{"command":"cd /workspace; cat > internal/jsonx/node.go <<'EOF'
package jsonx

// Kind describes the type of a JSON node.
type Kind int

const (
	KindNull Kind = iota
	KindBool
	KindNumber
	KindString
	KindObject
	KindArray
	KindNaN       // NaN, Infinity, -Infinity (non-standard numbers)
	KindUndefined // undefined
)

// Node is a parsed JSON value which keeps the raw textual representation
// of primitive values and object keys.
type Node struct {
	Kind     Kind
	Key      string // raw key including quotes (only for object members)
	HasKey   bool
	Value    string // raw token text for primitives
	Children []*Node
	Parent   *Node
	Index    int // index in parent

	// Slurp marks a synthetic top-level array created by --slurp.
	Slurp bool
}

func (n *Node) IsContainer() bool {
	return n.Kind == KindObject || n.Kind == KindArray
}

func (n *Node) IsPrimitive() bool {
	return !n.IsContainer()
}

// Len returns number of children.
func (n *Node) Len() int { return len(n.Children) }

func (n *Node) Append(child *Node) {
	child.Parent = n
	child.Index = len(n.Children)
	n.Children = append(n.Children, child)
}

// Clone makes a deep copy of the node.
func (n *Node) Clone() *Node {
	c := &Node{Kind: n.Kind, Key: n.Key, HasKey: n.HasKey, Value: n.Value, Slurp: n.Slurp}
	for _, ch := range n.Children {
		c.Append(ch.Clone())
	}
	return c
}

// Reindex recomputes indexes and parents of children.
func (n *Node) Reindex() {
	for i, ch := range n.Children {
		ch.Parent = n
		ch.Index = i
	}
}

// Size returns number of keys/items for containers.
func (n *Node) Size() int { return len(n.Children) }
EOF
cat > internal/jsonx/parser.go <<'EOF'
package jsonx

import (
	"fmt"
	"strings"
)

// ParseError is a syntax error with the line snippet already formatted.
type ParseError struct {
	Message string
	Line    int
	Snippet string
	Col     int
}

func (e *ParseError) Error() string {
	return fmt.Sprintf("%s on line %d.\n\n  %s\n  %s^\n", e.Message, e.Line, e.Snippet, strings.Repeat(".", e.Col))
}

// Parser is a streaming JSON parser working on in-memory data.
type Parser struct {
	data      []byte
	pos       int
	line      int
	lineStart int
	cur       byte
	Strict    bool
	eof       bool
}

func NewParser(data []byte, strict bool) *Parser {
	p := &Parser{data: data, line: 1, Strict: strict}
	if len(data) > 0 {
		p.cur = data[0]
		if p.cur == '\n' {
			p.line++
			p.lineStart = 1
		}
	} else {
		p.eof = true
	}
	return p
}

func (p *Parser) next() {
	if p.pos < len(p.data) {
		p.pos++
	}
	if p.pos < len(p.data) {
		p.cur = p.data[p.pos]
		if p.cur == '\n' {
			p.line++
			p.lineStart = p.pos + 1
		}
	} else {
		p.cur = 0
		p.eof = true
	}
}

// AtEOF reports whether all input has been consumed (ignoring whitespace).
func (p *Parser) AtEOF() bool {
	p.skipWhitespace()
	return p.pos >= len(p.data)
}

func (p *Parser) errorAt(pos int, msg string) *ParseError {
	// Build snippet of the current line.
	start := p.lineStart
	if start > len(p.data) {
		start = len(p.data)
	}
	end := start
	for end < len(p.data) && p.data[end] != '\n' {
		end++
	}
	lineText := string(p.data[start:end])
	col := pos - start
	if col > len(lineText)-1 {
		col = len(lineText) - 1
	}
	if col < 0 {
		col = 0
	}
	return &ParseError{Message: msg, Line: p.line, Snippet: lineText, Col: col}
}

func (p *Parser) errorf(format string, args ...interface{}) *ParseError {
	return p.errorAt(p.pos, fmt.Sprintf(format, args...))
}

func quoteChar(c byte) string {
	return fmt.Sprintf("%q", rune(c))
}

func isWhitespace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func (p *Parser) skipWhitespace() error {
	for {
		for isWhitespace(p.cur) && p.pos < len(p.data) {
			p.next()
		}
		if p.cur == '/' && p.pos < len(p.data) {
			if p.Strict {
				return p.errorf("Comments are not allowed in strict mode")
			}
			if err := p.skipComment(); err != nil {
				return err
			}
			continue
		}
		return nil
	}
}

func (p *Parser) skipComment() error {
	// p.cur == '/'
	p.next()
	switch p.cur {
	case '/':
		for p.pos < len(p.data) && p.cur != '\n' {
			p.next()
		}
		return nil
	case '*':
		p.next()
		for {
			if p.pos >= len(p.data) {
				return p.errorf("Unexpected end of input in comment")
			}
			if p.cur == '*' {
				p.next()
				if p.cur == '/' {
					p.next()
					return nil
				}
				continue
			}
			p.next()
		}
	default:
		return p.errorf("Invalid comment: '/%c'", p.cur)
	}
}

// Parse parses the next JSON value from the stream. Returns nil, nil at EOF.
func (p *Parser) Parse() (*Node, error) {
	if err := p.skipWhitespace(); err != nil {
		return nil, err
	}
	if p.pos >= len(p.data) {
		return nil, nil
	}
	return p.parseValue()
}

func (p *Parser) parseValue() (*Node, error) {
	if err := p.skipWhitespace(); err != nil {
		return nil, err
	}
	switch p.cur {
	case '{':
		return p.parseObject()
	case '[':
		return p.parseArray()
	case '"':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return &Node{Kind: KindString, Value: s}, nil
	case 't':
		return p.parseKeyword("true", KindBool)
	case 'f':
		return p.parseKeyword("false", KindBool)
	case 'u':
		if p.Strict {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		return p.parseKeyword("undefined", KindUndefined)
	case 'n':
		return p.parseExact("null", KindNull)
	case 'N':
		if p.Strict {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		return p.parseNaN("")
	case 'I', 'i':
		if p.Strict {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		return p.parseInfinity("")
	case '-':
		if !p.Strict && p.pos+1 < len(p.data) && (p.data[p.pos+1] == 'I' || p.data[p.pos+1] == 'i') {
			p.next()
			return p.parseInfinity("-")
		}
		return p.parseNumber()
	default:
		if p.cur >= '0' && p.cur <= '9' {
			return p.parseNumber()
		}
		return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
	}
}

func (p *Parser) parseKeyword(kw string, kind Kind) (*Node, error) {
	for i := 0; i < len(kw); i++ {
		if p.cur != kw[i] {
			return nil, p.errorf("Unexpected character %s in keyword", quoteChar(p.cur))
		}
		p.next()
	}
	return &Node{Kind: kind, Value: kw}, nil
}

func (p *Parser) parseExact(kw string, kind Kind) (*Node, error) {
	for i := 0; i < len(kw); i++ {
		if p.cur != kw[i] {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		p.next()
	}
	return &Node{Kind: kind, Value: kw}, nil
}

func lower(c byte) byte {
	if c >= 'A' && c <= 'Z' {
		return c + 32
	}
	return c
}

func (p *Parser) parseNaN(prefix string) (*Node, error) {
	start := p.pos
	for _, c := range []byte("nan") {
		if lower(p.cur) != c {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		p.next()
	}
	return &Node{Kind: KindNaN, Value: prefix + string(p.data[start:p.pos])}, nil
}

func (p *Parser) parseInfinity(prefix string) (*Node, error) {
	start := p.pos
	for _, c := range []byte("inf") {
		if lower(p.cur) != c {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		p.next()
	}
	if p.cur == 'i' {
		for _, c := range []byte("inity") {
			if p.cur != c {
				return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
			}
			p.next()
		}
	}
	return &Node{Kind: KindNaN, Value: prefix + string(p.data[start:p.pos])}, nil
}

func (p *Parser) parseNumber() (*Node, error) {
	start := p.pos
	if p.cur == '-' {
		p.next()
	}
	if p.cur == '0' {
		p.next()
	} else if p.cur >= '1' && p.cur <= '9' {
		for p.cur >= '0' && p.cur <= '9' {
			p.next()
		}
	} else {
		return nil, p.errorf("Invalid character %s in number", quoteChar(p.cur))
	}
	if p.cur == '.' {
		p.next()
		if !(p.cur >= '0' && p.cur <= '9') {
			return nil, p.errorf("Invalid character %s in number", quoteChar(p.cur))
		}
		for p.cur >= '0' && p.cur <= '9' {
			p.next()
		}
	}
	if p.cur == 'e' || p.cur == 'E' {
		p.next()
		if p.cur == '+' || p.cur == '-' {
			p.next()
		}
		if !(p.cur >= '0' && p.cur <= '9') {
			return nil, p.errorf("Invalid character %s in number", quoteChar(p.cur))
		}
		for p.cur >= '0' && p.cur <= '9' {
			p.next()
		}
	}
	return &Node{Kind: KindNumber, Value: string(p.data[start:p.pos])}, nil
}

func (p *Parser) parseString() (string, error) {
	start := p.pos
	p.next() // opening quote
	for {
		if p.pos >= len(p.data) {
			return "", p.errorf("Unexpected end of input in string")
		}
		switch p.cur {
		case '"':
			p.next()
			return string(p.data[start:p.pos]), nil
		case '\\':
			p.next()
			if p.pos >= len(p.data) {
				return "", p.errorf("Unexpected end of input in string")
			}
			p.next()
		default:
			p.next()
		}
	}
}

func (p *Parser) parseObject() (*Node, error) {
	node := &Node{Kind: KindObject}
	p.next() // {
	if err := p.skipWhitespace(); err != nil {
		return nil, err
	}
	if p.cur == '}' {
		p.next()
		return node, nil
	}
	for {
		if err := p.skipWhitespace(); err != nil {
			return nil, err
		}
		if p.cur != '"' {
			return nil, p.errorf("Expected object key to be a string, got %s", quoteChar(p.cur))
		}
		key, err := p.parseString()
		if err != nil {
			return nil, err
		}
		if err := p.skipWhitespace(); err != nil {
			return nil, err
		}
		if p.cur != ':' {
			return nil, p.errorf("Expected colon after object key, got %s", quoteChar(p.cur))
		}
		p.next()
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		val.Key = key
		val.HasKey = true
		node.Append(val)
		if err := p.skipWhitespace(); err != nil {
			return nil, err
		}
		switch p.cur {
		case ',':
			commaPos := p.pos
			p.next()
			if err := p.skipWhitespace(); err != nil {
				return nil, err
			}
			if p.cur == '}' {
				if p.Strict {
					return nil, p.errorAt(commaPos, "Trailing comma is not allowed in strict mode")
				}
				p.next()
				return node, nil
			}
		case '}':
			p.next()
			return node, nil
		default:
			return nil, p.errorf("Unexpected character %s in object", quoteChar(p.cur))
		}
	}
}

func (p *Parser) parseArray() (*Node, error) {
	node := &Node{Kind: KindArray}
	p.next() // [
	if err := p.skipWhitespace(); err != nil {
		return nil, err
	}
	if p.cur == ']' {
		p.next()
		return node, nil
	}
	for {
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		node.Append(val)
		if err := p.skipWhitespace(); err != nil {
			return nil, err
		}
		switch p.cur {
		case ',':
			commaPos := p.pos
			p.next()
			if err := p.skipWhitespace(); err != nil {
				return nil, err
			}
			if p.cur == ']' {
				if p.Strict {
					return nil, p.errorAt(commaPos, "Trailing comma is not allowed in strict mode")
				}
				p.next()
				return node, nil
			}
		case ']':
			p.next()
			return node, nil
		default:
			return nil, p.errorf("Invalid character %s in array", quoteChar(p.cur))
		}
	}
}

// ParseAll parses all values from data.
func ParseAll(data []byte, strict bool) ([]*Node, error) {
	p := NewParser(data, strict)
	var out []*Node
	for {
		n, err := p.Parse()
		if err != nil {
			return out, err
		}
		if n == nil {
			return out, nil
		}
		out = append(out, n)
	}
}
