// ParseError is a syntax error with the line snippet already formatted.
type ParseError struct {
	Message string
	Line    int
	Snippet string
	Col     int
}

func (e *ParseError) Error() string {
	return fmt.Sprintf("%s on line %d.\n\n  %s\n  %s^\n", e.Message, e.Line, e.Snippet, strings.Repeat(".", e.Col))
}

// Parser is a streaming JSON parser working on in-memory data.
type Parser struct {
	data      []byte
	pos       int
	line      int
	lineStart int
	cur       byte
	Strict    bool
	eof       bool
}

func NewParser(data []byte, strict bool) *Parser {
	p := &Parser{data: data, line: 1, Strict: strict}
	if len(data) > 0 {
		p.cur = data[0]
		if p.cur == '\n' {
			p.line++
			p.lineStart = 1
		}
	} else {
		p.eof = true
	}
	return p
}

func (p *Parser) next() {
	if p.pos < len(p.data) {
		p.pos++
	}
	if p.pos < len(p.data) {
		p.cur = p.data[p.pos]
		if p.cur == '\n' {
			p.line++
			p.lineStart = p.pos + 1
		}
	} else {
		p.cur = 0
		p.eof = true
	}
}

// AtEOF reports whether all input has been consumed (ignoring whitespace).
func (p *Parser) AtEOF() bool {
	p.skipWhitespace()
	return p.pos >= len(p.data)
}

func (p *Parser) errorAt(pos int, msg string) *ParseError {
	// Build snippet of the current line.
	start := p.lineStart
	if start > len(p.data) {
		start = len(p.data)
	}
	end := start
	for end < len(p.data) && p.data[end] != '\n' {
		end++
	}
	lineText := string(p.data[start:end])
	col := pos - start
	if col > len(lineText)-1 {
		col = len(lineText) - 1
	}
	if col < 0 {
		col = 0
	}
	return &ParseError{Message: msg, Line: p.line, Snippet: lineText, Col: col}
}

func (p *Parser) errorf(format string, args ...interface{}) *ParseError {
	return p.errorAt(p.pos, fmt.Sprintf(format, args...))
}

func quoteChar(c byte) string {
	return fmt.Sprintf("%q", rune(c))
}

func isWhitespace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func (p *Parser) skipWhitespace() error {
	for {
		for isWhitespace(p.cur) && p.pos < len(p.data) {
			p.next()
		}
		if p.cur == '/' && p.pos < len(p.data) {
			if p.Strict {
				return p.errorf("Comments are not allowed in strict mode")
			}
			if err := p.skipComment(); err != nil {
				return err
			}
			continue
		}
		return nil
	}
}

func (p *Parser) skipComment() error {
	// p.cur == '/'
	p.next()
	switch p.cur {
	case '/':
		for p.pos < len(p.data) && p.cur != '\n' {
			p.next()
		}
		return nil
	case '*':
		p.next()
		for {
			if p.pos >= len(p.data) {
				return p.errorf("Unexpected end of input in comment")
			}
			if p.cur == '*' {
				p.next()
				if p.cur == '/' {
					p.next()
					return nil
				}
				continue
			}
			p.next()
		}
	default:
		return p.errorf("Invalid comment: '/%c'", p.cur)
	}
}

// Parse parses the next JSON value from the stream. Returns nil, nil at EOF.
func (p *Parser) Parse() (*Node, error) {
	if err := p.skipWhitespace(); err != nil {
		return nil, err
	}
	if p.pos >= len(p.data) {
		return nil, nil
	}
	return p.parseValue()
}

func (p *Parser) parseValue() (*Node, error) {
	if err := p.skipWhitespace(); err != nil {
		return nil, err
	}
	switch p.cur {
	case '{':
		return p.parseObject()
	case '[':
		return p.parseArray()
	case '"':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
