		return p.parseExact("null", KindNull)
	case 'N':
		if p.Strict {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		return p.parseNaN("")
	case 'I', 'i':
		if p.Strict {
			return nil, p.errorf("Unexpected character %s", quoteChar(p.cur))
		}
		return p.parseInfinity("")
	case '-':
		if !p.Strict && p.pos+1 < len(p.data) && (p.data[p.pos+1] == 'I' || p.data[p.pos+1] == 'i') {
			p.next()
			return p.parseInfinity("-")
