package jsonx

import (
	"strings"

	"fx/internal/theme"
)

// Printer renders nodes as indented JSON text.
type Printer struct {
	Theme  theme.Theme
	Inline bool
}

const inlineWidth = 80

func isNumberKind(n *Node) bool { return n.Kind == KindNumber }

// isNumberArray reports whether n is a non-empty array of plain numbers.
func isNumberArray(n *Node) bool {
	if n.Kind != KindArray || len(n.Children) == 0 {
		return false
	}
	for _, c := range n.Children {
		if !isNumberKind(c) {
			return false
		}
	}
	return true
}

// objectInlinable reports whether an object element of an array can be
// rendered on a single line.
func objectInlinable(n *Node) bool {
	if n.Kind != KindObject {
		return false
	}
	for _, c := range n.Children {
		if c.IsContainer() {
			return false
		}
	}
	if len(n.Children) == 1 {
		c := n.Children[0]
		if c.Kind == KindString && len(c.Key)+len(c.Value) <= inlineWidth {
			return true
		}
	}
	strs, others := 0, 0
	for _, c := range n.Children {
		if len(c.Key) > 10 {
			return false
		}
		if c.Kind == KindString {
			if len(c.Value) > 20 {
				return false
			}
			strs++
		} else {
			others++
		}
	}
	return strs <= 2 && others <= 3
}

// arrayValueInlinable reports whether an array that is a value of an object
// member can be rendered on a single line.
func arrayValueInlinable(n *Node) bool {
	if isNumberArray(n) {
		return true
	}
	if len(n.Children) == 1 {
		c := n.Children[0]
		if c.IsPrimitive() && len(c.Value) <= inlineWidth {
			return true
		}
	}
	return false
}

// elementsInline decides whether children of an array should be inlined.
func elementsInline(n *Node) bool {
	if len(n.Children) == 0 {
		return false
	}
	first := n.Children[0]
	switch first.Kind {
	case KindObject:
		for _, c := range n.Children {
			if !objectInlinable(c) {
				return false
			}
		}
		return true
	case KindArray:
		for _, c := range n.Children {
			if !isNumberArray(c) {
				return false
			}
		}
		return true
	}
	return false
}

func (p *Printer) syntax(s string) string { return p.Theme.Syntax.Render(s) }

func (p *Printer) primitive(n *Node) string {
	switch n.Kind {
	case KindString:
		return p.Theme.String.Render(n.Value)
	case KindNumber:
		return p.Theme.Number.Render(n.Value)
	case KindBool:
		return p.Theme.Boolean.Render(n.Value)
	case KindNull:
		return p.Theme.Null.Render(n.Value)
	case KindNaN, KindUndefined:
		return theme.Style{Codes: "38;5;255;48;5;196"}.Render(n.Value)
	}
	return n.Value
}

func (p *Printer) key(n *Node) string {
	return p.Theme.Key.Render(n.Key) + p.syntax(": ")
}

// String renders the node (top-level).
func (p *Printer) String(n *Node) string {
	var b strings.Builder
	if n.Slurp {
		// Synthetic slurp array: children are rendered as top-level values.
		b.WriteString(p.syntax("["))
		b.WriteString("\n")
		for i, c := range n.Children {
			b.WriteString("  ")
			p.write(&b, c, "  ", false)
			if i < len(n.Children)-1 {
				b.WriteString(p.syntax(","))
			}
			b.WriteString("\n")
		}
		b.WriteString(p.syntax("]"))
		return b.String()
	}
	p.write(&b, n, "", false)
	return b.String()
}

func (p *Printer) write(b *strings.Builder, n *Node, indent string, inline bool) {
	switch n.Kind {
	case KindObject:
		if len(n.Children) == 0 {
			b.WriteString(p.syntax("{}"))
			return
		}
		if inline {
			b.WriteString(p.syntax("{"))
			b.WriteString(" ")
			for i, c := range n.Children {
				b.WriteString(p.key(c))
				b.WriteString(p.primitive(c))
				if i < len(n.Children)-1 {
					b.WriteString(p.syntax(","))
					b.WriteString(" ")
				}
			}
			b.WriteString(" ")
			b.WriteString(p.syntax("}"))
			return
		}
		b.WriteString(p.syntax("{"))
		b.WriteString("\n")
		childIndent := indent + "  "
		for i, c := range n.Children {
			b.WriteString(childIndent)
			b.WriteString(p.key(c))
			if c.Kind == KindArray && p.Inline && arrayValueInlinable(c) {
				p.writeInlineArray(b, c)
			} else {
				p.write(b, c, childIndent, false)
			}
			if i < len(n.Children)-1 {
				b.WriteString(p.syntax(","))
			}
			b.WriteString("\n")
		}
		b.WriteString(indent)
		b.WriteString(p.syntax("}"))
	case KindArray:
		if len(n.Children) == 0 {
			b.WriteString(p.syntax("[]"))
			return
		}
		if inline {
			p.writeInlineArray(b, n)
			return
		}
		b.WriteString(p.syntax("["))
		b.WriteString("\n")
		childIndent := indent + "  "
		inl := p.Inline && elementsInline(n)
		for i, c := range n.Children {
			b.WriteString(childIndent)
			p.write(b, c, childIndent, inl)
			if i < len(n.Children)-1 {
				b.WriteString(p.syntax(","))
			}
			b.WriteString("\n")
		}
		b.WriteString(indent)
		b.WriteString(p.syntax("]"))
	default:
		b.WriteString(p.primitive(n))
	}
}

func (p *Printer) writeInlineArray(b *strings.Builder, n *Node) {
	if len(n.Children) == 0 {
		b.WriteString(p.syntax("[]"))
		return
	}
	b.WriteString(p.syntax("["))
	b.WriteString(" ")
	for i, c := range n.Children {
		b.WriteString(p.primitive(c))
		if i < len(n.Children)-1 {
			b.WriteString(p.syntax(","))
			b.WriteString(" ")
		}
	}
	b.WriteString(" ")
	b.WriteString(p.syntax("]"))
}

// Compact renders node as compact JSON (no whitespace), unstyled.
func Compact(n *Node) string {
	var b strings.Builder
	compact(&b, n)
	return b.String()
}

func compact(b *strings.Builder, n *Node) {
	switch n.Kind {
	case KindObject:
		b.WriteByte('{')
		for i, c := range n.Children {
			if i > 0 {
				b.WriteByte(',')
			}
			b.WriteString(c.Key)
			b.WriteByte(':')
			compact(b, c)
		}
		b.WriteByte('}')
	case KindArray:
		b.WriteByte('[')
		for i, c := range n.Children {
			if i > 0 {
				b.WriteByte(',')
			}
			compact(b, c)
		}
		b.WriteByte(']')
	default:
		b.WriteString(n.Value)
	}
}

// Indented renders node as 2-space indented JSON without inlining or colors.
func Indented(n *Node) string {
	p := Printer{Theme: theme.Themes["0"], Inline: false}
	return p.String(n)
}
EOF
echo ok"}

