package input

import (
	"encoding/base64"
	"fmt"
	"math"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// YAMLToJSON converts all YAML documents in data into JSON texts.
func YAMLToJSON(data []byte) ([]string, error) {
	var docs []string
	dec := yaml.NewDecoder(strings.NewReader(string(data)))
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err != nil {
			if err.Error() == "EOF" {
				break
			}
			return docs, fmt.Errorf("%s", strings.TrimPrefix(err.Error(), "yaml: "))
		}
		var b strings.Builder
		if err := yamlNodeToJSON(&b, &node, map[*yaml.Node]bool{}); err != nil {
			return docs, err
		}
		docs = append(docs, b.String())
	}
	return docs, nil
}

func yamlNodeToJSON(b *strings.Builder, n *yaml.Node, seen map[*yaml.Node]bool) error {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil
		}
		return yamlNodeToJSON(b, n.Content[0], seen)
	case yaml.MappingNode:
		b.WriteByte('{')
		for i := 0; i+1 < len(n.Content); i += 2 {
			if i > 0 {
				b.WriteString(", ")
			}
			k := n.Content[i]
			key := yamlScalarString(k)
			b.WriteString(QuoteJSON(key))
			b.WriteString(": ")
			if err := yamlNodeToJSON(b, n.Content[i+1], seen); err != nil {
				return err
			}
		}
		b.WriteByte('}')
	case yaml.SequenceNode:
		b.WriteByte('[')
		for i, c := range n.Content {
			if i > 0 {
				b.WriteString(", ")
			}
			if err := yamlNodeToJSON(b, c, seen); err != nil {
				return err
			}
		}
		b.WriteByte(']')
	case yaml.AliasNode:
		if n.Alias == nil {
			b.WriteString("null")
			return nil
		}
		if seen[n.Alias] {
			return fmt.Errorf("anchor cycle detected")
		}
		seen[n.Alias] = true
		err := yamlNodeToJSON(b, n.Alias, seen)
		delete(seen, n.Alias)
		return err
	case yaml.ScalarNode:
		b.WriteString(yamlScalarJSON(n))
	}
	return nil
}

func yamlScalarString(n *yaml.Node) string {
	if n.Kind == yaml.AliasNode && n.Alias != nil {
		return yamlScalarString(n.Alias)
	}
	if n.Kind != yaml.ScalarNode {
		return n.Value
	}
	switch n.ShortTag() {
	case "!!null":
		return "null"
	}
	return n.Value
}

func yamlScalarJSON(n *yaml.Node) string {
	tag := n.ShortTag()
	switch tag {
	case "!!str":
		return QuoteJSON(n.Value)
	case "!!null":
		return "null"
	case "!!bool":
		var v bool
		if err := n.Decode(&v); err == nil {
			if v {
				return "true"
			}
			return "false"
		}
		return QuoteJSON(n.Value)
	case "!!int":
		var v int64
		if err := n.Decode(&v); err == nil {
			return strconv.FormatInt(v, 10)
		}
		var u uint64
		if err := n.Decode(&u); err == nil {
			return strconv.FormatUint(u, 10)
		}
		return QuoteJSON(n.Value)
	case "!!float":
		var v float64
		if err := n.Decode(&v); err == nil {
			if math.IsInf(v, 1) {
				return ".inf"
			}
			if math.IsInf(v, -1) {
				return "-.inf"
			}
			if math.IsNaN(v) {
				return ".nan"
			}
			if v == math.Trunc(v) && math.Abs(v) < 1e21 {
				return strconv.FormatFloat(v, 'f', -1, 64)
			}
			return strconv.FormatFloat(v, 'g', -1, 64)
		}
		return QuoteJSON(n.Value)
	case "!!timestamp":
		return QuoteJSON(n.Value)
	case "!!binary":
		raw, err := base64.StdEncoding.DecodeString(strings.Join(strings.Fields(n.Value), ""))
		if err != nil {
			return QuoteJSON(n.Value)
		}
		parts := make([]string, len(raw))
		for i, c := range raw {
			parts[i] = strconv.Itoa(int(c))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	}
	return QuoteJSON(n.Value)
}

// YAMLStringify renders a generic value (maps/slices/scalars) as YAML text.
func YAMLStringify(v interface{}) string {
	var b strings.Builder
	yamlWrite(&b, v, 0, false)
	return b.String()
}

type OrderedMap struct {
	Keys   []string
	Values map[string]interface{}
}

func yamlScalar(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case bool:
		if t {
			return "true"
		}
		return "false"
	case string:
		return yamlQuote(t)
	case float64:
		if math.IsInf(t, 1) {
			return ".inf"
		}
		if math.IsInf(t, -1) {
			return "-.inf"
		}
		if math.IsNaN(t) {
			return ".nan"
		}
		if t == math.Trunc(t) && math.Abs(t) < 1e21 {
			return strconv.FormatFloat(t, 'f', -1, 64)
		}
		return strconv.FormatFloat(t, 'g', -1, 64)
	case int64:
		return strconv.FormatInt(t, 10)
	case int:
		return strconv.Itoa(t)
	}
	return fmt.Sprint(v)
}

func yamlQuote(s string) string {
	if s == "" {
		return `""`
	}
	needs := false
	switch strings.ToLower(s) {
	case "null", "~", "true", "false", "yes", "no", "on", "off", ".inf", "-.inf", ".nan":
		needs = true
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		needs = true
	}
	if !needs {
		for i, r := range s {
			if r == '\n' || r == '\t' || r == '"' || r == '\'' || r == '\\' || r == '#' || r == ':' && (i+1 == len(s) || s[i+1] == ' ') || r == '{' || r == '}' || r == '[' || r == ']' || r == ',' || r == '&' || r == '*' || r == '!' || r == '|' || r == '>' || r == '%' || r == '@' || r == '`' {
				needs = true
				break
			}
			if i == 0 && (r == '-' || r == '?' || r == ' ') {
				needs = true
				break
			}
		}
		if strings.HasSuffix(s, " ") {
			needs = true
		}
	}
	if !needs {
		return s
	}
	return QuoteJSON(s)
}

func yamlWrite(b *strings.Builder, v interface{}, indent int, inSeq bool) {
	pad := strings.Repeat("  ", indent)
	switch t := v.(type) {
	case *OrderedMap:
		if len(t.Keys) == 0 {
			b.WriteString("{}\n")
			return
		}
		for i, k := range t.Keys {
			if !(i == 0 && inSeq) {
				b.WriteString(pad)
			}
			b.WriteString(yamlQuote(k))
			b.WriteString(":")
			val := t.Values[k]
			switch vt := val.(type) {
			case *OrderedMap:
				if len(vt.Keys) == 0 {
					b.WriteString(" {}\n")
				} else {
					b.WriteString("\n")
					yamlWrite(b, vt, indent+1, false)
				}
			case []interface{}:
				if len(vt) == 0 {
					b.WriteString(" []\n")
				} else {
					b.WriteString("\n")
					yamlWrite(b, vt, indent, false)
				}
			default:
				b.WriteString(" ")
				b.WriteString(yamlScalar(val))
				b.WriteString("\n")
			}
		}
	case []interface{}:
		if len(t) == 0 {
			b.WriteString("[]\n")
			return
		}
		for _, item := range t {
			b.WriteString(pad)
			b.WriteString("- ")
			switch it := item.(type) {
			case *OrderedMap:
				if len(it.Keys) == 0 {
					b.WriteString("{}\n")
				} else {
					yamlWrite(b, it, indent+1, true)
				}
			case []interface{}:
				if len(it) == 0 {
					b.WriteString("[]\n")
				} else {
					b.WriteString("\n")
					yamlWrite(b, it, indent+1, false)
				}
			default:
				b.WriteString(yamlScalar(item))
				b.WriteString("\n")
			}
		}
	default:
		b.WriteString(yamlScalar(v))
		b.WriteString("\n")
	}
}
