						return out, e
					}
				}
				if err != nil {
					return out, err
				}
			}
		}
		return out, nil
	} else if s.TOML {
		j, err := TOMLToJSON(s.Data)
		if err != nil {
			return out, err
		}
		data = []byte(j)
	} else {
		data = s.Data
	}
	p := jsonx.NewParser(data, s.Strict)
	for !p.EOF() {
		n, err := p.Parse()
		if n != nil {
			if e := emit(n); e != nil {
				return out, e
			}
		}
		if err != nil {
			return out, err
		}
	}
	return out, nil
}
