package input

import (
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
)

// TOMLToJSON converts TOML data to a JSON text.
func TOMLToJSON(data []byte) (string, error) {
	var v map[string]interface{}
	md, err := toml.Decode(string(data), &v)
	if err != nil {
		return "", fmt.Errorf("panic: ([]uint8) %s", err.Error())
	}
	order := map[string]int{}
	for i, k := range md.Keys() {
		order[k.String()] = i
	}
	var b strings.Builder
	tomlValue(&b, v, nil, order)
	return b.String(), nil
}

func tomlValue(b *strings.Builder, v interface{}, path []string, order map[string]int) {
	switch t := v.(type) {
	case map[string]interface{}:
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.SliceStable(keys, func(i, j int) bool {
			pi := strings.Join(append(append([]string{}, path...), keys[i]), ".")
			pj := strings.Join(append(append([]string{}, path...), keys[j]), ".")
			oi, oki := order[pi]
			oj, okj := order[pj]
			if oki && okj {
				return oi < oj
			}
			if oki != okj {
				return oki
			}
			return keys[i] < keys[j]
		})
		b.WriteByte('{')
		for i, k := range keys {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(QuoteJSON(k))
			b.WriteString(": ")
			tomlValue(b, t[k], append(append([]string{}, path...), k), order)
		}
		b.WriteByte('}')
	case []map[string]interface{}:
		b.WriteByte('[')
		for i, m := range t {
			if i > 0 {
				b.WriteString(", ")
			}
			tomlValue(b, m, path, order)
		}
		b.WriteByte(']')
	case []interface{}:
		b.WriteByte('[')
		for i, m := range t {
			if i > 0 {
				b.WriteString(", ")
			}
			tomlValue(b, m, path, order)
		}
		b.WriteByte(']')
	case string:
		b.WriteString(QuoteJSON(t))
	case int64:
		b.WriteString(strconv.FormatInt(t, 10))
	case float64:
		if math.IsInf(t, 0) || math.IsNaN(t) {
			b.WriteString(QuoteJSON(strconv.FormatFloat(t, 'g', -1, 64)))
		} else if t == math.Trunc(t) && math.Abs(t) < 1e21 {
			b.WriteString(strconv.FormatFloat(t, 'f', -1, 64))
		} else {
			b.WriteString(strconv.FormatFloat(t, 'g', -1, 64))
		}
	case bool:
		if t {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case time.Time:
		b.WriteString(QuoteJSON(t.Format(time.RFC3339Nano)))
	case toml.Primitive:
		b.WriteString("null")
	case nil:
		b.WriteString("null")
	default:
		b.WriteString(QuoteJSON(fmt.Sprint(t)))
	}
}
