package js

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type TokType int

const (
	TEOF TokType = iota
	TIdent
	TKeyword
	TNumber
	TBigInt
	TString
	TTemplate
	TRegex
	TPunct
	TPrivate
	TIllegal
)

type Token struct {
	Type          TokType
	Value         string // raw text for ident/keyword/punct; cooked value for string
	Raw           string
	Num           float64
	Pos           int
	End           int
	Line          int
	Col           int
	NewlineBefore bool
	// template literal parts
	Quasis   []string // cooked
	RawParts []string
	Exprs    [][]Token
	// regex
	Pattern string
	Flags   string
}

var keywords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true, "continue": true,
	"debugger": true, "default": true, "delete": true, "do": true, "else": true, "export": true,
	"extends": true, "finally": true, "for": true, "function": true, "if": true, "import": true,
	"in": true, "instanceof": true, "new": true, "return": true, "super": true, "switch": true,
	"this": true, "throw": true, "try": true, "typeof": true, "var": true, "void": true,
	"while": true, "with": true, "null": true, "true": true, "false": true, "enum": true,
}

// strictReserved are reserved only in strict mode.
var strictReserved = map[string]bool{
	"implements": true, "interface": true, "let": true, "package": true, "private": true,
	"protected": true, "public": true, "static": true, "yield": true,
}

type SyntaxError struct {
	Message string
	Pos     int
	Line    int
	Col     int
	Kind    string // "parser" or "compiler"
}

func (e *SyntaxError) Error() string { return e.Message }

type lexer struct {
	src    []rune
	pos    int
	line   int
	col    int
	tokens []Token
	// previous significant token to decide regex vs division
	lastSig *Token
	err     *SyntaxError
}

func isIDStart(r rune) bool {
	return r == '$' || r == '_' || unicode.IsLetter(r) || r == '\\'
}

func isIDPart(r rune) bool {
	return r == '$' || r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\u200c' || r == '\u200d' || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Pc, r)
}

func isLineTerm(r rune) bool { return r == '\n' || r == '\r' || r == '\u2028' || r == '\u2029' }

func isSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\v' || r == '\f' || r == 0xA0 || r == 0xFEFF || unicode.Is(unicode.Zs, r)
}

// Lex tokenizes source. If stopAtBrace is true, lexing stops at an unmatched '}'
// and returns the position after it.
func lexTokens(src []rune, start int, line, col int, stopAtBrace bool) ([]Token, int, int, int, *SyntaxError) {
	lx := &lexer{src: src, pos: start, line: line, col: col}
	depth := 0
	newline := false
	for {
		// skip whitespace and comments
		for lx.pos < len(lx.src) {
			r := lx.src[lx.pos]
			if isLineTerm(r) {
				newline = true
				lx.advance()
				continue
			}
			if isSpace(r) {
				lx.advance()
				continue
			}
			if r == '/' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] == '/' {
				for lx.pos < len(lx.src) && !isLineTerm(lx.src[lx.pos]) {
					lx.advance()
				}
				continue
			}
			if r == '/' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] == '*' {
				lx.advance()
				lx.advance()
				closed := false
				for lx.pos < len(lx.src) {
					if lx.src[lx.pos] == '*' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] == '/' {
						lx.advance()
						lx.advance()
						closed = true
						break
					}
					if isLineTerm(lx.src[lx.pos]) {
						newline = true
					}
					lx.advance()
				}
				if !closed {
					return nil, 0, 0, 0, &SyntaxError{Message: "Unexpected token ILLEGAL", Pos: lx.pos, Line: lx.line, Col: lx.col}
				}
				continue
			}
			break
		}
		if lx.pos >= len(lx.src) {
			lx.tokens = append(lx.tokens, Token{Type: TEOF, Pos: lx.pos, End: lx.pos, Line: lx.line, Col: lx.col, NewlineBefore: newline})
			return lx.tokens, lx.pos, lx.line, lx.col, nil
		}
		if stopAtBrace && lx.src[lx.pos] == '}' && depth == 0 {
			lx.tokens = append(lx.tokens, Token{Type: TEOF, Pos: lx.pos, End: lx.pos, Line: lx.line, Col: lx.col, NewlineBefore: newline})
			lx.advance()
			return lx.tokens, lx.pos, lx.line, lx.col, nil
		}
		tok, err := lx.next()
		if err != nil {
			return nil, 0, 0, 0, err
		}
		tok.NewlineBefore = newline
		newline = false
		if tok.Type == TPunct {
			switch tok.Value {
			case "{":
				depth++
			case "}":
				depth--
			}
		}
		lx.tokens = append(lx.tokens, tok)
		lx.lastSig = &lx.tokens[len(lx.tokens)-1]
	}
}

func (lx *lexer) advance() {
	if lx.pos < len(lx.src) {
		if lx.src[lx.pos] == '\n' {
			lx.line++
			lx.col = 1
		} else {
			lx.col++
		}
		lx.pos++
	}
}

func (lx *lexer) peek(off int) rune {
	if lx.pos+off < len(lx.src) {
		return lx.src[lx.pos+off]
	}
	return -1
}

func (lx *lexer) illegal() *SyntaxError {
	return &SyntaxError{Message: "Unexpected token ILLEGAL", Pos: lx.pos, Line: lx.line, Col: lx.col}
}

func (lx *lexer) regexAllowed() bool {
	t := lx.lastSig
	if t == nil {
		return true
	}
	switch t.Type {
	case TNumber, TBigInt, TString, TTemplate, TRegex:
		return false
	case TIdent:
		return false
	case TKeyword:
		switch t.Value {
		case "this", "super", "null", "true", "false":
			return false
		}
		return true
	case TPunct:
		switch t.Value {
		case ")", "]", "}":
			return false
		}
		return true
	}
	return true
}

func (lx *lexer) next() (Token, *SyntaxError) {
	start := lx.pos
	line, col := lx.line, lx.col
	r := lx.src[lx.pos]
	mk := func(t TokType, v string) Token {
		return Token{Type: t, Value: v, Raw: string(lx.src[start:lx.pos]), Pos: start, End: lx.pos, Line: line, Col: col}
	}
	switch {
	case isIDStart(r):
		name, err := lx.readIdent()
		if err != nil {
			return Token{}, err
		}
		if keywords[name] {
			return mk(TKeyword, name), nil
		}
		return mk(TIdent, name), nil
	case r >= '0' && r <= '9' || (r == '.' && lx.peek(1) >= '0' && lx.peek(1) <= '9'):
		return lx.readNumber(start, line, col)
	case r == '"' || r == '\'':
		s, err := lx.readString(r)
		if err != nil {
			return Token{}, err
		}
		t := mk(TString, s)
		return t, nil
	case r == '`':
		return lx.readTemplate(start, line, col)
	case r == '#':
		lx.advance()
		name, err := lx.readIdent()
		if err != nil {
			return Token{}, err
		}
		return mk(TPrivate, name), nil
	case r == '/':
		if lx.regexAllowed() {
			return lx.readRegex(start, line, col)
		}
	}
	// punctuators
	puncts := []string{
		">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=",
		"=>", "==", "!=", "<=", ">=", "&&", "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "**",
		"{", "}", "(", ")", "[", "]", ";", ",", "<", ">", "+", "-", "*", "/", "%", "&", "|", "^", "!", "~", "?", ":", "=", ".", "@",
	}
	rest := lx.src[lx.pos:]
	for _, p := range puncts {
		pr := []rune(p)
		if len(rest) >= len(pr) {
			match := true
			for i, c := range pr {
				if rest[i] != c {
					match = false
					break
				}
			}
			if match {
				// `?.` followed by a digit is a conditional operator
				if p == "?." && len(rest) > 2 && rest[2] >= '0' && rest[2] <= '9' {
					continue
				}
				for range pr {
					lx.advance()
				}
				return mk(TPunct, p), nil
			}
		}
	}
	return Token{}, lx.illegal()
}

func (lx *lexer) readIdent() (string, *SyntaxError) {
	var b strings.Builder
	for lx.pos < len(lx.src) {
		r := lx.src[lx.pos]
		if r == '\\' {
			// unicode escape in identifier
			if lx.peek(1) != 'u' {
				return "", lx.illegal()
			}
			lx.advance()
			lx.advance()
			cp, ok := lx.readUnicodeEscapeBody()
			if !ok {
				return "", lx.illegal()
			}
			b.WriteRune(cp)
			continue
		}
		if b.Len() == 0 {
			if !isIDStart(r) {
				break
			}
		} else if !isIDPart(r) {
			break
		}
		b.WriteRune(r)
		lx.advance()
	}
	return b.String(), nil
}

func (lx *lexer) readUnicodeEscapeBody() (rune, bool) {
	if lx.peek(0) == '{' {
		lx.advance()
		var v rune
		n := 0
		for lx.pos < len(lx.src) && lx.src[lx.pos] != '}' {
			d, ok := hexVal(lx.src[lx.pos])
			if !ok {
				return 0, false
			}
			v = v*16 + rune(d)
			n++
			lx.advance()
			if v > 0x10FFFF {
				return 0, false
			}
		}
		if lx.pos >= len(lx.src) || n == 0 {
			return 0, false
		}
		lx.advance()
		return v, true
	}
	var v rune
	for i := 0; i < 4; i++ {
		d, ok := hexVal(lx.peek(0))
		if !ok {
			return 0, false
		}
		v = v*16 + rune(d)
		lx.advance()
	}
	return v, true
}

func hexVal(r rune) (int, bool) {
	switch {
	case r >= '0' && r <= '9':
		return int(r - '0'), true
	case r >= 'a' && r <= 'f':
		return int(r-'a') + 10, true
	case r >= 'A' && r <= 'F':
		return int(r-'A') + 10, true
	}
	return 0, false
}

func (lx *lexer) readNumber(start, line, col int) (Token, *SyntaxError) {
	isDigit := func(r rune) bool { return r >= '0' && r <= '9' }
	r := lx.src[lx.pos]
	raw := func() string { return string(lx.src[start:lx.pos]) }
	mk := func(t TokType, num float64) Token {
		return Token{Type: t, Value: raw(), Raw: raw(), Num: num, Pos: start, End: lx.pos, Line: line, Col: col}
	}
	if r == '0' && (lx.peek(1) == 'x' || lx.peek(1) == 'X' || lx.peek(1) == 'o' || lx.peek(1) == 'O' || lx.peek(1) == 'b' || lx.peek(1) == 'B') {
		base := 16
		switch lx.peek(1) {
		case 'o', 'O':
			base = 8
		case 'b', 'B':
			base = 2
		}
		lx.advance()
		lx.advance()
		digits := ""
		for lx.pos < len(lx.src) {
			c := lx.src[lx.pos]
			if c == '_' {
				lx.advance()
				continue
			}
			d, ok := hexVal(c)
			if !ok || d >= base {
				break
			}
			digits += string(c)
			lx.advance()
		}
		if digits == "" {
			return Token{}, lx.illegal()
		}
		if lx.peek(0) == 'n' {
			lx.advance()
			t := mk(TBigInt, 0)
			t.Value = strconv.Itoa(base) + ":" + digits
			return t, nil
		}
		if isIDStart(lx.peek(0)) || isDigit(lx.peek(0)) {
			return Token{}, lx.illegal()
		}
		v, _ := strconv.ParseUint(digits, base, 64)
		f := float64(v)
		if len(digits) > 13 {
			// may exceed uint64 precision; use big parsing
			f = parseBigDigits(digits, base)
		}
		return mk(TNumber, f), nil
	}
	// legacy octal / decimal
	legacyOctal := false
	if r == '0' && isDigit(lx.peek(1)) {
		legacyOctal = true
		for lx.pos < len(lx.src) && isDigit(lx.src[lx.pos]) {
			if lx.src[lx.pos] >= '8' {
				legacyOctal = false
			}
			lx.advance()
		}
		s := raw()
		if legacyOctal {
			v, _ := strconv.ParseUint(s[1:], 8, 64)
			t := mk(TNumber, float64(v))
			t.Flags = "legacy-octal"
			return t, nil
		}
		// decimal with leading zero (e.g. 089)
		v, _ := strconv.ParseFloat(s, 64)
		t := mk(TNumber, v)
		t.Flags = "legacy-octal"
		return t, nil
	}
	intPart := ""
	for lx.pos < len(lx.src) && (isDigit(lx.src[lx.pos]) || lx.src[lx.pos] == '_') {
		if lx.src[lx.pos] != '_' {
			intPart += string(lx.src[lx.pos])
		}
		lx.advance()
	}
	isInt := true
	frac := ""
	if lx.peek(0) == '.' {
		isInt = false
		lx.advance()
		for lx.pos < len(lx.src) && (isDigit(lx.src[lx.pos]) || lx.src[lx.pos] == '_') {
			if lx.src[lx.pos] != '_' {
				frac += string(lx.src[lx.pos])
			}
			lx.advance()
		}
	}
	exp := ""
	if lx.peek(0) == 'e' || lx.peek(0) == 'E' {
		isInt = false
		lx.advance()
		if lx.peek(0) == '+' || lx.peek(0) == '-' {
			exp += string(lx.peek(0))
			lx.advance()
		}
		if !isDigit(lx.peek(0)) {
			return Token{}, lx.illegal()
		}
		for lx.pos < len(lx.src) && isDigit(lx.src[lx.pos]) {
			exp += string(lx.src[lx.pos])
			lx.advance()
		}
	}
	if isInt && lx.peek(0) == 'n' {
		lx.advance()
		t := mk(TBigInt, 0)
		t.Value = "10:" + intPart
		return t, nil
	}
	if isIDStart(lx.peek(0)) || isDigit(lx.peek(0)) {
		return Token{}, lx.illegal()
	}
	num := intPart
	if frac != "" || !isInt {
		if frac != "" {
			num += "." + frac
		}
		if exp != "" {
			num += "e" + exp
		}
	}
	if num == "" || num == "." {
		num = "0"
	}
	v, err := strconv.ParseFloat(num, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			// v is ±Inf or 0 already
		} else {
			v = 0
		}
	}
	return mk(TNumber, v), nil
}

func parseBigDigits(digits string, base int) float64 {
	f := 0.0
	for _, c := range digits {
		d, _ := hexVal(c)
		f = f*float64(base) + float64(d)
	}
	return f
}

func (lx *lexer) readString(quote rune) (string, *SyntaxError) {
	lx.advance()
	var b strings.Builder
	for {
		if lx.pos >= len(lx.src) {
			return "", lx.illegal()
		}
		r := lx.src[lx.pos]
		if r == quote {
			lx.advance()
			return b.String(), nil
		}
		if r == '\n' || r == '\r' {
			return "", lx.illegal()
		}
		if r == '\\' {
			lx.advance()
			if lx.pos >= len(lx.src) {
				return "", lx.illegal()
			}
			e := lx.src[lx.pos]
			switch e {
			case 'n':
				b.WriteRune('\n')
				lx.advance()
			case 't':
				b.WriteRune('\t')
				lx.advance()
			case 'r':
				b.WriteRune('\r')
				lx.advance()
			case 'b':
				b.WriteRune('\b')
				lx.advance()
			case 'f':
				b.WriteRune('\f')
				lx.advance()
			case 'v':
				b.WriteRune('\v')
				lx.advance()
			case '0':
				if !(lx.peek(1) >= '0' && lx.peek(1) <= '9') {
					b.WriteRune(0)
					lx.advance()
					break
				}
				fallthrough
			case '1', '2', '3', '4', '5', '6', '7':
				// legacy octal escape
				v := 0
				n := 0
				for n < 3 && lx.pos < len(lx.src) && lx.src[lx.pos] >= '0' && lx.src[lx.pos] <= '7' {
					nv := v*8 + int(lx.src[lx.pos]-'0')
					if nv > 255 {
						break
					}
					v = nv
					lx.advance()
					n++
				}
				b.WriteRune(rune(v))
			case 'x':
				lx.advance()
				d1, ok1 := hexVal(lx.peek(0))
				d2, ok2 := hexVal(lx.peek(1))
				if !ok1 || !ok2 {
					return "", lx.illegal()
				}
				lx.advance()
				lx.advance()
				b.WriteRune(rune(d1*16 + d2))
			case 'u':
				lx.advance()
				cp, ok := lx.readUnicodeEscapeBody()
				if !ok {
					return "", lx.illegal()
				}
				// handle surrogate pairs
				if cp >= 0xD800 && cp <= 0xDBFF && lx.peek(0) == '\\' && lx.peek(1) == 'u' {
					save := lx.pos
					sl, sc := lx.line, lx.col
					lx.advance()
					lx.advance()
					lo, ok2 := lx.readUnicodeEscapeBody()
					if ok2 && lo >= 0xDC00 && lo <= 0xDFFF {
						cp = (cp-0xD800)<<10 + (lo - 0xDC00) + 0x10000
					} else {
						lx.pos, lx.line, lx.col = save, sl, sc
					}
				}
				writeCodePoint(&b, cp)
			case '\r':
				lx.advance()
				if lx.peek(0) == '\n' {
					lx.advance()
				}
			case '\n', '\u2028', '\u2029':
				lx.advance()
			default:
				b.WriteRune(e)
				lx.advance()
			}
			continue
		}
		b.WriteRune(r)
		lx.advance()
	}
}

// writeCodePoint writes a code point, encoding lone surrogates in WTF-8 style
// (as 3-byte sequences) so they can round-trip.
func writeCodePoint(b *strings.Builder, cp rune) {
	if cp >= 0xD800 && cp <= 0xDFFF {
		b.WriteByte(byte(0xE0 | (cp >> 12)))
		b.WriteByte(byte(0x80 | ((cp >> 6) & 0x3F)))
		b.WriteByte(byte(0x80 | (cp & 0x3F)))
		return
	}
	if !utf8.ValidRune(cp) {
		b.WriteRune(utf8.RuneError)
		return
	}
	b.WriteRune(cp)
}

func (lx *lexer) readTemplate(start, line, col int) (Token, *SyntaxError) {
	lx.advance() // `
	tok := Token{Type: TTemplate, Pos: start, Line: line, Col: col}
	var cooked strings.Builder
	var raw strings.Builder
	for {
		if lx.pos >= len(lx.src) {
			return Token{}, lx.illegal()
		}
		r := lx.src[lx.pos]
		if r == '`' {
			lx.advance()
			tok.Quasis = append(tok.Quasis, cooked.String())
			tok.RawParts = append(tok.RawParts, raw.String())
			tok.End = lx.pos
			tok.Raw = string(lx.src[start:lx.pos])
			tok.Value = tok.Raw
			return tok, nil
		}
		if r == '$' && lx.peek(1) == '{' {
			lx.advance()
			lx.advance()
			tok.Quasis = append(tok.Quasis, cooked.String())
			tok.RawParts = append(tok.RawParts, raw.String())
			cooked.Reset()
			raw.Reset()
			toks, npos, nline, ncol, err := lexTokens(lx.src, lx.pos, lx.line, lx.col, true)
			if err != nil {
				return Token{}, err
			}
			if npos > len(lx.src) || (npos == len(lx.src) && (len(lx.src) == 0 || lx.src[npos-1] != '}')) {
				return Token{}, lx.illegal()
			}
			tok.Exprs = append(tok.Exprs, toks)
			lx.pos, lx.line, lx.col = npos, nline, ncol
			continue
		}
		if r == '\\' {
			raw.WriteRune(r)
			lx.advance()
			if lx.pos >= len(lx.src) {
				return Token{}, lx.illegal()
			}
			e := lx.src[lx.pos]
			raw.WriteRune(e)
			switch e {
			case 'n':
				cooked.WriteRune('\n')
				lx.advance()
			case 't':
				cooked.WriteRune('\t')
				lx.advance()
			case 'r':
				cooked.WriteRune('\r')
				lx.advance()
			case 'b':
				cooked.WriteRune('\b')
				lx.advance()
			case 'f':
				cooked.WriteRune('\f')
				lx.advance()
			case 'v':
				cooked.WriteRune('\v')
				lx.advance()
			case '0':
				cooked.WriteRune(0)
				lx.advance()
			case 'x':
				lx.advance()
				d1, ok1 := hexVal(lx.peek(0))
				d2, ok2 := hexVal(lx.peek(1))
				if !ok1 || !ok2 {
					return Token{}, lx.illegal()
				}
				raw.WriteRune(lx.peek(0))
				raw.WriteRune(lx.peek(1))
				lx.advance()
				lx.advance()
				cooked.WriteRune(rune(d1*16 + d2))
			case 'u':
				lx.advance()
				p0 := lx.pos
				cp, ok := lx.readUnicodeEscapeBody()
				if !ok {
					return Token{}, lx.illegal()
				}
				raw.WriteString(string(lx.src[p0:lx.pos]))
				writeCodePoint(&cooked, cp)
			case '\r':
				lx.advance()
				if lx.peek(0) == '\n' {
					lx.advance()
				}
			case '\n':
				lx.advance()
			default:
				cooked.WriteRune(e)
				lx.advance()
			}
			continue
		}
		if r == '\r' {
			// normalize CRLF
			lx.advance()
			if lx.peek(0) == '\n' {
				lx.advance()
			}
			cooked.WriteRune('\n')
			raw.WriteRune('\n')
			continue
		}
		cooked.WriteRune(r)
		raw.WriteRune(r)
		lx.advance()
	}
}

func (lx *lexer) readRegex(start, line, col int) (Token, *SyntaxError) {
	lx.advance() // /
	var pat strings.Builder
	inClass := false
	for {
		if lx.pos >= len(lx.src) || isLineTerm(lx.src[lx.pos]) {
			return Token{}, &SyntaxError{Message: "Invalid regular expression: missing /", Pos: lx.pos, Line: lx.line, Col: lx.col}
		}
		r := lx.src[lx.pos]
		if r == '\\' {
			pat.WriteRune(r)
			lx.advance()
			if lx.pos >= len(lx.src) || isLineTerm(lx.src[lx.pos]) {
				return Token{}, &SyntaxError{Message: "Invalid regular expression: missing /", Pos: lx.pos, Line: lx.line, Col: lx.col}
			}
			pat.WriteRune(lx.src[lx.pos])
			lx.advance()
			continue
		}
		if r == '[' {
			inClass = true
		} else if r == ']' {
			inClass = false
		} else if r == '/' && !inClass {
			lx.advance()
			break
		}
		pat.WriteRune(r)
		lx.advance()
	}
	var flags strings.Builder
	for lx.pos < len(lx.src) && isIDPart(lx.src[lx.pos]) {
		flags.WriteRune(lx.src[lx.pos])
		lx.advance()
	}
	return Token{Type: TRegex, Pattern: pat.String(), Flags: flags.String(), Raw: string(lx.src[start:lx.pos]), Value: string(lx.src[start:lx.pos]), Pos: start, End: lx.pos, Line: line, Col: col}, nil
}

func (t Token) String() string {
	switch t.Type {
	case TEOF:
		return "EOF"
	case TNumber:
		return fmt.Sprintf("number(%s)", t.Raw)
	}
	return t.Value
}
EOF
echo ok"}

