{"command":"cd /workspace; cat > internal/js/parser.go <<'EOF'
package js

import (
	"fmt"
	"strings"
)

type parser struct {
	src    []rune
	toks   []Token
	i      int
	strict bool
	inFunc int
	inLoop int
	inSwitch int
	labels []string
	noIn   bool
	err    *SyntaxError
}

type bailout struct{}

func (p *parser) fail(tok Token, msg string) {
	if p.err == nil {
		p.err = &SyntaxError{Message: msg, Pos: tok.Pos, Line: tok.Line, Col: tok.Col, Kind: "parser"}
	}
	panic(bailout{})
}

func (p *parser) compileError(tok Token, msg string) {
	if p.err == nil {
		p.err = &SyntaxError{Message: msg, Pos: tok.Pos, Line: tok.Line, Col: tok.Col, Kind: "compiler"}
	}
	panic(bailout{})
}

func (p *parser) unexpected(tok Token) {
	switch tok.Type {
	case TEOF:
		p.fail(tok, "Unexpected end of input")
	case TNumber, TBigInt:
		p.fail(tok, "Unexpected number")
	case TString, TTemplate:
		p.fail(tok, "Unexpected string")
	case TIdent:
		if p.strict && strictReserved[tok.Value] {
			p.fail(tok, "Unexpected strict mode reserved word")
		}
		p.fail(tok, "Unexpected identifier")
	case TKeyword:
		p.fail(tok, "Unexpected token "+tok.Value)
	case TIllegal:
		p.fail(tok, "Unexpected token ILLEGAL")
	default:
		p.fail(tok, "Unexpected token "+tok.Value)
	}
}

func (p *parser) cur() Token  { return p.toks[p.i] }
func (p *parser) peekTok(n int) Token {
	if p.i+n < len(p.toks) {
		return p.toks[p.i+n]
	}
	return p.toks[len(p.toks)-1]
}
func (p *parser) advance() Token {
	t := p.toks[p.i]
	if p.i < len(p.toks)-1 {
		p.i++
	}
	return t
}
func (p *parser) is(v string) bool {
	t := p.cur()
	return (t.Type == TPunct || t.Type == TKeyword) && t.Value == v
}
func (p *parser) isIdent(v string) bool {
	t := p.cur()
	return t.Type == TIdent && t.Value == v
}
func (p *parser) eat(v string) bool {
	if p.is(v) {
		p.advance()
		return true
	}
	return false
}
func (p *parser) expect(v string) Token {
	if !p.is(v) {
		p.unexpected(p.cur())
	}
	return p.advance()
}

func (p *parser) consumeSemicolon() {
	if p.eat(";") {
		return
	}
	t := p.cur()
	if t.Type == TEOF || p.is("}") || t.NewlineBefore {
		return
	}
	p.unexpected(t)
}

// Parse parses a complete program.
func Parse(src string, strict bool) (prog *Program, err *SyntaxError) {
	runes := []rune(src)
	toks, _, _, _, lerr := lexTokens(runes, 0, 1, 1, false)
	if lerr != nil {
		lerr.Kind = "parser"
		return nil, lerr
	}
	p := &parser{src: runes, toks: toks, strict: strict}
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(bailout); ok {
				err = p.err
				return
			}
			panic(r)
		}
	}()
	prog = &Program{}
	// directive prologue
	if t := p.cur(); t.Type == TString && t.Value == "use strict" && (p.peekTok(1).Type == TEOF || p.peekTok(1).Value == ";" || p.peekTok(1).NewlineBefore) {
		p.strict = true
	}
	prog.Strict = p.strict
	for p.cur().Type != TEOF {
		prog.Body = append(prog.Body, p.parseStatement())
	}
	return prog, nil
}

func (p *parser) parseStatement() Node {
	t := p.cur()
	switch t.Type {
	case TPunct:
		switch t.Value {
		case "{":
			return p.parseBlock()
		case ";":
			p.advance()
			return &EmptyStmt{}
		}
	case TKeyword:
		switch t.Value {
		case "var", "const":
			d := p.parseVarDecl(true)
			p.consumeSemicolon()
			return d
		case "function":
			return p.parseFunctionDecl()
		case "class":
			return p.parseClassDecl()
		case "if":
			return p.parseIf()
		case "for":
			return p.parseFor()
		case "while":
			p.advance()
			p.expect("(")
			test := p.parseExpression()
			p.expect(")")
			p.inLoop++
			body := p.parseStatement()
			p.inLoop--
			return &WhileStmt{Test: test, Body: body}
		case "do":
			p.advance()
			p.inLoop++
			body := p.parseStatement()
			p.inLoop--
			if !p.is("while") {
				p.unexpected(p.cur())
			}
			p.advance()
			p.expect("(")
			test := p.parseExpression()
			p.expect(")")
			p.eat(";")
			return &DoWhileStmt{Body: body, Test: test}
		case "return":
			if p.inFunc == 0 {
				p.fail(t, "Illegal return statement")
			}
			p.advance()
			var arg Node
			if !p.is(";") && !p.is("}") && p.cur().Type != TEOF && !p.cur().NewlineBefore {
				arg = p.parseExpression()
			}
			p.consumeSemicolon()
			return &ReturnStmt{Arg: arg}
		case "break", "continue":
			p.advance()
			label := ""
			if p.cur().Type == TIdent && !p.cur().NewlineBefore {
				label = p.advance().Value
			}
			p.consumeSemicolon()
			if t.Value == "break" {
				if label == "" && p.inLoop == 0 && p.inSwitch == 0 {
					p.compileError(t, "Could not find block label")
				}
				return &BreakStmt{Label: label}
			}
			if p.inLoop == 0 {
				p.compileError(t, "Could not find block label")
			}
			return &ContinueStmt{Label: label}
		case "throw":
			p.advance()
			if p.cur().NewlineBefore {
				p.fail(p.cur(), "Illegal newline after throw")
			}
			arg := p.parseExpression()
			p.consumeSemicolon()
			return &ThrowStmt{Arg: arg}
		case "try":
			return p.parseTry()
		case "switch":
			return p.parseSwitch()
		case "debugger":
			p.advance()
			p.consumeSemicolon()
			return &DebuggerStmt{}
		case "with":
			if p.strict {
				p.compileError(t, "Strict mode code may not include a with statement")
			}
			p.fail(t, "Unexpected token with")
		case "import", "export":
			p.fail(t, "Unexpected token "+t.Value)
		}
	case TIdent:
		if t.Value == "let" {
			nt := p.peekTok(1)
			if nt.Type == TIdent || (nt.Type == TPunct && (nt.Value == "[" || nt.Value == "{")) || (nt.Type == TKeyword && nt.Value == "yield") {
				d := p.parseVarDecl(true)
				p.consumeSemicolon()
				return d
			}
			if p.strict {
				p.compileError(t, "Unexpected strict mode reserved word")
			}
		}
		if t.Value == "async" && p.peekTok(1).Type == TKeyword && p.peekTok(1).Value == "function" && !p.peekTok(1).NewlineBefore {
			p.advance()
			fd := p.parseFunctionDecl()
			fd.(*FuncDecl).Func.IsAsync = true
			return fd
		}
		// labeled statement
		if p.peekTok(1).Type == TPunct && p.peekTok(1).Value == ":" {
			p.advance()
			p.advance()
			p.labels = append(p.labels, t.Value)
			body := p.parseStatement()
			p.labels = p.labels[:len(p.labels)-1]
			return &LabeledStmt{Label: t.Value, Body: body}
		}
	}
	expr := p.parseExpression()
	p.consumeSemicolon()
	return &ExprStmt{Expr: expr}
}

func (p *parser) parseBlock() *BlockStmt {
	p.expect("{")
	b := &BlockStmt{}
	for !p.is("}") {
		if p.cur().Type == TEOF {
			p.unexpected(p.cur())
		}
		b.Body = append(b.Body, p.parseStatement())
	}
	p.advance()
	return b
}

func (p *parser) parseVarDecl(allowIn bool) *VarDecl {
	kindTok := p.advance()
	d := &VarDecl{Kind: kindTok.Value}
	for {
		target := p.parseBindingTarget()
		var init Node
		if p.eat("=") {
			save := p.noIn
			p.noIn = !allowIn
			init = p.parseAssignment()
			p.noIn = save
		} else if d.Kind == "const" && allowIn {
			if !(p.is("in") || p.isIdent("of")) {
				p.fail(p.cur(), "Missing initializer in const declaration")
			}
		} else if _, ok := target.(*Identifier); !ok && allowIn {
			if !(p.is("in") || p.isIdent("of")) {
				p.fail(p.cur(), "Missing initializer in destructuring declaration")
			}
		}
		d.Decls = append(d.Decls, &VarDeclarator{Target: target, Init: init})
		if !p.eat(",") {
			break
		}
	}
	return d
}

func (p *parser) checkBindingIdent(t Token) {
	if t.Type != TIdent {
		p.unexpected(t)
	}
	if p.strict {
		if t.Value == "eval" || t.Value == "arguments" {
			p.compileError(t, "Assignment to eval or arguments is not allowed in strict mode")
		}
		if strictReserved[t.Value] {
			if t.Value == "let" {
				p.compileError(t, "let is disallowed as a lexically bound name")
			}
			p.compileError(t, "Unexpected strict mode reserved word")
		}
	}
}

// parseBindingTarget parses an identifier or destructuring pattern.
func (p *parser) parseBindingTarget() Node {
	t := p.cur()
	switch {
	case t.Type == TPunct && t.Value == "[":
		return p.parseArrayPattern()
	case t.Type == TPunct && t.Value == "{":
		return p.parseObjectPattern()
	case t.Type == TIdent:
		p.checkBindingIdent(t)
		p.advance()
		return &Identifier{Name: t.Value, Pos: t.Pos}
	case t.Type == TKeyword && (t.Value == "yield" || t.Value == "await"):
		p.advance()
		return &Identifier{Name: t.Value, Pos: t.Pos}
	}
	p.unexpected(t)
	return nil
}

func (p *parser) parseArrayPattern() Node {
	p.expect("[")
	ap := &ArrayPattern{}
	for !p.is("]") {
		if p.is(",") {
			p.advance()
			ap.Elements = append(ap.Elements, nil)
			continue
		}
		if p.eat("...") {
			ap.Rest = p.parseBindingTarget()
			p.eat(",")
			if !p.is("]") {
				p.unexpected(p.cur())
			}
			break
		}
		target := p.parseBindingTarget()
		var def Node
		if p.eat("=") {
			def = p.parseAssignment()
		}
		ap.Elements = append(ap.Elements, &PatternElem{Target: target, Default: def})
		if !p.is("]") {
			p.expect(",")
		}
	}
	p.expect("]")
	return ap
}

func (p *parser) parsePropertyName() (Node, bool) {
	t := p.cur()
	switch t.Type {
	case TIdent, TKeyword:
		p.advance()
		return &StringLit{Value: t.Value}, false
	case TString:
		p.advance()
		return &StringLit{Value: t.Value}, false
	case TNumber:
		p.advance()
		return &StringLit{Value: numberToString(t.Num)}, false
	case TBigInt:
		p.advance()
		return &StringLit{Value: bigIntLiteralString(t.Value)}, false
	case TPunct:
		if t.Value == "[" {
			p.advance()
			e := p.parseAssignment()
			p.expect("]")
			return e, true
		}
	}
	p.unexpected(t)
	return nil, false
}

func (p *parser) parseObjectPattern() Node {
	p.expect("{")
	op := &ObjectPattern{}
	for !p.is("}") {
		if p.eat("...") {
			op.Rest = p.parseBindingTarget()
			p.eat(",")
			if !p.is("}") {
				p.unexpected(p.cur())
			}
			break
		}
		keyTok := p.cur()
		key, computed := p.parsePropertyName()
		var target Node
		var def Node
		if p.eat(":") {
			target = p.parseBindingTarget()
		} else {
			if computed || (keyTok.Type != TIdent && !(keyTok.Type == TKeyword && (keyTok.Value == "yield" || keyTok.Value == "await"))) {
				p.unexpected(p.cur())
			}
			p.checkBindingIdent(keyTok)
			target = &Identifier{Name: keyTok.Value, Pos: keyTok.Pos}
		}
		if p.eat("=") {
			def = p.parseAssignment()
		}
		op.Props = append(op.Props, &PatternProp{Key: key, Computed: computed, Target: target, Default: def})
		if !p.is("}") {
			p.expect(",")
		}
	}
	p.expect("}")
	return op
}

func (p *parser) parseFunctionDecl() Node {
	start := p.cur().Pos
	p.advance() // function
	isGen := p.eat("*")
	nameTok := p.cur()
	if nameTok.Type != TIdent {
		p.unexpected(nameTok)
	}
	p.checkBindingIdent(nameTok)
	p.advance()
	f := p.parseFunctionRest(nameTok.Value, start, false)
	f.IsGen = isGen
	return &FuncDecl{Func: f}
}

func (p *parser) parseParams() []*Param {
	p.expect("(")
	var params []*Param
	for !p.is(")") {
		if p.eat("...") {
			target := p.parseBindingTarget()
			params = append(params, &Param{Target: target, Rest: true})
			if !p.is(")") {
				p.unexpected(p.cur())
			}
			break
		}
		target := p.parseBindingTarget()
		var def Node
		if p.eat("=") {
			def = p.parseAssignment()
		}
		params = append(params, &Param{Target: target, Default: def})
		if !p.is(")") {
			p.expect(",")
		}
	}
	p.expect(")")
	return params
}

func (p *parser) parseFunctionBody() []Node {
	p.expect("{")
	saveStrict := p.strict
	saveLoop, saveSwitch, saveLabels := p.inLoop, p.inSwitch, p.labels
	p.inLoop, p.inSwitch, p.labels = 0, 0, nil
	p.inFunc++
	if t := p.cur(); t.Type == TString && t.Value == "use strict" {
		nt := p.peekTok(1)
		if nt.Type == TEOF || (nt.Type == TPunct && (nt.Value == ";" || nt.Value == "}")) || nt.NewlineBefore {
			p.strict = true
		}
	}
	var body []Node
	for !p.is("}") {
		if p.cur().Type == TEOF {
			p.unexpected(p.cur())
		}
		body = append(body, p.parseStatement())
	}
	p.advance()
	p.inFunc--
	p.strict = saveStrict
	p.inLoop, p.inSwitch, p.labels = saveLoop, saveSwitch, saveLabels
	return body
}

func (p *parser) parseFunctionRest(name string, start int, isMethod bool) *FuncLit {
	params := p.parseParams()
	body := p.parseFunctionBody()
	end := p.toks[p.i-1].End
	f := &FuncLit{Name: name, Params: params, Body: body, Source: string(p.src[start:end]), IsMethod: isMethod, Strict: p.strict}
	f.SimpleParams = simpleParams(params)
	return f
}

func simpleParams(params []*Param) bool {
	for _, pr := range params {
		if pr.Rest || pr.Default != nil {
			return false
		}
		if _, ok := pr.Target.(*Identifier); !ok {
			return false
		}
	}
	return true
}

func (p *parser) parseClassDecl() Node {
	c := p.parseClass()
	if c.Name == "" {
		p.unexpected(p.cur())
	}
	return &ClassDecl{Class: c}
}

func (p *parser) parseClass() *ClassLit {
	start := p.cur().Pos
	p.advance() // class
	saveStrict := p.strict
	p.strict = true
	c := &ClassLit{}
	if p.cur().Type == TIdent {
		c.Name = p.advance().Value
	}
	if p.eat("extends") {
		c.SuperClass = p.parseLeftHandSide()
	}
	p.expect("{")
	for !p.is("}") {
		if p.eat(";") {
			continue
		}
		m := &ClassMember{Kind: "method"}
		if p.isIdent("static") && !(p.peekTok(1).Type == TPunct && (p.peekTok(1).Value == "(" || p.peekTok(1).Value == "=")) {
			p.advance()
			m.Static = true
			if p.is("{") {
				// static block
				body := p.parseFunctionBody()
				m.Kind = "static-block"
				m.Value = &FuncLit{Body: body, Strict: true}
				c.Members = append(c.Members, m)
				continue
			}
		}
		if (p.isIdent("get") || p.isIdent("set")) && !(p.peekTok(1).Type == TPunct && (p.peekTok(1).Value == "(" || p.peekTok(1).Value == "=" || p.peekTok(1).Value == ";" || p.peekTok(1).Value == "}")) {
			m.Kind = p.advance().Value
		}
		if p.isIdent("async") && !(p.peekTok(1).Type == TPunct && (p.peekTok(1).Value == "(" || p.peekTok(1).Value == "=")) && !p.peekTok(1).NewlineBefore {
			p.advance()
		}
		p.eat("*")
		keyStart := p.cur().Pos
		if p.cur().Type == TPrivate {
			m.Private = true
			m.Key = &StringLit{Value: "#" + p.advance().Value}
		} else {
			m.Key, m.Computed = p.parsePropertyName()
		}
		if p.is("(") {
			name := ""
			if s, ok := m.Key.(*StringLit); ok {
				name = s.Value
			}
			f := p.parseFunctionRest(name, keyStart, true)
			if m.Kind == "get" {
				f.IsGetter = true
			}
			if m.Kind == "set" {
				f.IsSetter = true
			}
			if name == "constructor" && !m.Static && !m.Computed && m.Kind == "method" {
				m.Kind = "constructor"
			}
			m.Value = f
		} else {
			m.Kind = "field"
			if p.eat("=") {
				m.Value = p.parseAssignment()
			}
			p.consumeSemicolon()
		}
		c.Members = append(c.Members, m)
	}
	p.expect("}")
	end := p.toks[p.i-1].End
	c.Source = string(p.src[start:end])
	p.strict = saveStrict
	return c
}

func (p *parser) parseIf() Node {
	p.advance()
	p.expect("(")
	test := p.parseExpression()
	p.expect(")")
	cons := p.parseStatement()
	var alt Node
	if p.eat("else") {
		alt = p.parseStatement()
	}
	return &IfStmt{Test: test, Cons: cons, Alt: alt}
}

func (p *parser) parseFor() Node {
	p.advance() // for
	if p.isIdent("await") {
		p.advance()
	}
	p.expect("(")
	var init Node
	if p.is(";") {
		// no init
	} else {
		t := p.cur()
		isDecl := (t.Type == TKeyword && (t.Value == "var" || t.Value == "const")) ||
			(t.Type == TIdent && t.Value == "let" && (p.peekTok(1).Type == TIdent || (p.peekTok(1).Type == TPunct && (p.peekTok(1).Value == "[" || p.peekTok(1).Value == "{"))))
		if isDecl {
			init = p.parseVarDecl(false)
		} else {
			save := p.noIn
			p.noIn = true
			init = p.parseExpression()
			p.noIn = save
		}
		if p.is("in") || p.isIdent("of") {
			of := p.isIdent("of")
			p.advance()
			var right Node
			if of {
				right = p.parseAssignment()
			} else {
				right = p.parseExpression()
			}
			p.expect(")")
			if vd, ok := init.(*VarDecl); ok {
				if len(vd.Decls) != 1 {
					p.fail(t, "Invalid left-hand side in for-in loop: Must have a single binding.")
				}
			} else {
				init = p.toPattern(init, true)
			}
			p.inLoop++
			body := p.parseStatement()
			p.inLoop--
			return &ForInStmt{Left: init, Right: right, Body: body, Of: of}
		}
	}
	p.expect(";")
	var test, update Node
	if !p.is(";") {
		test = p.parseExpression()
	}
	p.expect(";")
	if !p.is(")") {
		update = p.parseExpression()
	}
	p.expect(")")
	p.inLoop++
	body := p.parseStatement()
	p.inLoop--
	return &ForStmt{Init: init, Test: test, Update: update, Body: body}
}

func (p *parser) parseTry() Node {
	p.advance()
	ts := &TryStmt{}
	ts.Block = p.parseBlock()
	if p.eat("catch") {
		if p.eat("(") {
			ts.Param = p.parseBindingTarget()
			p.expect(")")
		}
		ts.Handler = p.parseBlock()
	}
	if p.eat("finally") {
		ts.Finalizer = p.parseBlock()
	}
	if ts.Handler == nil && ts.Finalizer == nil {
		p.fail(p.cur(), "Missing catch or finally after try")
	}
	return ts
}

func (p *parser) parseSwitch() Node {
	p.advance()
	p.expect("(")
	disc := p.parseExpression()
	p.expect(")")
	p.expect("{")
	ss := &SwitchStmt{Disc: disc}
	p.inSwitch++
	hasDefault := false
	for !p.is("}") {
		sc := &SwitchCase{}
		if p.eat("case") {
			sc.Test = p.parseExpression()
		} else if p.eat("default") {
			if hasDefault {
				p.fail(p.cur(), "More than one default clause in switch statement")
			}
			hasDefault = true
		} else {
			p.unexpected(p.cur())
		}
		p.expect(":")
		for !p.is("case") && !p.is("default") && !p.is("}") {
			if p.cur().Type == TEOF {
				p.unexpected(p.cur())
			}
			sc.Body = append(sc.Body, p.parseStatement())
		}
		ss.Cases = append(ss.Cases, sc)
	}
	p.inSwitch--
	p.expect("}")
	return ss
}

// Expressions

func (p *parser) parseExpression() Node {
	e := p.parseAssignment()
	if p.is(",") {
		seq := &SeqExpr{Exprs: []Node{e}}
		for p.eat(",") {
			seq.Exprs = append(seq.Exprs, p.parseAssignment())
		}
		return seq
	}
	return e
}

func isAssignOp(v string) bool {
	switch v {
	case "=", "+=", "-=", "*=", "/=", "%=", "**=", "<<=", ">>=", ">>>=", "&=", "|=", "^=", "&&=", "||=", "??=":
		return true
	}
	return false
}

// arrowAhead checks whether the tokens starting at '(' form arrow params.
func (p *parser) arrowAhead() bool {
	if !p.is("(") {
		return false
	}
	depth := 0
	for j := p.i; j < len(p.toks); j++ {
		t := p.toks[j]
		if t.Type == TEOF {
			return false
		}
		if t.Type == TPunct {
			switch t.Value {
			case "(", "[", "{":
				depth++
			case ")", "]", "}":
				depth--
				if depth == 0 {
					nt := p.toks[j+1]
					return nt.Type == TPunct && nt.Value == "=>" && !nt.NewlineBefore
				}
			}
		}
	}
	return false
}

func (p *parser) parseArrowFromParams(start int, params []*Param, isAsync bool) Node {
	p.expect("=>")
	f := &FuncLit{Params: params, IsArrow: true, IsAsync: isAsync, Strict: p.strict}
	f.SimpleParams = simpleParams(params)
	if p.is("{") {
		f.Body = p.parseFunctionBody()
	} else {
		p.inFunc++
		saveLoop, saveSwitch := p.inLoop, p.inSwitch
		p.inLoop, p.inSwitch = 0, 0
		f.ExprBody = p.parseAssignment()
		p.inLoop, p.inSwitch = saveLoop, saveSwitch
		p.inFunc--
	}
	end := p.toks[p.i-1].End
	f.Source = string(p.src[start:end])
	return f
}

func (p *parser) parseAssignment() Node {
	t := p.cur()
	// arrow functions
	if t.Type == TIdent && t.Value == "async" && !p.peekTok(1).NewlineBefore {
		nt := p.peekTok(1)
		if nt.Type == TIdent && p.peekTok(2).Type == TPunct && p.peekTok(2).Value == "=>" {
			p.advance()
			id := p.advance()
			p.checkBindingIdent(id)
			return p.parseArrowFromParams(t.Pos, []*Param{{Target: &Identifier{Name: id.Value, Pos: id.Pos}}}, true)
		}
		if nt.Type == TPunct && nt.Value == "(" {
			save := p.i
			p.advance()
			if p.arrowAhead() {
				params := p.parseParams()
				return p.parseArrowFromParams(t.Pos, params, true)
			}
			p.i = save
		}
		if nt.Type == TKeyword && nt.Value == "function" {
			p.advance()
			fn := p.parseFunctionExpr(t.Pos)
			fn.(*FuncLit).IsAsync = true
			return p.continueAssignment(fn)
		}
	}
	if t.Type == TIdent && p.peekTok(1).Type == TPunct && p.peekTok(1).Value == "=>" && !p.peekTok(1).NewlineBefore {
		p.advance()
		p.checkBindingIdent(t)
		return p.parseArrowFromParams(t.Pos, []*Param{{Target: &Identifier{Name: t.Value, Pos: t.Pos}}}, false)
	}
	if t.Type == TKeyword && (t.Value == "yield") && p.peekTok(1).Type == TPunct && p.peekTok(1).Value == "=>" {
		p.advance()
		return p.parseArrowFromParams(t.Pos, []*Param{{Target: &Identifier{Name: t.Value, Pos: t.Pos}}}, false)
	}
	if p.arrowAhead() {
		params := p.parseParams()
		return p.parseArrowFromParams(t.Pos, params, false)
	}
	left := p.parseConditional()
	return p.continueAssignment(left)
}

func (p *parser) continueAssignment(left Node) Node {
	t := p.cur()
	if t.Type == TPunct && isAssignOp(t.Value) {
		p.advance()
		var target Node
		if t.Value == "=" {
			target = p.toPattern(left, false)
		} else {
			switch left.(type) {
			case *Identifier, *MemberExpr:
				target = left
			default:
				p.fail(t, "Invalid left-hand side in assignment")
			}
		}
		if id, ok := target.(*Identifier); ok && p.strict && (id.Name == "eval" || id.Name == "arguments") {
			p.compileError(t, "Assignment to eval or arguments is not allowed in strict mode")
		}
		right := p.parseAssignment()
		return &AssignExpr{Op: t.Value, Target: target, Value: right}
	}
	return left
}

// toPattern converts an expression (array/object literal) into a pattern.
func (p *parser) toPattern(n Node, forIn bool) Node {
	switch e := n.(type) {
	case *Identifier:
		if p.strict && (e.Name == "eval" || e.Name == "arguments") {
			p.compileError(p.cur(), "Assignment to eval or arguments is not allowed in strict mode")
		}
		return e
	case *MemberExpr:
		return e
	case *ArrayLit:
		ap := &ArrayPattern{}
		for i, el := range e.Elements {
			if el == nil {
				ap.Elements = append(ap.Elements, nil)
				continue
			}
			if sp, ok := el.(*SpreadElement); ok {
				if i != len(e.Elements)-1 {
					p.fail(p.cur(), "Rest element must be last element")
				}
				ap.Rest = p.toPattern(sp.Arg, forIn)
				break
			}
			if as, ok := el.(*AssignExpr); ok && as.Op == "=" {
				ap.Elements = append(ap.Elements, &PatternElem{Target: p.toPattern(as.Target, forIn), Default: as.Value})
				continue
			}
			ap.Elements = append(ap.Elements, &PatternElem{Target: p.toPattern(el, forIn)})
		}
		return ap
	case *ObjectLit:
		op := &ObjectPattern{}
		for _, pr := range e.Props {
			if pr.Kind == "spread" {
				op.Rest = p.toPattern(pr.Value, forIn)
				continue
			}
			if pr.Kind != "init" {
				p.fail(p.cur(), "Invalid destructuring assignment target")
			}
			pp := &PatternProp{Key: pr.Key, Computed: pr.Computed}
			if as, ok := pr.Value.(*AssignExpr); ok && as.Op == "=" && pr.Shorthand {
				pp.Target = p.toPattern(as.Target, forIn)
				pp.Default = as.Value
			} else if as, ok := pr.Value.(*AssignExpr); ok && as.Op == "=" {
				pp.Target = p.toPattern(as.Target, forIn)
				pp.Default = as.Value
			} else {
				pp.Target = p.toPattern(pr.Value, forIn)
			}
			op.Props = append(op.Props, pp)
		}
		return op
	case *AssignExpr:
		if e.Op == "=" {
			return &PatternElem{Target: p.toPattern(e.Target, forIn), Default: e.Value}
		}
	case *ArrayPattern, *ObjectPattern:
		return n
	}
	if forIn {
		p.fail(p.cur(), "Invalid left-hand side in for-in loop")
	}
	p.fail(p.cur(), "Invalid left-hand side in assignment")
	return nil
}

func (p *parser) parseConditional() Node {
	test := p.parseBinary(0)
	if p.is("?") {
		p.advance()
		save := p.noIn
		p.noIn = false
		cons := p.parseAssignment()
		p.noIn = save
		p.expect(":")
		alt := p.parseAssignment()
		return &CondExpr{Test: test, Cons: cons, Alt: alt}
	}
	return test
}

var binPrec = map[string]int{
	"??": 1,
	"||": 2, "&&": 3, "|": 4, "^": 5, "&": 6,
	"==": 7, "!=": 7, "===": 7, "!==": 7,
	"<": 8, ">": 8, "<=": 8, ">=": 8, "instanceof": 8, "in": 8,
	"<<": 9, ">>": 9, ">>>": 9,
	"+": 10, "-": 10,
	"*": 11, "/": 11, "%": 11,
	"**": 12,
}

func (p *parser) binOp() (string, int, bool) {
	t := p.cur()
	if t.Type != TPunct && t.Type != TKeyword {
		return "", 0, false
	}
	if t.Value == "in" && p.noIn {
		return "", 0, false
	}
	prec, ok := binPrec[t.Value]
	if !ok {
		return "", 0, false
	}
	return t.Value, prec, true
}

func (p *parser) parseBinary(minPrec int) Node {
	left := p.parseUnary()
	for {
		op, prec, ok := p.binOp()
		if !ok || prec < minPrec {
			return left
		}
		opTok := p.advance()
		var right Node
		if op == "**" {
			if u, isUnary := left.(*UnaryExpr); isUnary && u.Op != "" {
				p.fail(opTok, "Unary operator used immediately before exponentiation expression. Parenthesis must be used to disambiguate operator precedence")
			}
			right = p.parseBinary(prec) // right assoc
		} else {
			right = p.parseBinary(prec + 1)
		}
		switch op {
		case "&&", "||", "??":
			// mixing ?? with && / || without parens is a syntax error
			if op == "??" {
				if l, ok := left.(*LogicalExpr); ok && l.Op != "??" {
					p.fail(opTok, "Unexpected token ??")
				}
				if r, ok := right.(*LogicalExpr); ok && r.Op != "??" {
					p.fail(opTok, "Unexpected token ??")
				}
			}
			left = &LogicalExpr{Op: op, Left: left, Right: right}
		default:
			left = &BinaryExpr{Op: op, Left: left, Right: right}
		}
	}
}

func (p *parser) parseUnary() Node {
	t := p.cur()
	if t.Type == TPunct {
		switch t.Value {
		case "!", "-", "+", "~":
			p.advance()
			arg := p.parseUnary()
			return &UnaryExpr{Op: t.Value, Arg: arg}
		case "++", "--":
			p.advance()
			arg := p.parseUnary()
			switch arg.(type) {
			case *Identifier, *MemberExpr:
			default:
				p.fail(t, "Invalid left-hand side expression in prefix operation")
			}
			return &UpdateExpr{Op: t.Value, Prefix: true, Arg: arg}
		}
	}
	if t.Type == TKeyword {
		switch t.Value {
		case "typeof", "void", "delete":
			p.advance()
			arg := p.parseUnary()
			if t.Value == "delete" && p.strict {
				if _, ok := arg.(*Identifier); ok {
					p.compileError(t, "Delete of an unqualified identifier in strict mode")
				}
			}
			return &UnaryExpr{Op: t.Value, Arg: arg}
		}
	}
	if t.Type == TIdent && t.Value == "await" && p.inFunc > 0 {
		// treat await as identifier unless followed by expression start... keep simple: identifier
	}
	return p.parsePostfix()
}

func (p *parser) parsePostfix() Node {
	expr := p.parseLeftHandSide()
	t := p.cur()
	if t.Type == TPunct && (t.Value == "++" || t.Value == "--") && !t.NewlineBefore {
		switch expr.(type) {
		case *Identifier, *MemberExpr:
		default:
			p.fail(t, "Invalid left-hand side expression in postfix operation")
		}
		p.advance()
		return &UpdateExpr{Op: t.Value, Prefix: false, Arg: expr}
	}
	return expr
}

func (p *parser) parseArguments() []Node {
	p.expect("(")
	var args []Node
	for !p.is(")") {
		if p.eat("...") {
			args = append(args, &SpreadElement{Arg: p.parseAssignment()})
		} else {
			args = append(args, p.parseAssignment())
		}
		if !p.is(")") {
			p.expect(",")
		}
	}
	p.expect(")")
	return args
}

func (p *parser) parseLeftHandSide() Node {
	var expr Node
	t := p.cur()
	if t.Type == TKeyword && t.Value == "new" {
		p.advance()
		if p.is(".") {
			p.advance()
			if !p.isIdent("target") {
				p.unexpected(p.cur())
			}
			p.advance()
			expr = &Identifier{Name: "new.target"}
		} else {
			callee := p.parseNewCallee()
			var args []Node
			if p.is("(") {
				args = p.parseArguments()
			}
			expr = &NewExpr{Callee: callee, Args: args}
		}
	} else {
		expr = p.parsePrimary()
	}
	hasOptional := false
	for {
		t := p.cur()
		if t.Type == TPunct {
			switch t.Value {
			case ".":
				p.advance()
				nt := p.cur()
				if nt.Type == TPrivate {
					p.advance()
					expr = &MemberExpr{Object: expr, Prop: &Identifier{Name: "#" + nt.Value}}
					continue
				}
				if nt.Type != TIdent && nt.Type != TKeyword {
					p.unexpected(nt)
				}
				p.advance()
				expr = &MemberExpr{Object: expr, Prop: &Identifier{Name: nt.Value}}
				continue
			case "?.":
				p.advance()
				hasOptional = true
				nt := p.cur()
				if nt.Type == TPunct && nt.Value == "(" {
					args := p.parseArguments()
					expr = &CallExpr{Callee: expr, Args: args, Optional: true}
					continue
				}
				if nt.Type == TPunct && nt.Value == "[" {
					p.advance()
					prop := p.parseExpression()
					p.expect("]")
					expr = &MemberExpr{Object: expr, Prop: prop, Computed: true, Optional: true}
					continue
				}
				if nt.Type == TPrivate {
					p.advance()
					expr = &MemberExpr{Object: expr, Prop: &Identifier{Name: "#" + nt.Value}, Optional: true}
					continue
				}
				if nt.Type != TIdent && nt.Type != TKeyword {
					p.unexpected(nt)
				}
				p.advance()
				expr = &MemberExpr{Object: expr, Prop: &Identifier{Name: nt.Value}, Optional: true}
				continue
			case "[":
				p.advance()
				save := p.noIn
				p.noIn = false
				prop := p.parseExpression()
				p.noIn = save
				p.expect("]")
				expr = &MemberExpr{Object: expr, Prop: prop, Computed: true}
				continue
			case "(":
				args := p.parseArguments()
				expr = &CallExpr{Callee: expr, Args: args}
				continue
			}
		}
		if t.Type == TTemplate {
			if hasOptional {
				p.fail(t, "Invalid tagged template on optional chain")
			}
			p.advance()
			expr = &TaggedTemplate{Tag: expr, Quasi: p.templateFromToken(t)}
			continue
		}
		break
	}
	if hasOptional {
		return &OptionalChain{Expr: expr}
	}
	return expr
}

func (p *parser) parseNewCallee() Node {
	t := p.cur()
	var expr Node
	if t.Type == TKeyword && t.Value == "new" {
		p.advance()
		callee := p.parseNewCallee()
		var args []Node
		if p.is("(") {
			args = p.parseArguments()
		}
		expr = &NewExpr{Callee: callee, Args: args}
	} else {
		expr = p.parsePrimary()
	}
	for {
		t := p.cur()
		if t.Type == TPunct && t.Value == "." {
			p.advance()
			nt := p.cur()
			if nt.Type != TIdent && nt.Type != TKeyword {
				p.unexpected(nt)
			}
			p.advance()
			expr = &MemberExpr{Object: expr, Prop: &Identifier{Name: nt.Value}}
			continue
		}
		if t.Type == TPunct && t.Value == "[" {
			p.advance()
			prop := p.parseExpression()
			p.expect("]")
			expr = &MemberExpr{Object: expr, Prop: prop, Computed: true}
			continue
		}
		if t.Type == TTemplate {
			p.advance()
			expr = &TaggedTemplate{Tag: expr, Quasi: p.templateFromToken(t)}
			continue
		}
		break
	}
	return expr
}

func (p *parser) templateFromToken(t Token) *TemplateLit {
	tl := &TemplateLit{Quasis: t.Quasis, Raws: t.RawParts}
	for _, toks := range t.Exprs {
		sub := &parser{src: p.src, toks: toks, strict: p.strict, inFunc: p.inFunc}
		if sub.cur().Type == TEOF {
			p.unexpected(sub.cur())
		}
		e := sub.parseExpression()
		if sub.cur().Type != TEOF {
			p.unexpected(sub.cur())
		}
		tl.Exprs = append(tl.Exprs, e)
	}
	return tl
}

func (p *parser) parseFunctionExpr(start int) Node {
	p.advance() // function
	isGen := p.eat("*")
	name := ""
	if p.cur().Type == TIdent {
		name = p.advance().Value
	} else if p.cur().Type == TKeyword && (p.cur().Value == "yield" || p.cur().Value == "await") {
		name = p.advance().Value
	}
	f := p.parseFunctionRest(name, start, false)
	f.IsGen = isGen
	return f
}

func (p *parser) parsePrimary() Node {
	t := p.cur()
	switch t.Type {
	case TIdent:
		if t.Value == "async" && p.peekTok(1).Type == TKeyword && p.peekTok(1).Value == "function" && !p.peekTok(1).NewlineBefore {
			p.advance()
			fn := p.parseFunctionExpr(t.Pos)
			fn.(*FuncLit).IsAsync = true
			return fn
		}
		if p.strict && strictReserved[t.Value] {
			if t.Value == "let" {
				p.compileError(t, "Unexpected strict mode reserved word")
			}
			p.compileError(t, "Unexpected strict mode reserved word")
		}
		p.advance()
		return &Identifier{Name: t.Value, Pos: t.Pos}
	case TNumber:
		if t.Flags == "legacy-octal" && p.strict {
			p.compileError(t, "Octal literals are not allowed in strict mode")
		}
		p.advance()
		return &NumberLit{Value: t.Num, Raw: t.Raw}
	case TBigInt:
		p.advance()
		return &BigIntLit{Raw: t.Value}
	case TString:
		p.advance()
		return &StringLit{Value: t.Value}
	case TTemplate:
		p.advance()
		return p.templateFromToken(t)
	case TRegex:
		p.advance()
		if err := validateRegexFlags(t.Flags); err != "" {
			p.compileError(t, err)
		}
		if msg := validateRegexPattern(t.Pattern, t.Flags); msg != "" {
			p.compileError(t, msg)
		}
		return &RegexLit{Pattern: t.Pattern, Flags: t.Flags}
	case TPrivate:
		p.compileError(t, "Compiler bug: Unknown expression type: *ast.PrivateIdentifier")
	case TKeyword:
		switch t.Value {
		case "this":
			p.advance()
			return &ThisExpr{}
		case "super":
			p.advance()
			return &SuperExpr{}
		case "null":
			p.advance()
			return &NullLit{}
		case "true":
			p.advance()
			return &BoolLit{Value: true}
		case "false":
			p.advance()
			return &BoolLit{Value: false}
		case "function":
			return p.parseFunctionExpr(t.Pos)
		case "class":
			return p.parseClass()
		case "new":
			return p.parseLeftHandSide()
		case "yield", "await":
			p.advance()
			return &Identifier{Name: t.Value, Pos: t.Pos}
		}
		p.unexpected(t)
	case TPunct:
		switch t.Value {
		case "(":
			p.advance()
			save := p.noIn
			p.noIn = false
			e := p.parseExpression()
			p.noIn = save
			p.expect(")")
			return e
		case "[":
			return p.parseArrayLit()
		case "{":
			return p.parseObjectLit()
		}
		p.unexpected(t)
	case TEOF:
		p.unexpected(t)
	}
	p.unexpected(t)
	return nil
}

func (p *parser) parseArrayLit() Node {
	p.expect("[")
	al := &ArrayLit{}
	for !p.is("]") {
		if p.is(",") {
			p.advance()
			al.Elements = append(al.Elements, nil)
			continue
		}
		var el Node
		if p.eat("...") {
			el = &SpreadElement{Arg: p.parseAssignment()}
		} else {
			el = p.parseAssignment()
		}
		al.Elements = append(al.Elements, el)
		if !p.is("]") {
			p.expect(",")
		}
	}
	p.expect("]")
	return al
}

func (p *parser) parseObjectLit() Node {
	p.expect("{")
	ol := &ObjectLit{}
	for !p.is("}") {
		if p.eat("...") {
			ol.Props = append(ol.Props, &Property{Kind: "spread", Value: p.parseAssignment()})
			if !p.is("}") {
				p.expect(",")
			}
			continue
		}
		prop := &Property{Kind: "init"}
		t := p.cur()
		isGetSet := (t.Type == TIdent && (t.Value == "get" || t.Value == "set")) && !(p.peekTok(1).Type == TPunct && (p.peekTok(1).Value == "," || p.peekTok(1).Value == ":" || p.peekTok(1).Value == "(" || p.peekTok(1).Value == "}" || p.peekTok(1).Value == "="))
		isAsync := t.Type == TIdent && t.Value == "async" && !(p.peekTok(1).Type == TPunct && (p.peekTok(1).Value == "," || p.peekTok(1).Value == ":" || p.peekTok(1).Value == "(" || p.peekTok(1).Value == "}" || p.peekTok(1).Value == "=")) && !p.peekTok(1).NewlineBefore
		if isGetSet {
			p.advance()
			prop.Kind = t.Value
		} else if isAsync {
			p.advance()
		}
		isGen := p.eat("*")
		keyStart := p.cur().Pos
		keyTok := p.cur()
		prop.Key, prop.Computed = p.parsePropertyName()
		if p.is("(") {
			name := ""
			if s, ok := prop.Key.(*StringLit); ok {
				name = s.Value
			}
			f := p.parseFunctionRest(name, keyStart, true)
			f.IsGen = isGen
			f.IsAsync = isAsync
			if prop.Kind == "get" {
				f.IsGetter = true
			} else if prop.Kind == "set" {
				f.IsSetter = true
			} else {
				prop.Kind = "method"
			}
			prop.Value = f
		} else if prop.Kind == "get" || prop.Kind == "set" {
			p.unexpected(p.cur())
		} else if p.eat(":") {
			prop.Value = p.parseAssignment()
		} else {
			// shorthand
			if prop.Computed || (keyTok.Type != TIdent && !(keyTok.Type == TKeyword && (keyTok.Value == "yield" || keyTok.Value == "await"))) {
				p.unexpected(p.cur())
			}
			if p.strict && strictReserved[keyTok.Value] {
				p.compileError(keyTok, "Unexpected strict mode reserved word")
			}
			prop.Shorthand = true
			id := &Identifier{Name: keyTok.Value, Pos: keyTok.Pos}
			if p.is("=") {
				// CoverInitializedName: only valid in patterns
				p.advance()
				def := p.parseAssignment()
				prop.Value = &AssignExpr{Op: "=", Target: id, Value: def}
			} else {
				prop.Value = id
			}
		}
		ol.Props = append(ol.Props, prop)
		if !p.is("}") {
			p.expect(",")
		}
	}
	p.expect("}")
	return ol
}

func validateRegexFlags(flags string) string {
	seen := map[rune]bool{}
	for _, f := range flags {
		if !strings.ContainsRune("gimsuyd", f) || seen[f] {
			return fmt.Sprintf("Invalid flags supplied to RegExp constructor '%s'", flags)
		}
		seen[f] = true
	}
	return ""
}
