	if o.Class == "String" {
		n := strLen(o.Prim.(string))
		for i := 0; i < n; i++ {
			ints = append(ints, i)
		}
	}
	for _, k := range o.keys {
		if k.IsSymbol() {
			syms = append(syms, k)
			continue
		}
		if idx, ok := arrayIndex(k.S); ok {
			ints = append(ints, idx)
			continue
		}
		strs = append(strs, k)
	}
	sort.Ints(ints)
	out := make([]PropKey, 0, len(ints)+len(strs)+len(syms))
	for _, i := range ints {
		out = append(out, strKey(strconv.Itoa(i)))
	}
	if o.Class == "Array" {
		out = append(out, strKey("length"))
	}
	if o.Class == "String" {
		out = append(out, strKey("length"))
	}
	out = append(out, strs...)
	if includeSymbols {
		out = append(out, syms...)
	}
	return out
}

func arrayIndex(s string) (int, bool) {
	if len(s) == 0 || len(s) > 10 {
		return 0, false
	}
	if s == "0" {
		return 0, true
	}
	if s[0] < '1' || s[0] > '9' {
		return 0, false
	}
	n := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int(c-'0')
	}
	if n > 4294967294 {
		return 0, false
	}
	return n, true
}

// OrderedMap for Map/Set with insertion order.
type OrderedMap struct {
	keys   []Value
	vals   []Value
	index  map[interface{}]int
	size   int
	deleted int
}

func newOrderedMap() *OrderedMap { return &OrderedMap{index: map[interface{}]int{}} }

func mapKeyOf(v Value) interface{} {
	switch t := v.(type) {
	case float64:
		if t == 0 {
			return float64(0) // normalize -0
		}
		if math.IsNaN(t) {
			return "NaN-key"
		}
		return t
	case *big.Int:
		return "bigint:" + t.String()
	}
	return v
}

func (m *OrderedMap) Get(k Value) (Value, bool) {
	i, ok := m.index[mapKeyOf(k)]
	if !ok {
		return undefined, false
	}
	return m.vals[i], true
}

func (m *OrderedMap) Set(k Value, v Value) {
	mk := mapKeyOf(k)
	if i, ok := m.index[mk]; ok {
		m.vals[i] = v
		return
	}
	if f, ok := k.(float64); ok && f == 0 {
		k = float64(0)
	}
	m.index[mk] = len(m.keys)
	m.keys = append(m.keys, k)
	m.vals = append(m.vals, v)
	m.size++
}

func (m *OrderedMap) Delete(k Value) bool {
	mk := mapKeyOf(k)
	i, ok := m.index[mk]
	if !ok {
		return false
	}
	delete(m.index, mk)
	m.keys[i] = nil
	m.vals[i] = nil
	m.size--
	m.deleted++
	return true
}

func (m *OrderedMap) Clear() {
	m.keys = nil
	m.vals = nil
	m.index = map[interface{}]int{}
	m.size = 0
}

func (m *OrderedMap) Has(k Value) bool {
	_, ok := m.index[mapKeyOf(k)]
	return ok
}

// Each iterates live over entries (tolerates mutation during iteration).
func (m *OrderedMap) Each(fn func(k, v Value) bool) {
	for i := 0; i < len(m.keys); i++ {
		if m.keys[i] == nil {
			continue
		}
		if !fn(m.keys[i], m.vals[i]) {
			return
		}
	}
}

func (m *OrderedMap) Len() int { return m.size }

