func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

// decodeWTF8 decodes a string into code points, keeping lone surrogates.
func decodeWTF8(s string) []rune {
	out := make([]rune, 0, len(s))
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			out = append(out, rune(c))
			i++
			continue
		}
		if c == 0xED && i+2 < len(s) && s[i+1] >= 0xA0 && s[i+1] <= 0xBF && s[i+2] >= 0x80 && s[i+2] <= 0xBF {
			// surrogate encoded in WTF-8
			r := rune(c&0x0F)<<12 | rune(s[i+1]&0x3F)<<6 | rune(s[i+2]&0x3F)
			out = append(out, r)
			i += 3
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		out = append(out, r)
		i += size
	}
	return out
}

// utf16Units converts a string to UTF-16 code units.
func utf16Units(s string) []uint16 {
	if isASCII(s) {
		u := make([]uint16, len(s))
		for i := 0; i < len(s); i++ {
			u[i] = uint16(s[i])
		}
		return u
	}
	cps := decodeWTF8(s)
	u := make([]uint16, 0, len(cps))
	for _, r := range cps {
		if r >= 0x10000 {
			r -= 0x10000
			u = append(u, uint16(0xD800+(r>>10)), uint16(0xDC00+(r&0x3FF)))
		} else {
			u = append(u, uint16(r))
		}
	}
	return u
}

// unitsToString converts UTF-16 code units to a (WTF-8) string.
func unitsToString(u []uint16) string {
	var b strings.Builder
	for i := 0; i < len(u); i++ {
		c := rune(u[i])
		if c >= 0xD800 && c <= 0xDBFF && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] <= 0xDFFF {
			cp := (c-0xD800)<<10 + (rune(u[i+1]) - 0xDC00) + 0x10000
			b.WriteRune(cp)
			i++
			continue
		}
		writeCodePoint(&b, c)
	}
	return b.String()
}

func strLen(s string) int {
	if isASCII(s) {
		return len(s)
	}
	return len(utf16Units(s))
}

// strAt returns the code unit at index i as a string, or "" if out of range.
func strAt(s string, i int) (string, bool) {
	if isASCII(s) {
		if i < 0 || i >= len(s) {
			return "", false
		}
		return s[i : i+1], true
	}
	u := utf16Units(s)
	if i < 0 || i >= len(u) {
		return "", false
	}
	return unitsToString(u[i : i+1]), true
}

