		}
		return -1
	}
	for i := from; i+len(su) <= len(u); i++ {
		match := true
		for j := range su {
			if u[i+j] != su[j] {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

func strLastIndexOf(s, sub string, from int) int {
	u := utf16Units(s)
	su := utf16Units(sub)
	if from > len(u)-len(su) {
