// unitIndexToByteOffset converts a UTF-16 index to a byte offset.
func unitIndexToByteOffset(s string, idx int) int {
	if isASCII(s) {
		return idx
	}
	n := 0
	for i := 0; i < len(s); {
		if n >= idx {
			return i
		}
		c := s[i]
		if c < 0x80 {
			n++
			i++
			continue
		}
		if c == 0xED && i+2 < len(s) && s[i+1] >= 0xA0 && s[i+1] <= 0xBF {
			n++
			i += 3
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r >= 0x10000 {
			n += 2
		} else {
			n++
		}
		i += size
	}
	return len(s)
}

func isJSWhitespace(r rune) bool {
	switch r {
	case '\t', '\n', '\v', '\f', '\r', ' ', 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
		return true
	}
	return r >= 0x2000 && r <= 0x200A
}

func trimJS(s string) string {
	return strings.TrimFunc(s, isJSWhitespace)
}

func trimStartJS(s string) string { return strings.TrimLeftFunc(s, isJSWhitespace) }
func trimEndJS(s string) string   { return strings.TrimRightFunc(s, isJSWhitespace) }

// sanitizeUTF8 converts lone surrogates into U+FFFD for output.
func sanitizeUTF8(s string) string {
	if isASCII(s) {
		return s
	}
	cps := decodeWTF8(s)
	var b strings.Builder
	for _, r := range cps {
		if r >= 0xD800 && r <= 0xDFFF || !utf8.ValidRune(r) {
			b.WriteRune(utf8.RuneError)
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}
