// numberToString implements Number::toString(10).
func numberToString(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if f == 0 {
		return "0"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	sign := ""
	if f < 0 {
		sign = "-"
		f = -f
	}
	// shortest representation
	e := strconv.FormatFloat(f, 'e', -1, 64) // d.ddde±XX
	mant, expStr, _ := strings.Cut(e, "e")
	digits := strings.Replace(mant, ".", "", 1)
	exp, _ := strconv.Atoi(expStr)
	k := len(digits)
	n := exp + 1
	var s string
	switch {
	case k <= n && n <= 21:
		s = digits + strings.Repeat("0", n-k)
	case 0 < n && n <= 21:
		s = digits[:n] + "." + digits[n:]
	case -6 < n && n <= 0:
		s = "0." + strings.Repeat("0", -n) + digits
	default:
		es := "+"
		if n-1 < 0 {
			es = "-"
		}
		ev := n - 1
		if ev < 0 {
			ev = -ev
		}
		if k == 1 {
			s = digits + "e" + es + strconv.Itoa(ev)
		} else {
			s = digits[:1] + "." + digits[1:] + "e" + es + strconv.Itoa(ev)
		}
	}
	return sign + s
}

// numberToStringRadix converts a number to a string in the given radix.
func numberToStringRadix(f float64, radix int) string {
	if radix == 10 {
		return numberToString(f)
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	if f == 0 {
		return "0"
	}
	neg := f < 0
	if neg {
		f = -f
	}
	intPart := math.Floor(f)
	frac := f - intPart
	const chars = "0123456789abcdefghijklmnopqrstuvwxyz"
	// integer part
	var intStr string
	if intPart < 1e21 {
		bi, _ := big.NewFloat(intPart).Int(nil)
		intStr = bi.Text(radix)
	} else {
		bf := new(big.Float).SetFloat64(intPart)
		bi, _ := bf.Int(nil)
		intStr = bi.Text(radix)
	}
	if frac == 0 {
		if neg {
			return "-" + intStr
		}
		return intStr
	}
	// fraction: port of V8's algorithm
	var b strings.Builder
	b.WriteString(intStr)
	b.WriteByte('.')
	delta := 0.5 * (math.Nextafter(f, math.Inf(1)) - f)
	delta = math.Max(math.Nextafter(0, 1), delta)
	if frac >= delta {
		for {
			frac *= float64(radix)
			delta *= float64(radix)
			digit := int(frac)
			b.WriteByte(chars[digit])
			frac -= float64(digit)
			if frac > 0.5 || (frac == 0.5 && (digit&1) == 1) {
				if frac+delta > 1 {
					// round up and propagate carries
					s := []byte(b.String())
					i := len(s) - 1
					for ; i >= 0; i-- {
						if s[i] == '.' {
							continue
						}
						d := strings.IndexByte(chars, s[i])
						if d+1 < radix {
							s[i] = chars[d+1]
							break
						}
						s[i] = '0'
					}
					if i < 0 {
						s = append([]byte{'1'}, s...)
					}
					res := strings.TrimRight(string(s), "0")
					res = strings.TrimSuffix(res, ".")
					if neg {
						return "-" + res
					}
					return res
				}
			}
			if frac < delta {
				break
			}
		}
	}
	res := b.String()
	res = strings.TrimSuffix(res, ".")
	if neg {
		return "-" + res
	}
	return res
}

