func exactRat(f float64) *big.Rat {
	r := new(big.Rat)
	r.SetFloat64(f)
	return r
}

// roundHalfUp returns the integer n closest to r, choosing the larger on ties.
func roundHalfUp(r *big.Rat) *big.Int {
	// floor(r + 1/2)
	half := big.NewRat(1, 2)
	sum := new(big.Rat).Add(r, half)
	num := sum.Num()
	den := sum.Denom()
	q := new(big.Int).Div(num, den) // Euclidean division; for positive fine
	if sum.Sign() < 0 && new(big.Int).Mod(num, den).Sign() != 0 {
		// big.Int.Div is Euclidean => already floor for negative with positive denom
	}
	return q
}

func numberToFixed(x float64, f int) string {
	if math.IsNaN(x) {
		return "NaN"
	}
	if math.Abs(x) >= 1e21 {
		return numberToString(x)
	}
	sign := ""
	if x < 0 {
		sign = "-"
		x = -x
	}
	r := exactRat(x)
	scale := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(f)), nil)
	r.Mul(r, new(big.Rat).SetInt(scale))
	n := roundHalfUp(r)
	s := n.String()
	if f == 0 {
		return sign + s
	}
	for len(s) <= f {
		s = "0" + s
	}
	return sign + s[:len(s)-f] + "." + s[len(s)-f:]
}

// digitsAndExp returns p significant digits of x (x>0) and exponent e such
// that x ≈ d.ddd × 10^e, using round-half-up on the exact value.
func digitsAndExp(x float64, p int) (string, int) {
	r := exactRat(x)
	// estimate e
	e := int(math.Floor(math.Log10(x)))
	for attempt := 0; attempt < 3; attempt++ {
		// n = round(x / 10^(e-p+1))
		shift := e - p + 1
		scaled := new(big.Rat).Set(r)
		if shift >= 0 {
			scaled.Quo(scaled, new(big.Rat).SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(shift)), nil)))
		} else {
			scaled.Mul(scaled, new(big.Rat).SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-shift)), nil)))
		}
		n := roundHalfUp(scaled)
		s := n.String()
		if len(s) == p {
			return s, e
		}
		if len(s) > p {
			e++
		} else {
			e--
		}
	}
	s := new(big.Int).String()
	return s, e
}

func numberToExponential(x float64, f int, hasF bool) string {
