package js

import (
	"strings"
	"unicode/utf8"
)

func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

// decodeWTF8 decodes a string into code points, keeping lone surrogates.
func decodeWTF8(s string) []rune {
	out := make([]rune, 0, len(s))
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			out = append(out, rune(c))
			i++
			continue
		}
		if c == 0xED && i+2 < len(s) && s[i+1] >= 0xA0 && s[i+1] <= 0xBF && s[i+2] >= 0x80 && s[i+2] <= 0xBF {
			// surrogate encoded in WTF-8
			r := rune(c&0x0F)<<12 | rune(s[i+1]&0x3F)<<6 | rune(s[i+2]&0x3F)
			out = append(out, r)
			i += 3
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		out = append(out, r)
		i += size
	}
	return out
}

// utf16Units converts a string to UTF-16 code units.
func utf16Units(s string) []uint16 {
	if isASCII(s) {
		u := make([]uint16, len(s))
		for i := 0; i < len(s); i++ {
			u[i] = uint16(s[i])
		}
		return u
	}
	cps := decodeWTF8(s)
	u := make([]uint16, 0, len(cps))
	for _, r := range cps {
		if r >= 0x10000 {
			r -= 0x10000
			u = append(u, uint16(0xD800+(r>>10)), uint16(0xDC00+(r&0x3FF)))
		} else {
			u = append(u, uint16(r))
		}
	}
	return u
}

// unitsToString converts UTF-16 code units to a (WTF-8) string.
func unitsToString(u []uint16) string {
	var b strings.Builder
	for i := 0; i < len(u); i++ {
		c := rune(u[i])
		if c >= 0xD800 && c <= 0xDBFF && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] <= 0xDFFF {
			cp := (c-0xD800)<<10 + (rune(u[i+1]) - 0xDC00) + 0x10000
			b.WriteRune(cp)
			i++
			continue
		}
		writeCodePoint(&b, c)
	}
	return b.String()
}

func strLen(s string) int {
	if isASCII(s) {
		return len(s)
	}
	return len(utf16Units(s))
}

// strAt returns the code unit at index i as a string, or "" if out of range.
func strAt(s string, i int) (string, bool) {
	if isASCII(s) {
		if i < 0 || i >= len(s) {
			return "", false
		}
		return s[i : i+1], true
	}
	u := utf16Units(s)
	if i < 0 || i >= len(u) {
		return "", false
	}
	return unitsToString(u[i : i+1]), true
}

func strSlice(s string, from, to int) string {
	if isASCII(s) {
		if from < 0 {
			from = 0
		}
		if to > len(s) {
			to = len(s)
		}
		if from >= to {
			return ""
		}
		return s[from:to]
	}
	u := utf16Units(s)
	if from < 0 {
		from = 0
	}
	if to > len(u) {
		to = len(u)
	}
	if from >= to {
		return ""
	}
	return unitsToString(u[from:to])
}

// strIndexOf returns the UTF-16 index of sub in s starting at from.
func strIndexOf(s, sub string, from int) int {
	if isASCII(s) && isASCII(sub) {
		if from < 0 {
			from = 0
		}
		if from > len(s) {
			if sub == "" {
				return len(s)
			}
			return -1
		}
		i := strings.Index(s[from:], sub)
		if i < 0 {
			return -1
		}
		return i + from
	}
	u := utf16Units(s)
	su := utf16Units(sub)
	if from < 0 {
		from = 0
	}
	if from > len(u) {
		if len(su) == 0 {
			return len(u)
		}
		return -1
	}
	for i := from; i+len(su) <= len(u); i++ {
		match := true
		for j := range su {
			if u[i+j] != su[j] {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

func strLastIndexOf(s, sub string, from int) int {
	u := utf16Units(s)
	su := utf16Units(sub)
	if from > len(u)-len(su) {
		from = len(u) - len(su)
	}
	for i := from; i >= 0; i-- {
		match := true
		for j := range su {
			if u[i+j] != su[j] {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

// byteOffsetToUnitIndex converts a byte offset in s to a UTF-16 index.
func byteOffsetToUnitIndex(s string, off int) int {
	if isASCII(s) {
		return off
	}
	return strLen(s[:off])
}

// unitIndexToByteOffset converts a UTF-16 index to a byte offset.
func unitIndexToByteOffset(s string, idx int) int {
	if isASCII(s) {
		return idx
	}
	n := 0
	for i := 0; i < len(s); {
		if n >= idx {
			return i
		}
		c := s[i]
		if c < 0x80 {
			n++
			i++
			continue
		}
		if c == 0xED && i+2 < len(s) && s[i+1] >= 0xA0 && s[i+1] <= 0xBF {
			n++
			i += 3
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r >= 0x10000 {
			n += 2
		} else {
			n++
		}
		i += size
	}
	return len(s)
}

func isJSWhitespace(r rune) bool {
	switch r {
	case '\t', '\n', '\v', '\f', '\r', ' ', 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
		return true
	}
	return r >= 0x2000 && r <= 0x200A
}

func trimJS(s string) string {
	return strings.TrimFunc(s, isJSWhitespace)
}

func trimStartJS(s string) string { return strings.TrimLeftFunc(s, isJSWhitespace) }
func trimEndJS(s string) string   { return strings.TrimRightFunc(s, isJSWhitespace) }

// sanitizeUTF8 converts lone surrogates into U+FFFD for output.
func sanitizeUTF8(s string) string {
	if isASCII(s) {
		return s
	}
	cps := decodeWTF8(s)
	var b strings.Builder
	for _, r := range cps {
		if r >= 0xD800 && r <= 0xDFFF || !utf8.ValidRune(r) {
			b.WriteRune(utf8.RuneError)
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}
