		} else {
			s = digits[:1] + "." + digits[1:] + "e" + es + strconv.Itoa(ev)
		}
	}
	return sign + s
}

// numberToStringRadix converts a number to a string in the given radix.
func numberToStringRadix(f float64, radix int) string {
	if radix == 10 {
		return numberToString(f)
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	if f == 0 {
		return "0"
	}
	neg := f < 0
	if neg {
		f = -f
	}
	intPart := math.Floor(f)
	frac := f - intPart
	const chars = "0123456789abcdefghijklmnopqrstuvwxyz"
