	var intStr string
	if intPart < 1e21 {
		bi, _ := big.NewFloat(intPart).Int(nil)
		intStr = bi.Text(radix)
	} else {
		bf := new(big.Float).SetFloat64(intPart)
		bi, _ := bf.Int(nil)
		intStr = bi.Text(radix)
