		if neg {
			return "-" + intStr
		}
		return intStr
	}
	// fraction: port of V8's algorithm
	var b strings.Builder
	b.WriteString(intStr)
	b.WriteByte('.')
	delta := 0.5 * (math.Nextafter(f, math.Inf(1)) - f)
	delta = math.Max(math.Nextafter(0, 1), delta)
	if frac >= delta {
		for {
			frac *= float64(radix)
			delta *= float64(radix)
			digit := int(frac)
			b.WriteByte(chars[digit])
			frac -= float64(digit)
			if frac > 0.5 || (frac == 0.5 && (digit&1) == 1) {
				if frac+delta > 1 {
