	panic(&Throw{Value: r.newError(kind, msg)})
}

func (r *Realm) typeError(msg string)      { r.throwError("TypeError", msg) }
func (r *Realm) rangeError(msg string)     { r.throwError("RangeError", msg) }
func (r *Realm) referenceError(msg string) { r.throwError("ReferenceError", msg) }
func (r *Realm) syntaxError(msg string)    { r.throwError("SyntaxError", msg) }

func throwValue(v Value) { panic(&Throw{Value: v}) }

// --- type checks ---

func isUndefined(v Value) bool { _, ok := v.(Undefined); return ok }
func isNull(v Value) bool      { _, ok := v.(Null); return ok }
func isNullish(v Value) bool   { return isUndefined(v) || isNull(v) }
func isObject(v Value) bool    { _, ok := v.(*Object); return ok }
func isCallable(v Value) bool {
	o, ok := v.(*Object)
	return ok && o.Fn != nil
}

func typeOf(v Value) string {
	switch t := v.(type) {
	case Undefined:
		return "undefined"
	case Null:
		return "object"
	case bool:
		return "boolean"
	case float64:
		return "number"
	case string:
		return "string"
	case *Symbol:
		return "symbol"
	case *big.Int:
		return "bigint"
	case *Object:
		if t.Fn != nil {
			return "function"
		}
		return "object"
	}
	return "undefined"
}

// --- conversions ---

func toBoolean(v Value) bool {
	switch t := v.(type) {
	case Undefined, Null:
		return false
	case bool:
		return t
	case float64:
		return !(t == 0 || math.IsNaN(t))
	case string:
		return t != ""
	case *big.Int:
		return t.Sign() != 0
	}
	return true
}

func (r *Realm) toPrimitive(v Value, hint string) Value {
	o, ok := v.(*Object)
	if !ok {
		return v
	}
	if ex := r.getV(o, r.SymToPrimitive); !isNullish(ex) {
		if !isCallable(ex) {
			r.typeError("Symbol.toPrimitive is not a function")
		}
		h := hint
		if h == "" {
			h = "default"
		}
		res := r.call(ex, o, []Value{h})
		if isObject(res) {
			r.typeError("Cannot convert object to primitive value")
		}
		return res
	}
	order := []string{"valueOf", "toString"}
	if hint == "string" {
		order = []string{"toString", "valueOf"}
	}
	for _, name := range order {
		fn := r.getV(o, name)
		if isCallable(fn) {
			res := r.call(fn, o, nil)
			if !isObject(res) {
				return res
			}
		}
	}
	r.typeError("Cannot convert object to primitive value")
	return nil
}

func toNumberPrim(v Value) float64 {
	switch t := v.(type) {
	case Undefined:
		return math.NaN()
	case Null:
		return 0
	case bool:
		if t {
			return 1
		}
		return 0
	case float64:
		return t
	case string:
		return stringToNumber(t)
	}
	return math.NaN()
}

// toNumber without a realm (no object conversion with user code).
func toNumber(v Value) float64 {
	if o, ok := v.(*Object); ok {
		if o.Prim != nil {
			return toNumberPrim(o.Prim)
		}
		return math.NaN()
	}
	return toNumberPrim(v)
}

func (r *Realm) toNumber(v Value) float64 {
	switch t := v.(type) {
	case *Object:
		return r.toNumber(r.toPrimitive(t, "number"))
	case *Symbol:
		r.typeError("Cannot convert a Symbol value to a number")
	case *big.Int:
		r.typeError("Cannot convert a BigInt value to a number")
	}
	return toNumberPrim(v)
}

// toNumeric returns either float64 or *big.Int.
func (r *Realm) toNumeric(v Value) Value {
	p := r.toPrimitive(v, "number")
	if b, ok := p.(*big.Int); ok {
		return b
	}
	return r.toNumber(p)
}

func (r *Realm) toString(v Value) string {
	switch t := v.(type) {
	case Undefined:
		return "undefined"
	case Null:
		return "null"
	case bool:
		if t {
			return "true"
		}
		return "false"
	case float64:
		return numberToString(t)
	case string:
		return t
	case *Symbol:
		r.typeError("Cannot convert a Symbol value to a string")
	case *big.Int:
		return t.String()
	case *Object:
		return r.toString(r.toPrimitive(t, "string"))
	}
	return ""
}

// toStringNoThrow is used for display purposes.
func toStringNoThrow(v Value) string {
	switch t := v.(type) {
	case Undefined:
		return "undefined"
	case Null:
		return "null"
	case bool:
		if t {
			return "true"
		}
		return "false"
	case float64:
		return numberToString(t)
	case string:
		return t
	case *Symbol:
		return t.String()
	case *big.Int:
		return t.String()
	case *Object:
		if t.Fn != nil {
			return "function"
		}
		return "[object Object]"
	}
	return ""
}

func (r *Realm) toPropertyKey(v Value) PropKey {
	switch t := v.(type) {
	case string:
		return strKey(t)
	case *Symbol:
		return symKey(t)
	case float64:
		return strKey(numberToString(t))
	case *Object:
		p := r.toPrimitive(t, "string")
		if s, ok := p.(*Symbol); ok {
			return symKey(s)
		}
		return strKey(r.toString(p))
	}
	return strKey(r.toString(v))
}

func (r *Realm) toObject(v Value) *Object {
	switch t := v.(type) {
	case *Object:
		return t
	case Undefined, Null:
		r.typeError("Cannot convert undefined or null to object")
	case bool:
		o := newObject(r.BooleanProto)
		o.Class = "Boolean"
		o.Prim = t
		return o
	case float64:
		o := newObject(r.NumberProto)
		o.Class = "Number"
		o.Prim = t
		return o
	case string:
		o := newObject(r.StringProto)
		o.Class = "String"
		o.Prim = t
		return o
	case *Symbol:
		o := newObject(r.SymbolProto)
		o.Class = "Symbol"
		o.Prim = t
		return o
	case *big.Int:
		o := newObject(r.BigIntProto)
		o.Class = "BigInt"
		o.Prim = t
		return o
	}
	r.typeError("Cannot convert to object")
	return nil
}

func (r *Realm) protoOf(v Value) *Object {
	switch t := v.(type) {
	case *Object:
		return t.Proto
	case bool:
		return r.BooleanProto
	case float64:
		return r.NumberProto
	case string:
		return r.StringProto
	case *Symbol:
		return r.SymbolProto
	case *big.Int:
		return r.BigIntProto
	}
	return nil
}

func (r *Realm) toLength(v Value) int {
	n := toIntegerOrInfinity(r.toNumber(v))
	if n <= 0 {
		return 0
	}
	if n > 9007199254740991 {
		return 9007199254740991
	}
	return int(n)
}

func (r *Realm) toInteger(v Value) float64 {
	return toIntegerOrInfinity(r.toNumber(v))
}

// --- property access ---

// getProp looks up a property through the prototype chain.
func (r *Realm) getProp(v Value, key PropKey, receiver Value) Value {
	var o *Object
	switch t := v.(type) {
	case *Object:
		o = t
	case string:
		if !key.IsSymbol() {
			if key.S == "length" {
				return float64(strLen(t))
			}
			if idx, ok := arrayIndex(key.S); ok {
				if s, ok := strAt(t, idx); ok {
					return s
				}
				return undefined
			}
		}
		o = r.StringProto
	case Undefined, Null:
		name := key.S
		if key.IsSymbol() {
			name = key.Sym.String()
		}
		r.typeError("Cannot read property '" + name + "' of undefined")
	default:
		o = r.protoOf(v)
	}
	for o != nil {
		if p := o.getOwn(key); p != nil {
			if p.Accessor {
				if p.Getter == nil {
					return undefined
				}
				return r.call(p.Getter, receiver, nil)
			}
			return p.Value
		}
		o = o.Proto
	}
	return undefined
}

// getV gets a property by string or symbol key.
func (r *Realm) getV(v Value, key interface{}) Value {
	switch k := key.(type) {
	case string:
		return r.getProp(v, strKey(k), v)
	case *Symbol:
		return r.getProp(v, symKey(k), v)
	case PropKey:
		return r.getProp(v, k, v)
	}
	return undefined
}

func (r *Realm) hasProperty(o *Object, key PropKey) bool {
	for o != nil {
		if o.hasOwn(key) {
			return true
		}
		o = o.Proto
	}
	return false
}

// setProp assigns a property, honoring setters and writability.
func (r *Realm) setProp(target Value, key PropKey, v Value, receiver Value) {
	o, ok := target.(*Object)
	if !ok {
		if isNullish(target) {
			r.typeError("Cannot convert undefined or null to object")
		}
		// primitives: setters on prototype may run; otherwise ignore
		proto := r.protoOf(target)
		for p := proto; p != nil; p = p.Proto {
			if pr := p.getOwn(key); pr != nil {
				if pr.Accessor && pr.Setter != nil {
					r.call(pr.Setter, receiver, []Value{v})
				}
				return
			}
		}
		return
	}
	// look for existing own or inherited property
	for p := o; p != nil; p = p.Proto {
		if pr := p.getOwn(key); pr != nil {
			if pr.Accessor {
				if pr.Setter == nil {
					if r.isStrictCtx() {
						name := key.S
						if key.IsSymbol() {
							name = key.Sym.String()
						}
						r.typeError("Cannot assign to read only property '" + name + "' of object")
					}
					return
				}
				r.call(pr.Setter, receiver, []Value{v})
				return
			}
			if p == o {
				if !pr.Writable {
					if r.isStrictCtx() {
						name := key.S
						if key.IsSymbol() {
							name = key.Sym.String()
						}
						r.typeError("Cannot assign to read only property '" + name + "' of object")
					}
					return
				}
				o.setOwn(key, v)
				return
			}
			if !pr.Writable {
				if r.isStrictCtx() {
					r.typeError("Cannot assign to read only property '" + key.S + "' of object")
				}
				return
			}
			break
		}
	}
	if !o.Extensible {
		if r.isStrictCtx() {
			r.typeError("Cannot add property " + key.S + ", object is not extensible")
		}
		return
	}
	o.setOwn(key, v)
}

func (r *Realm) isStrictCtx() bool { return true }

func (r *Realm) deleteProp(target Value, key PropKey) bool {
	o, ok := target.(*Object)
	if !ok {
		if isNullish(target) {
			r.typeError("Cannot convert undefined or null to object")
		}
		return true
	}
	if !o.deleteOwn(key) {
		r.typeError("Cannot delete property '" + key.S + "' of object")
	}
	return true
}

// --- function calls ---

func (r *Realm) call(fnv Value, this Value, args []Value) Value {
	fo, ok := fnv.(*Object)
	if !ok || fo.Fn == nil {
		r.typeError("Value is not a function: " + toStringNoThrow(fnv))
	}
	return r.callFunction(fo, this, args, nil)
}

func (r *Realm) callFunction(fo *Object, this Value, args []Value, newTarget *Object) Value {
	fn := fo.Fn
	if fn.Bound != nil {
		all := append(append([]Value{}, fn.Bound.Args...), args...)
		if newTarget != nil {
			return r.construct(fn.Bound.Target, all, newTarget)
		}
		return r.callFunction(fn.Bound.Target, fn.Bound.This, all, nil)
	}
	r.depth++
	if r.depth > r.MaxDepth {
		r.depth = 0
		r.rangeError("Maximum call stack size exceeded")
	}
	defer func() { r.depth-- }()
	if fn.Native != nil {
		return fn.Native(r, this, args, newTarget)
	}
	if fn.IsClass && newTarget == nil {
		r.typeError("Class constructor " + fn.Name + " cannot be invoked without 'new'")
	}
	return r.callUser(fo, this, args, newTarget)
}

func (r *Realm) construct(ctor *Object, args []Value, newTarget *Object) Value {
	if ctor.Fn == nil || !ctor.Fn.IsCtor {
		r.typeError("Value is not a constructor")
	}
	if newTarget == nil {
		newTarget = ctor
	}
	if ctor.Fn.Bound != nil {
		return r.callFunction(ctor, undefined, args, newTarget)
	}
	if ctor.Fn.Native != nil {
		return r.callFunction(ctor, undefined, args, newTarget)
	}
	if ctor.Fn.Derived {
		// this is created by super()
		res := r.callUser(ctor, nil, args, newTarget)
		return res
	}
	protoV := r.getV(newTarget, "prototype")
	proto, ok := protoV.(*Object)
	if !ok {
		proto = r.ObjectProto
	}
	this := newObject(proto)
	r.initFields(ctor, this)
	res := r.callUser(ctor, this, args, newTarget)
	if ro, ok := res.(*Object); ok {
		return ro
	}
	return this
}

// ordinaryCreateFromConstructor creates an object whose prototype is taken from newTarget.
func (r *Realm) createFromCtor(newTarget *Object, fallback *Object) *Object {
	if newTarget != nil {
		if p, ok := r.getV(newTarget, "prototype").(*Object); ok {
			return newObject(p)
		}
	}
	return newObject(fallback)
}

func (r *Realm) initFields(ctor *Object, this *Object) {
	if len(ctor.ClassFields) == 0 {
		return
	}
	for _, m := range ctor.ClassFields {
		env := &Env{vars: map[string]*Binding{}, parent: ctor.FieldsEnv, funcEnv: true, this: this, hasThis: true, home: ctor}
		var v Value = undefined
		if m.Value != nil {
			v = r.eval(m.Value, env)
		}
		var key PropKey
		if m.Computed {
			key = r.toPropertyKey(r.eval(m.Key, env))
		} else {
			key = strKey(m.Key.(*StringLit).Value)
		}
		if m.Private {
			if this.private == nil {
				this.private = map[string]Value{}
			}
			this.private[key.S] = v
			continue
		}
		this.defineOwn(key, &Prop{Value: v, Enumerable: true, Writable: true, Configurable: true})
	}
}

// --- object creation helpers ---

func (r *Realm) newArray(vals []Value) *Object {
	a := newObject(r.ArrayProto)
	a.Class = "Array"
	if vals == nil {
		vals = []Value{}
	}
	a.Array = vals
	return a
}

func (r *Realm) newPlainObject() *Object { return newObject(r.ObjectProto) }

func (r *Realm) newNativeFunction(name string, length int, fn func(r *Realm, this Value, args []Value, nt *Object) Value) *Object {
	f := newObject(r.FunctionProto)
	f.Class = "Function"
	f.Fn = &Function{Name: name, Native: fn, Length: length, Realm: r}
	f.defineOwn(strKey("length"), &Prop{Value: float64(length), Configurable: true})
	f.defineOwn(strKey("name"), &Prop{Value: name, Configurable: true})
	return f
}

func (r *Realm) newCtor(name string, length int, fn func(r *Realm, this Value, args []Value, nt *Object) Value, proto *Object) *Object {
	c := r.newNativeFunction(name, length, fn)
	c.Fn.IsCtor = true
	if proto != nil {
		c.defineOwn(strKey("prototype"), &Prop{Value: proto})
		proto.defineOwn(strKey("constructor"), &Prop{Value: c, Writable: true, Configurable: true})
	}
	return c
}

func (r *Realm) setMethod(o *Object, name string, length int, fn func(r *Realm, this Value, args []Value, nt *Object) Value) *Object {
	f := r.newNativeFunction(name, length, fn)
	o.defineOwn(strKey(name), &Prop{Value: f, Writable: true, Configurable: true})
	return f
}

func (r *Realm) setSymMethod(o *Object, sym *Symbol, name string, length int, fn func(r *Realm, this Value, args []Value, nt *Object) Value) *Object {
	f := r.newNativeFunction(name, length, fn)
	o.defineOwn(symKey(sym), &Prop{Value: f, Writable: true, Configurable: true})
	return f
}

func (r *Realm) setGetter(o *Object, name string, fn func(r *Realm, this Value) Value) {
	g := r.newNativeFunction("get "+name, 0, func(r *Realm, this Value, args []Value, nt *Object) Value { return fn(r, this) })
	o.defineOwn(strKey(name), &Prop{Accessor: true, Getter: g, Configurable: true})
}

func (r *Realm) setConst(o *Object, name string, v Value) {
	o.defineOwn(strKey(name), &Prop{Value: v})
}

func (r *Realm) setProp2(o *Object, name string, v Value) {
	o.defineOwn(strKey(name), &Prop{Value: v, Writable: true, Configurable: true})
}

func arg(args []Value, i int) Value {
	if i < len(args) {
		return args[i]
	}
	return undefined
}

// --- comparison ---

func strictEquals(a, b Value) bool {
	switch x := a.(type) {
	case Undefined:
		return isUndefined(b)
	case Null:
		return isNull(b)
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case float64:
		y, ok := b.(float64)
		return ok && x == y
	case string:
		y, ok := b.(string)
		return ok && x == y
	case *Symbol:
		y, ok := b.(*Symbol)
		return ok && x == y
	case *big.Int:
		y, ok := b.(*big.Int)
		return ok && x.Cmp(y) == 0
	case *Object:
		y, ok := b.(*Object)
		return ok && x == y
	}
	return false
}

func sameValueZero(a, b Value) bool {
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			if math.IsNaN(x) && math.IsNaN(y) {
				return true
			}
			return x == y
		}
		return false
	}
	return strictEquals(a, b)
}

func sameValue(a, b Value) bool {
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			if math.IsNaN(x) && math.IsNaN(y) {
				return true
			}
			if x == 0 && y == 0 {
				return math.Signbit(x) == math.Signbit(y)
			}
			return x == y
		}
		return false
	}
	return strictEquals(a, b)
}

func (r *Realm) looseEquals(a, b Value) bool {
	ta, tb := typeOf(a), typeOf(b)
	if isNull(a) {
		ta = "null"
	}
	if isNull(b) {
		tb = "null"
	}
	if ta == tb || (ta == "function" && tb == "object") || (ta == "object" && tb == "function") {
		return strictEquals(a, b)
	}
	if isNullish(a) && isNullish(b) {
		return true
	}
	if isNullish(a) || isNullish(b) {
		return false
	}
	switch {
	case ta == "number" && tb == "string":
		return a.(float64) == stringToNumber(b.(string))
	case ta == "string" && tb == "number":
		return stringToNumber(a.(string)) == b.(float64)
	case ta == "bigint" && tb == "string":
		bi, ok := stringToBigInt(b.(string))
		return ok && a.(*big.Int).Cmp(bi) == 0
	case ta == "string" && tb == "bigint":
		bi, ok := stringToBigInt(a.(string))
		return ok && b.(*big.Int).Cmp(bi) == 0
	case ta == "boolean":
		return r.looseEquals(boolToNum(a.(bool)), b)
	case tb == "boolean":
		return r.looseEquals(a, boolToNum(b.(bool)))
	case (ta == "string" || ta == "number" || ta == "bigint" || ta == "symbol") && (tb == "object" || tb == "function"):
		return r.looseEquals(a, r.toPrimitive(b, ""))
	case (ta == "object" || ta == "function") && (tb == "string" || tb == "number" || tb == "bigint" || tb == "symbol"):
		return r.looseEquals(r.toPrimitive(a, ""), b)
	case ta == "bigint" && tb == "number":
		return bigEqualsFloat(a.(*big.Int), b.(float64))
	case ta == "number" && tb == "bigint":
		return bigEqualsFloat(b.(*big.Int), a.(float64))
	}
	return false
}

func boolToNum(b bool) float64 {
	if b {
		return 1
	}
	return 0
}

func bigEqualsFloat(b *big.Int, f float64) bool {
	if math.IsNaN(f) || math.IsInf(f, 0) || f != math.Trunc(f) {
		return false
	}
	bf := new(big.Float).SetInt(b)
	return bf.Cmp(big.NewFloat(f)) == 0
}

func stringToBigInt(s string) (*big.Int, bool) {
	s = trimJS(s)
	if s == "" {
		return new(big.Int), true
	}
	b := new(big.Int)
	if len(s) > 2 && s[0] == '0' {
		switch s[1] {
		case 'x', 'X':
			_, ok := b.SetString(s[2:], 16)
			return b, ok
		case 'o', 'O':
			_, ok := b.SetString(s[2:], 8)
			return b, ok
		case 'b', 'B':
			_, ok := b.SetString(s[2:], 2)
			return b, ok
		}
	}
	for i, c := range s {
		if !(c >= '0' && c <= '9') && !(i == 0 && (c == '-' || c == '+')) {
			return nil, false
		}
	}
	_, ok := b.SetString(s, 10)
	return b, ok
}

// numberOrBigIntToString
func numericString(v Value) string {
	switch t := v.(type) {
	case float64:
		return numberToString(t)
	case *big.Int:
		return t.String()
	}
	return ""
}

func itoa(i int) string { return strconv.Itoa(i) }
