cd /workspace; cat > internal/js/env.go <<'EOF'
package js

type Binding struct {
	Value       Value
	Kind        string // var, let, const, function, param, class
	Initialized bool
}

type Env struct {
	vars    map[string]*Binding
	parent  *Env
	funcEnv bool
	this    Value
	hasThis bool
	newTarget Value
	home    *Object // home object for super lookups
	fnObj   *Object // current function object
	global  *Object // global object for the global env
	args    *Object // arguments object (lazy)
	argVals []Value
	hasArgs bool
	strict  bool
}

func newEnv(parent *Env) *Env {
	return &Env{vars: map[string]*Binding{}, parent: parent}
}

func (e *Env) lookup(name string) (*Binding, *Env) {
	for env := e; env != nil; env = env.parent {
		if b, ok := env.vars[name]; ok {
			return b, env
		}
	}
	return nil, nil
}

func (e *Env) declare(name string, kind string, v Value, initialized bool) *Binding {
	b := &Binding{Value: v, Kind: kind, Initialized: initialized}
	e.vars[name] = b
	return b
}

// funcScope returns the nearest function (or global) environment.
func (e *Env) funcScope() *Env {
	for env := e; env != nil; env = env.parent {
		if env.funcEnv {
			return env
		}
	}
	return e
}

// thisEnv finds the environment that provides `this`.
func (e *Env) thisEnv() *Env {
	for env := e; env != nil; env = env.parent {
		if env.hasThis {
			return env
		}
	}
	return nil
}
