var normal = completion{}

// RunProgram executes a parsed program in the global environment.
func (r *Realm) RunProgram(prog *Program) (result Value, err error) {
	defer func() {
		if rec := recover(); rec != nil {
			switch t := rec.(type) {
			case *Throw:
				err = &JSError{Value: t.Value, Realm: r}
			case *ExitError:
				err = t
			default:
				panic(rec)
			}
		}
	}()
	env := r.GlobalEnv
	r.hoist(prog.Body, env, env, true)
	result = undefined
	for _, st := range prog.Body {
		c := r.exec(st, env)
		if c.kind != ctrlNone {
			break
		}
		if es, ok := st.(*ExprStmt); ok {
			_ = es
			result = c.value
		}
	}
	return result, nil
}

// JSError wraps a thrown JS value as a Go error.
type JSError struct {
	Value Value
	Realm *Realm
}

func (e *JSError) Error() string {
	return e.Realm.errorToString(e.Value)
}

// errorToString mirrors e.toString() for thrown values.
func (r *Realm) errorToString(v Value) string {
	defer func() { recover() }()
	if o, ok := v.(*Object); ok {
		if o.IsError || r.hasProperty(o, strKey("message")) {
			return r.toString(r.call(r.getV(o, "toString"), o, nil))
		}
		return r.toString(v)
	}
	return toStringNoThrow(v)
}

// hoist declares var/function bindings in the function scope and let/const/class in block scope.
func (r *Realm) hoist(body []Node, blockEnv *Env, fnEnv *Env, topLevel bool) {
	for _, st := range body {
		r.hoistStmt(st, blockEnv, fnEnv, true)
	}
}

func (r *Realm) hoistStmt(st Node, blockEnv *Env, fnEnv *Env, direct bool) {
	switch s := st.(type) {
	case *VarDecl:
		if s.Kind == "var" {
			for _, d := range s.Decls {
				for _, name := range patternNames(d.Target) {
					if _, ok := fnEnv.vars[name]; !ok {
						fnEnv.declare(name, "var", undefined, true)
					}
				}
			}
		} else if direct {
			for _, d := range s.Decls {
				for _, name := range patternNames(d.Target) {
					blockEnv.declare(name, s.Kind, undefined, false)
				}
			}
		}
	case *FuncDecl:
		if direct {
			fn := r.makeFunction(s.Func, blockEnv)
			if b, ok := blockEnv.vars[s.Func.Name]; ok {
				b.Value = fn
				b.Initialized = true
			} else {
				blockEnv.declare(s.Func.Name, "function", fn, true)
			}
		}
	case *ClassDecl:
		if direct {
			blockEnv.declare(s.Class.Name, "class", undefined, false)
		}
	case *IfStmt:
		r.hoistStmt(s.Cons, blockEnv, fnEnv, false)
		if s.Alt != nil {
			r.hoistStmt(s.Alt, blockEnv, fnEnv, false)
		}
	case *ForStmt:
		if s.Init != nil {
			if vd, ok := s.Init.(*VarDecl); ok && vd.Kind == "var" {
				r.hoistStmt(vd, blockEnv, fnEnv, false)
			}
		}
		r.hoistStmt(s.Body, blockEnv, fnEnv, false)
	case *ForInStmt:
		if vd, ok := s.Left.(*VarDecl); ok && vd.Kind == "var" {
			r.hoistStmt(vd, blockEnv, fnEnv, false)
		}
		r.hoistStmt(s.Body, blockEnv, fnEnv, false)
	case *WhileStmt:
		r.hoistStmt(s.Body, blockEnv, fnEnv, false)
	case *DoWhileStmt:
		r.hoistStmt(s.Body, blockEnv, fnEnv, false)
	case *BlockStmt:
		for _, b := range s.Body {
			r.hoistStmt(b, blockEnv, fnEnv, false)
		}
	case *TryStmt:
		for _, b := range s.Block.Body {
			r.hoistStmt(b, blockEnv, fnEnv, false)
		}
		if s.Handler != nil {
			for _, b := range s.Handler.Body {
				r.hoistStmt(b, blockEnv, fnEnv, false)
			}
		}
		if s.Finalizer != nil {
			for _, b := range s.Finalizer.Body {
				r.hoistStmt(b, blockEnv, fnEnv, false)
			}
		}
	case *SwitchStmt:
		for _, c := range s.Cases {
			for _, b := range c.Body {
				r.hoistStmt(b, blockEnv, fnEnv, false)
			}
		}
	case *LabeledStmt:
		r.hoistStmt(s.Body, blockEnv, fnEnv, direct)
	}
}

func patternNames(n Node) []string {
	switch p := n.(type) {
	case *Identifier:
		return []string{p.Name}
	case *ArrayPattern:
		var out []string
		for _, el := range p.Elements {
			if el != nil {
				out = append(out, patternNames(el.Target)...)
			}
		}
		if p.Rest != nil {
			out = append(out, patternNames(p.Rest)...)
		}
		return out
	case *ObjectPattern:
		var out []string
		for _, pr := range p.Props {
			out = append(out, patternNames(pr.Target)...)
		}
		if p.Rest != nil {
			out = append(out, patternNames(p.Rest)...)
		}
		return out
	case *PatternElem:
		return patternNames(p.Target)
	}
	return nil
}

// execBlock executes statements in a new block scope.
func (r *Realm) execBlock(body []Node, parent *Env) completion {
	env := newEnv(parent)
	r.hoistBlock(body, env)
	return r.execStmts(body, env)
}

// hoistBlock declares lexical bindings and function declarations for a block.
func (r *Realm) hoistBlock(body []Node, env *Env) {
	for _, st := range body {
		switch s := st.(type) {
		case *VarDecl:
			if s.Kind != "var" {
				for _, d := range s.Decls {
					for _, name := range patternNames(d.Target) {
						env.declare(name, s.Kind, undefined, false)
					}
				}
			}
		case *FuncDecl:
			fn := r.makeFunction(s.Func, env)
			env.declare(s.Func.Name, "function", fn, true)
			// also visible in function scope (sloppy semantics)
			fs := env.funcScope()
			if fs != env {
				if b, ok := fs.vars[s.Func.Name]; !ok || b.Kind == "var" || b.Kind == "function" {
					fs.declare(s.Func.Name, "function", fn, true)
				}
			}
		case *ClassDecl:
			env.declare(s.Class.Name, "class", undefined, false)
		case *LabeledStmt:
			r.hoistBlock([]Node{s.Body}, env)
		}
	}
}

func (r *Realm) execStmts(body []Node, env *Env) completion {
	var last Value = undefined
	for _, st := range body {
		c := r.exec(st, env)
		if c.kind != ctrlNone {
			return c
		}
		if c.value != nil {
			last = c.value
		}
	}
	return completion{value: last}
}

func (r *Realm) exec(st Node, env *Env) completion {
	switch s := st.(type) {
	case *ExprStmt:
		return completion{value: r.eval(s.Expr, env)}
	case *VarDecl:
		for _, d := range s.Decls {
			if d.Init == nil {
				if s.Kind == "var" {
					continue
				}
				// let x; => undefined
				r.bindPattern(d.Target, undefined, env, s.Kind)
				continue
			}
			var v Value
			if id, ok := d.Target.(*Identifier); ok {
				v = r.evalNamed(d.Init, env, id.Name)
			} else {
				v = r.eval(d.Init, env)
			}
			r.bindPattern(d.Target, v, env, s.Kind)
		}
		return normal
	case *FuncDecl:
		return normal
	case *ClassDecl:
		cls := r.makeClass(s.Class, env)
		b, _ := env.lookup(s.Class.Name)
		if b != nil {
			b.Value = cls
			b.Initialized = true
		} else {
			env.declare(s.Class.Name, "class", cls, true)
		}
		return normal
	case *BlockStmt:
		return r.execBlock(s.Body, env)
	case *EmptyStmt, *DebuggerStmt:
		return normal
	case *IfStmt:
		if toBoolean(r.eval(s.Test, env)) {
			return r.exec(s.Cons, env)
		} else if s.Alt != nil {
			return r.exec(s.Alt, env)
		}
		return normal
	case *ReturnStmt:
		var v Value = undefined
		if s.Arg != nil {
			v = r.eval(s.Arg, env)
		}
		return completion{kind: ctrlReturn, value: v}
	case *BreakStmt:
		return completion{kind: ctrlBreak, label: s.Label}
	case *ContinueStmt:
		return completion{kind: ctrlContinue, label: s.Label}
	case *ThrowStmt:
		v := r.eval(s.Arg, env)
		panic(&Throw{Value: v})
	case *WhileStmt:
		return r.execLoop(func() bool { return toBoolean(r.eval(s.Test, env)) }, nil, s.Body, env, "")
	case *DoWhileStmt:
		first := true
		return r.execLoop(func() bool {
			if first {
				first = false
				return true
			}
			return toBoolean(r.eval(s.Test, env))
		}, nil, s.Body, env, "")
	case *ForStmt:
		return r.execFor(s, env, "")
	case *ForInStmt:
		return r.execForIn(s, env, "")
	case *LabeledStmt:
		switch body := s.Body.(type) {
		case *ForStmt:
			return r.execFor(body, env, s.Label)
		case *ForInStmt:
			return r.execForIn(body, env, s.Label)
		case *WhileStmt:
			return r.execLoop(func() bool { return toBoolean(r.eval(body.Test, env)) }, nil, body.Body, env, s.Label)
		case *DoWhileStmt:
			first := true
			return r.execLoop(func() bool {
				if first {
					first = false
					return true
				}
				return toBoolean(r.eval(body.Test, env))
			}, nil, body.Body, env, s.Label)
		}
		c := r.exec(s.Body, env)
		if c.kind == ctrlBreak && c.label == s.Label {
			return normal
		}
		return c
	case *TryStmt:
		return r.execTry(s, env)
	case *SwitchStmt:
		return r.execSwitch(s, env)
	}
	r.syntaxError("Unsupported statement")
	return normal
}

func (r *Realm) execLoop(test func() bool, update func(), body Node, env *Env, label string) completion {
	for test() {
		c := r.exec(body, env)
		switch c.kind {
		case ctrlBreak:
			if c.label == "" || c.label == label {
				return normal
			}
			return c
		case ctrlContinue:
			if c.label != "" && c.label != label {
				return c
			}
		case ctrlReturn:
			return c
		}
		if update != nil {
			update()
		}
	}
	return normal
}

func (r *Realm) execFor(s *ForStmt, parent *Env, label string) completion {
	env := newEnv(parent)
	var lexNames []string
	if s.Init != nil {
		if vd, ok := s.Init.(*VarDecl); ok {
			if vd.Kind != "var" {
				for _, d := range vd.Decls {
					lexNames = append(lexNames, patternNames(d.Target)...)
				}
				for _, n := range lexNames {
					env.declare(n, vd.Kind, undefined, false)
				}
			}
			r.exec(vd, env)
		} else {
			r.eval(s.Init, env)
		}
	}
	iterEnv := env
	for {
		// per-iteration copy of lexical bindings so closures capture distinct values
		if len(lexNames) > 0 {
			ne := newEnv(parent)
			for _, n := range lexNames {
				b := iterEnv.vars[n]
				ne.declare(n, b.Kind, b.Value, true)
			}
			iterEnv = ne
		}
		if s.Test != nil && !toBoolean(r.eval(s.Test, iterEnv)) {
			break
		}
		c := r.exec(s.Body, iterEnv)
		switch c.kind {
		case ctrlBreak:
			if c.label == "" || c.label == label {
				return normal
			}
			return c
		case ctrlContinue:
			if c.label != "" && c.label != label {
				return c
			}
		case ctrlReturn:
			return c
		}
		if s.Update != nil {
			r.eval(s.Update, iterEnv)
		}
	}
	return normal
}

func (r *Realm) execForIn(s *ForInStmt, parent *Env, label string) completion {
	right := r.eval(s.Right, parent)
	assign := func(v Value) *Env {
		env := newEnv(parent)
		if vd, ok := s.Left.(*VarDecl); ok {
			d := vd.Decls[0]
			if vd.Kind == "var" {
				r.bindPattern(d.Target, v, env, "assign")
			} else {
				for _, n := range patternNames(d.Target) {
					env.declare(n, vd.Kind, undefined, false)
				}
				r.bindPattern(d.Target, v, env, vd.Kind)
			}
		} else {
			r.bindPattern(s.Left, v, env, "assign")
		}
		return env
	}
	runBody := func(v Value) (completion, bool) {
		env := assign(v)
		c := r.exec(s.Body, env)
		switch c.kind {
		case ctrlBreak:
			if c.label == "" || c.label == label {
				return normal, true
			}
			return c, true
		case ctrlContinue:
			if c.label != "" && c.label != label {
				return c, true
			}
		case ctrlReturn:
			return c, true
		}
		return normal, false
	}
	if s.Of {
		var result completion
		stopped := false
		r.iterate(right, func(v Value) bool {
			c, stop := runBody(v)
			if stop {
				result = c
				stopped = true
				return false
			}
			return true
		})
		if stopped {
			return result
		}
		return normal
	}
	// for-in: enumerate string keys through prototype chain
	if isNullish(right) {
		return normal
	}
	obj := r.toObject(right)
	seen := map[string]bool{}
	for o := obj; o != nil; o = o.Proto {
		keys := o.ownKeys(false)
		for _, k := range keys {
			if seen[k.S] {
				continue
			}
			seen[k.S] = true
			p := o.getOwn(k)
			if p == nil || !p.Enumerable {
				continue
			}
			if o.Class == "Array" && k.S == "length" {
				continue
			}
			if o.Class == "String" && k.S == "length" {
				continue
			}
			c, stop := runBody(k.S)
			if stop {
				return c
			}
		}
	}
	return normal
}

func (r *Realm) execTry(s *TryStmt, env *Env) (result completion) {
	runFinally := func() {
		if s.Finalizer != nil {
			c := r.execBlock(s.Finalizer.Body, env)
			if c.kind != ctrlNone {
				result = c
			}
		}
	}
	defer func() {
		if rec := recover(); rec != nil {
			th, ok := rec.(*Throw)
			if !ok || s.Handler == nil {
				// propagate after finally
				if s.Finalizer != nil {
					c := r.execBlock(s.Finalizer.Body, env)
					if c.kind != ctrlNone {
						result = c
						return
					}
				}
				panic(rec)
			}
			result = r.runCatch(s, env, th.Value)
			runFinally()
		}
	}()
	result = r.execBlock(s.Block.Body, env)
	runFinally()
	return result
}

func (r *Realm) runCatch(s *TryStmt, env *Env, thrown Value) (result completion) {
	cenv := newEnv(env)
	if s.Param != nil {
		for _, n := range patternNames(s.Param) {
			cenv.declare(n, "let", undefined, false)
		}
		r.bindPattern(s.Param, thrown, cenv, "let")
	}
	// exceptions in catch propagate (after finally handled by caller's defer? no — handle here)
	if s.Finalizer != nil {
		defer func() {
			if rec := recover(); rec != nil {
				c := r.execBlock(s.Finalizer.Body, env)
				if c.kind != ctrlNone {
					result = c
					return
				}
				panic(rec)
			}
		}()
	}
	return r.execBlock(s.Handler.Body, cenv)
}

func (r *Realm) execSwitch(s *SwitchStmt, parent *Env) completion {
	disc := r.eval(s.Disc, parent)
	env := newEnv(parent)
	var all []Node
	for _, c := range s.Cases {
		all = append(all, c.Body...)
	}
	r.hoistBlock(all, env)
	start := -1
	for i, c := range s.Cases {
		if c.Test == nil {
			continue
		}
		if strictEquals(disc, r.eval(c.Test, env)) {
			start = i
			break
		}
	}
	if start < 0 {
		for i, c := range s.Cases {
			if c.Test == nil {
				start = i
				break
			}
		}
	}
	if start < 0 {
		return normal
	}
	for i := start; i < len(s.Cases); i++ {
		c := r.execStmts(s.Cases[i].Body, env)
		switch c.kind {
		case ctrlBreak:
			if c.label == "" {
				return normal
			}
			return c
		case ctrlContinue, ctrlReturn:
			return c
		}
	}
	return normal
}

// --- iteration ---

// iterate calls fn for each value produced by the iterable. fn returns false to stop.
func (r *Realm) iterate(iterable Value, fn func(v Value) bool) {
	if o, ok := iterable.(*Object); ok && o.Class == "Array" {
		// fast path if default iterator
		if it := r.getV(o, r.SymIterator); it == r.arrayValuesFn {
			for i := 0; i < len(o.Array); i++ {
				v := o.Array[i]
				if v == nil {
					v = undefined
				}
				if !fn(v) {
					return
				}
			}
			return
		}
	}
	if s, ok := iterable.(string); ok {
		for _, cp := range decodeWTF8(s) {
			var b strings.Builder
			writeCodePoint(&b, cp)
			if !fn(b.String()) {
				return
			}
		}
		return
	}
	iterFn := r.getV(iterable, r.SymIterator)
	if !isCallable(iterFn) {
		if isNullish(iterable) {
			r.typeError(toStringNoThrow(iterable) + " is not iterable")
		}
		r.typeError("object is not iterable")
	}
	iter := r.call(iterFn, iterable, nil)
	io, ok := iter.(*Object)
	if !ok {
		r.typeError("Result of the Symbol.iterator method is not an object")
	}
	if io.Iter != nil {
		for {
			v, done := io.Iter.Next()
			if done {
				return
			}
			if !fn(v) {
				return
			}
		}
	}
	next := r.getV(io, "next")
	for {
		res := r.call(next, io, nil)
		ro, ok := res.(*Object)
		if !ok {
			r.typeError("Iterator result is not an object")
		}
		if toBoolean(r.getV(ro, "done")) {
			return
		}
		if !fn(r.getV(ro, "value")) {
			if ret := r.getV(io, "return"); isCallable(ret) {
				r.call(ret, io, nil)
			}
			return
		}
	}
}

func (r *Realm) iterToSlice(iterable Value) []Value {
	var out []Value
	r.iterate(iterable, func(v Value) bool {
		out = append(out, v)
		return true
	})
	return out
}

// makeIterator creates an iterator object from a Go next function.
func (r *Realm) makeIterator(proto *Object, next func() (Value, bool)) *Object {
	it := newObject(proto)
	it.Iter = &Iterator{Next: next}
	return it
}

// --- binding / destructuring ---

func (r *Realm) bindPattern(target Node, v Value, env *Env, kind string) {
	switch t := target.(type) {
	case *Identifier:
		if kind == "assign" {
			r.assignIdent(t.Name, v, env)
			return
		}
		b, _ := env.lookup(t.Name)
		if kind == "var" {
			fs := env.funcScope()
			if b == nil {
				fs.declare(t.Name, "var", v, true)
				return
			}
			b.Value = v
			b.Initialized = true
			return
		}
		if b == nil || (kind != "param" && b.Initialized && b.Kind != kind && b.Kind != "param") {
			b = env.declare(t.Name, kind, v, true)
			return
		}
		b.Value = v
		b.Initialized = true
	case *MemberExpr:
		obj := r.eval(t.Object, env)
		key := r.memberKey(t, env)
		r.setProp(obj, key, v, obj)
	case *ArrayPattern:
		if isNullish(v) {
			r.typeError(toStringNoThrow(v) + " is not iterable")
		}
		vals := r.iterToSlice(v)
		for i, el := range t.Elements {
			if el == nil {
				continue
			}
			var item Value = undefined
			if i < len(vals) {
				item = vals[i]
			}
			if isUndefined(item) && el.Default != nil {
				if id, ok := el.Target.(*Identifier); ok {
					item = r.evalNamed(el.Default, env, id.Name)
				} else {
					item = r.eval(el.Default, env)
				}
			}
			r.bindPattern(el.Target, item, env, kind)
		}
		if t.Rest != nil {
			var rest []Value
			if len(t.Elements) < len(vals) {
				rest = append(rest, vals[len(t.Elements):]...)
			}
			r.bindPattern(t.Rest, r.newArray(rest), env, kind)
		}
	case *ObjectPattern:
		if isNullish(v) {
			r.typeError("Cannot destructure '" + toStringNoThrow(v) + "' as it is " + toStringNoThrow(v) + ".")
		}
		used := map[PropKey]bool{}
		for _, pr := range t.Props {
			var key PropKey
			if pr.Computed {
				key = r.toPropertyKey(r.eval(pr.Key, env))
			} else {
				key = strKey(pr.Key.(*StringLit).Value)
			}
			used[key] = true
			item := r.getProp(v, key, v)
			if isUndefined(item) && pr.Default != nil {
				if id, ok := pr.Target.(*Identifier); ok {
					item = r.evalNamed(pr.Default, env, id.Name)
				} else {
					item = r.eval(pr.Default, env)
				}
			}
			r.bindPattern(pr.Target, item, env, kind)
		}
		if t.Rest != nil {
			rest := r.newPlainObject()
			src := r.toObject(v)
			for _, k := range src.ownKeys(true) {
				if used[k] {
					continue
				}
				p := src.getOwn(k)
				if p == nil || !p.Enumerable {
					continue
				}
				rest.setOwn(k, r.getProp(src, k, src))
			}
			r.bindPattern(t.Rest, rest, env, kind)
		}
	case *PatternElem:
		if isUndefined(v) && t.Default != nil {
			v = r.eval(t.Default, env)
		}
		r.bindPattern(t.Target, v, env, kind)
	default:
		r.syntaxError("Invalid destructuring target")
	}
}

func (r *Realm) assignIdent(name string, v Value, env *Env) {
	b, _ := env.lookup(name)
	if b == nil {
		// check global object
		if r.Global.hasOwn(strKey(name)) {
			r.setProp(r.Global, strKey(name), v, r.Global)
			return
		}
		r.referenceError(name + " is not defined")
	}
	if b.Kind == "const" {
		if !b.Initialized {
			r.referenceError("Cannot access '" + name + "' before initialization")
		}
		r.typeError("Assignment to constant variable.")
	}
	if !b.Initialized {
		r.referenceError("Cannot access '" + name + "' before initialization")
	}
	b.Value = v
}

func (r *Realm) lookupIdent(name string, env *Env) Value {
	b, _ := env.lookup(name)
	if b == nil {
		if p := r.Global.getOwn(strKey(name)); p != nil {
			return r.getProp(r.Global, strKey(name), r.Global)
		}
		if name == "undefined" {
			return undefined
		}
		r.referenceError(name + " is not defined")
	}
	if !b.Initialized {
		r.referenceError("Cannot access a variable before initialization")
	}
	return b.Value
}

// --- functions ---

func (r *Realm) makeFunction(lit *FuncLit, env *Env) *Object {
	f := newObject(r.FunctionProto)
	f.Class = "Function"
	fn := &Function{Name: lit.Name, Lit: lit, Env: env, Source: lit.Source, Strict: lit.Strict, Realm: r}
	if !lit.IsArrow && !lit.IsMethod && !lit.IsGen && !lit.IsAsync {
		fn.IsCtor = true
	}
	f.Fn = fn
	n := 0
	for _, p := range lit.Params {
		if p.Rest || p.Default != nil {
			break
		}
		n++
	}
	fn.Length = n
	f.defineOwn(strKey("length"), &Prop{Value: float64(n), Configurable: true})
	f.defineOwn(strKey("name"), &Prop{Value: lit.Name, Configurable: true})
	if fn.IsCtor {
		proto := newObject(r.ObjectProto)
		proto.defineOwn(strKey("constructor"), &Prop{Value: f, Writable: true, Configurable: true})
		f.defineOwn(strKey("prototype"), &Prop{Value: proto, Writable: true})
	}
	return f
}

func (r *Realm) callUser(fo *Object, this Value, args []Value, newTarget *Object) Value {
	fn := fo.Fn
	lit := fn.Lit
	env := newEnv(fn.Env)
	env.funcEnv = true
	env.fnObj = fo
	env.strict = fn.Strict
	env.home = fn.Home
	if !lit.IsArrow {
		env.hasThis = true
		if this == nil {
			// derived constructor before super(): uninitialized this
			env.this = nil
		} else if !fn.Strict && !fn.IsClass {
			if isNullish(this) {
				this = r.Global
			} else if _, ok := this.(*Object); !ok {
				this = r.toObject(this)
			}
			env.this = this
		} else {
			env.this = this
		}
		if newTarget != nil {
			env.newTarget = newTarget
		} else {
			env.newTarget = undefined
		}
		env.argVals = args
		env.hasArgs = true
	}
	// parameters
	for i, p := range lit.Params {
		var v Value = undefined
		if p.Rest {
			var rest []Value
			if i < len(args) {
				rest = append(rest, args[i:]...)
			}
			v = r.newArray(rest)
		} else if i < len(args) {
			v = args[i]
		}
		if isUndefined(v) && p.Default != nil {
			if id, ok := p.Target.(*Identifier); ok {
				v = r.evalNamed(p.Default, env, id.Name)
			} else {
				v = r.eval(p.Default, env)
			}
		}
		for _, n := range patternNames(p.Target) {
			env.declare(n, "param", undefined, true)
		}
		r.bindPattern(p.Target, v, env, "param")
	}
	if lit.ExprBody != nil {
		return r.eval(lit.ExprBody, env)
	}
	// hoist var declarations and functions in body
	r.hoist(lit.Body, env, env, false)
	c := r.execStmts(lit.Body, env)
	if c.kind == ctrlReturn {
		return c.value
	}
	if newTarget != nil && fn.Derived {
		te := env.thisEnv()
		if te == nil || te.this == nil {
			r.referenceError("Must call super constructor in derived class before accessing 'this' or returning from derived constructor")
		}
		return te.this
	}
	return undefined
}

func (r *Realm) argumentsObject(env *Env) Value {
	fe := env
	for fe != nil && !(fe.funcEnv && fe.hasArgs) {
		fe = fe.parent
	}
	if fe == nil {
		r.referenceError("arguments is not defined")
	}
	if fe.args == nil {
		a := newObject(r.ObjectProto)
		a.Class = "Arguments"
		for i, v := range fe.argVals {
			a.setOwn(strKey(itoa(i)), v)
		}
		a.defineOwn(strKey("length"), &Prop{Value: float64(len(fe.argVals)), Writable: true, Configurable: true})
		a.defineOwn(symKey(r.SymIterator), &Prop{Value: r.arrayValuesFn, Writable: true, Configurable: true})
		fe.args = a
	}
	return fe.args
}

// --- classes ---

func (r *Realm) makeClass(c *ClassLit, env *Env) *Object {
	cenv := newEnv(env)
	var parent *Object
	protoParent := r.ObjectProto
	ctorParent := r.FunctionProto
	if c.SuperClass != nil {
		sv := r.eval(c.SuperClass, env)
		if isNull(sv) {
			protoParent = nil
		} else {
			so, ok := sv.(*Object)
			if !ok || so.Fn == nil || !so.Fn.IsCtor {
				r.typeError("Class extends value " + toStringNoThrow(sv) + " is not a constructor or null")
			}
			parent = so
			ctorParent = so
			pp := r.getV(so, "prototype")
			if ppo, ok := pp.(*Object); ok {
				protoParent = ppo
			} else if isNull(pp) {
				protoParent = nil
			} else {
				r.typeError("Class extends value does not have valid prototype property")
			}
		}
	}
	proto := newObject(protoParent)
	var ctorLit *FuncLit
	for _, m := range c.Members {
		if m.Kind == "constructor" {
			ctorLit = m.Value.(*FuncLit)
		}
	}
	if ctorLit == nil {
		ctorLit = &FuncLit{Name: c.Name, Strict: true, IsMethod: true}
		if parent != nil {
			// constructor(...args) { super(...args) }
			ctorLit.Params = []*Param{{Target: &Identifier{Name: "args"}, Rest: true}}
			ctorLit.Body = []Node{&ExprStmt{Expr: &CallExpr{Callee: &SuperExpr{}, Args: []Node{&SpreadElement{Arg: &Identifier{Name: "args"}}}}}}
		}
	}
	ctor := newObject(ctorParent)
	ctor.Class = "Function"
	fn := &Function{Name: c.Name, Lit: ctorLit, Env: cenv, Source: c.Source, Strict: true, IsCtor: true, IsClass: true, Realm: r, Home: proto}
	if parent != nil {
		fn.Derived = true
		fn.Parent = parent
	}
	ctor.Fn = fn
	n := 0
	for _, p := range ctorLit.Params {
		if p.Rest || p.Default != nil {
			break
		}
		n++
	}
	fn.Length = n
	ctor.defineOwn(strKey("length"), &Prop{Value: float64(n), Configurable: true})
	ctor.defineOwn(strKey("name"), &Prop{Value: c.Name, Configurable: true})
	ctor.defineOwn(strKey("prototype"), &Prop{Value: proto})
	proto.defineOwn(strKey("constructor"), &Prop{Value: ctor, Writable: true, Configurable: true})
	if c.Name != "" {
		cenv.declare(c.Name, "const", ctor, true)
	}
	ctor.FieldsEnv = cenv
	var staticInits []func()
	for _, m := range c.Members {
		if m.Kind == "constructor" {
			continue
		}
		target := proto
		if m.Static {
			target = ctor
		}
		switch m.Kind {
		case "method", "get", "set":
			f := r.makeFunction(m.Value.(*FuncLit), cenv)
			f.Fn.Home = target
			f.Fn.IsCtor = false
			f.Fn.Strict = true
			var key PropKey
			if m.Computed {
				key = r.toPropertyKey(r.eval(m.Key, cenv))
			} else {
				key = strKey(m.Key.(*StringLit).Value)
			}
			if m.Private {
				if target.private == nil {
					target.private = map[string]Value{}
				}
				if m.Static {
					target.private[key.S] = f
				} else {
					// instance private methods: store on prototype's private map (looked up via chain)
					proto.private = ensureMap(proto.private)
					proto.private[key.S] = f
				}
				continue
			}
			switch m.Kind {
			case "method":
				f.defineOwn(strKey("name"), &Prop{Value: key.S, Configurable: true})
				target.defineOwn(key, &Prop{Value: f, Writable: true, Configurable: true})
			case "get":
				existing := target.props[key]
				p := &Prop{Accessor: true, Configurable: true}
				if existing != nil && existing.Accessor {
					p = existing
				}
				p.Getter = f
				target.defineOwn(key, p)
			case "set":
				existing := target.props[key]
				p := &Prop{Accessor: true, Configurable: true}
				if existing != nil && existing.Accessor {
					p = existing
				}
				p.Setter = f
				target.defineOwn(key, p)
			}
		case "field":
			if m.Static {
				mm := m
				staticInits = append(staticInits, func() {
					fenv := &Env{vars: map[string]*Binding{}, parent: cenv, funcEnv: true, this: ctor, hasThis: true, home: ctor}
					var v Value = undefined
					if mm.Value != nil {
						v = r.eval(mm.Value, fenv)
					}
					var key PropKey
					if mm.Computed {
						key = r.toPropertyKey(r.eval(mm.Key, cenv))
					} else {
						key = strKey(mm.Key.(*StringLit).Value)
					}
					if mm.Private {
						ctor.private = ensureMap(ctor.private)
						ctor.private[key.S] = v
						return
					}
					ctor.defineOwn(key, &Prop{Value: v, Enumerable: true, Writable: true, Configurable: true})
				})
			} else {
				ctor.ClassFields = append(ctor.ClassFields, m)
			}
		case "static-block":
			mm := m
			staticInits = append(staticInits, func() {
				fenv := &Env{vars: map[string]*Binding{}, parent: cenv, funcEnv: true, this: ctor, hasThis: true, home: ctor}
				lit := mm.Value.(*FuncLit)
				r.hoist(lit.Body, fenv, fenv, false)
				r.execStmts(lit.Body, fenv)
			})
		}
	}
	for _, init := range staticInits {
		init()
	}
	return ctor
}

func ensureMap(m map[string]Value) map[string]Value {
	if m == nil {
		return map[string]Value{}
	}
	return m
}

// --- expressions ---

// evalNamed evaluates an expression; anonymous functions/classes get the given name.
func (r *Realm) evalNamed(n Node, env *Env, name string) Value {
	switch e := n.(type) {
	case *FuncLit:
		if e.Name == "" {
			f := r.makeFunction(e, env)
			f.Fn.Name = name
			f.defineOwn(strKey("name"), &Prop{Value: name, Configurable: true})
			return f
		}
	case *ClassLit:
		if e.Name == "" {
			c := r.makeClass(e, env)
			c.Fn.Name = name
			c.defineOwn(strKey("name"), &Prop{Value: name, Configurable: true})
			return c
		}
	}
	return r.eval(n, env)
}

func (r *Realm) eval(n Node, env *Env) Value {
	switch e := n.(type) {
	case *NumberLit:
		return e.Value
	case *StringLit:
		return e.Value
	case *BoolLit:
		return e.Value
	case *NullLit:
		return null
	case *BigIntLit:
		return parseBigIntLiteral(e.Raw)
	case *Identifier:
		if e.Name == "undefined" {
			if b, _ := env.lookup("undefined"); b == nil {
				return undefined
			}
		}
		if e.Name == "arguments" {
			if b, _ := env.lookup("arguments"); b == nil {
				return r.argumentsObject(env)
			}
		}
		if e.Name == "new.target" {
			te := env.thisEnv()
			if te == nil || te.newTarget == nil {
				return undefined
			}
			return te.newTarget
		}
		return r.lookupIdent(e.Name, env)
	case *ThisExpr:
		te := env.thisEnv()
		if te == nil {
			return r.Global
		}
		if te.this == nil {
			r.referenceError("Must call super constructor in derived class before accessing 'this' or returning from derived constructor")
		}
		return te.this
	case *TemplateLit:
		var b strings.Builder
		for i, q := range e.Quasis {
			b.WriteString(q)
			if i < len(e.Exprs) {
				v := r.eval(e.Exprs[i], env)
				if _, ok := v.(*Symbol); ok {
					r.typeError("Cannot convert a Symbol value to a string")
				}
				b.WriteString(r.toString(v))
			}
		}
		return b.String()
	case *TaggedTemplate:
		return r.evalTaggedTemplate(e, env)
	case *RegexLit:
		return r.newRegExp(e.Pattern, e.Flags)
	case *ArrayLit:
		vals := make([]Value, 0, len(e.Elements))
		for _, el := range e.Elements {
			if el == nil {
				vals = append(vals, nil)
				continue
			}
			if sp, ok := el.(*SpreadElement); ok {
				v := r.eval(sp.Arg, env)
				vals = append(vals, r.iterToSlice(v)...)
				continue
			}
			vals = append(vals, r.eval(el, env))
		}
		return r.newArray(vals)
	case *ObjectLit:
		return r.evalObjectLit(e, env)
	case *FuncLit:
		f := r.makeFunction(e, env)
		if e.Name != "" && !e.IsArrow && !e.IsMethod {
			// named function expression: name binding in its own scope
			fenv := newEnv(env)
			fenv.declare(e.Name, "const", f, true)
			f.Fn.Env = fenv
		}
		return f
	case *ClassLit:
		return r.makeClass(e, env)
	case *UnaryExpr:
		return r.evalUnary(e, env)
	case *UpdateExpr:
		return r.evalUpdate(e, env)
	case *BinaryExpr:
		l := r.eval(e.Left, env)
		rv := r.eval(e.Right, env)
		return r.binaryOp(e.Op, l, rv)
	case *LogicalExpr:
		l := r.eval(e.Left, env)
		switch e.Op {
		case "&&":
			if !toBoolean(l) {
				return l
			}
			return r.eval(e.Right, env)
		case "||":
			if toBoolean(l) {
				return l
			}
			return r.eval(e.Right, env)
		case "??":
			if !isNullish(l) {
				return l
			}
			return r.eval(e.Right, env)
		}
	case *CondExpr:
		if toBoolean(r.eval(e.Test, env)) {
			return r.eval(e.Cons, env)
		}
		return r.eval(e.Alt, env)
	case *SeqExpr:
		var v Value = undefined
		for _, x := range e.Exprs {
			v = r.eval(x, env)
		}
		return v
	case *AssignExpr:
		return r.evalAssign(e, env)
	case *MemberExpr:
		v, _ := r.evalMember(e, env, false)
		return v
	case *OptionalChain:
		v, _ := r.evalChain(e.Expr, env)
		return v
	case *CallExpr:
		v, _ := r.evalCall(e, env, false)
		return v
	case *NewExpr:
		callee := r.eval(e.Callee, env)
		args := r.evalArgs(e.Args, env)
		co, ok := callee.(*Object)
		if !ok {
			r.typeError("Value is not an object: " + toStringNoThrow(callee))
		}
		if co.Fn == nil || !co.Fn.IsCtor {
			r.typeError("Value is not a constructor")
		}
		return r.construct(co, args, nil)
	case *SpreadElement:
		r.syntaxError("Unexpected spread")
	case *SuperExpr:
		r.syntaxError("'super' keyword unexpected here")
	}
	r.syntaxError("Unsupported expression")
	return undefined
}

func (r *Realm) evalTaggedTemplate(e *TaggedTemplate, env *Env) Value {
	var fn Value
	var this Value = undefined
	if m, ok := e.Tag.(*MemberExpr); ok {
		obj := r.eval(m.Object, env)
		key := r.memberKey(m, env)
		fn = r.getProp(obj, key, obj)
		this = obj
	} else {
		fn = r.eval(e.Tag, env)
	}
	cooked := make([]Value, len(e.Quasi.Quasis))
	raws := make([]Value, len(e.Quasi.Raws))
	for i, q := range e.Quasi.Quasis {
		cooked[i] = q
	}
	for i, q := range e.Quasi.Raws {
		raws[i] = q
	}
	strs := r.newArray(cooked)
	strs.defineOwn(strKey("raw"), &Prop{Value: r.newArray(raws)})
	args := []Value{strs}
	for _, x := range e.Quasi.Exprs {
		args = append(args, r.eval(x, env))
	}
	return r.call(fn, this, args)
}

func (r *Realm) evalObjectLit(e *ObjectLit, env *Env) Value {
	obj := r.newPlainObject()
	for _, p := range e.Props {
		if p.Kind == "spread" {
			src := r.eval(p.Value, env)
			if isNullish(src) {
				continue
			}
			if s, ok := src.(string); ok {
				for i, u := range utf16Units(s) {
					obj.setOwn(strKey(itoa(i)), unitsToString([]uint16{u}))
				}
				continue
			}
			so, ok := src.(*Object)
			if !ok {
				continue
			}
			for _, k := range so.ownKeys(true) {
				pr := so.getOwn(k)
				if pr == nil || !pr.Enumerable {
					continue
				}
				obj.setOwn(k, r.getProp(so, k, so))
			}
			continue
		}
		var key PropKey
		if p.Computed {
			key = r.toPropertyKey(r.eval(p.Key, env))
		} else {
			key = strKey(p.Key.(*StringLit).Value)
		}
		switch p.Kind {
		case "init":
			var v Value
			if !p.Computed {
				v = r.evalNamed(p.Value, env, key.S)
			} else {
				v = r.eval(p.Value, env)
			}
			if key.S == "__proto__" && !p.Computed && !p.Shorthand {
				if po, ok := v.(*Object); ok {
					obj.Proto = po
				} else if isNull(v) {
					obj.Proto = nil
				}
				continue
			}
			obj.defineOwn(key, &Prop{Value: v, Enumerable: true, Writable: true, Configurable: true})
		case "method":
			f := r.makeFunction(p.Value.(*FuncLit), env)
			f.Fn.Home = obj
			f.Fn.IsCtor = false
			name := key.S
			if key.IsSymbol() {
				name = "[" + key.Sym.Description + "]"
			}
			f.Fn.Name = name
			f.defineOwn(strKey("name"), &Prop{Value: name, Configurable: true})
			obj.defineOwn(key, &Prop{Value: f, Enumerable: true, Writable: true, Configurable: true})
		case "get", "set":
			f := r.makeFunction(p.Value.(*FuncLit), env)
			f.Fn.Home = obj
			f.Fn.IsCtor = false
			existing := obj.props[key]
			pr := &Prop{Accessor: true, Enumerable: true, Configurable: true}
			if existing != nil && existing.Accessor {
				pr = existing
			}
			if p.Kind == "get" {
				pr.Getter = f
			} else {
				pr.Setter = f
			}
			obj.defineOwn(key, pr)
		}
	}
	return obj
}

func (r *Realm) evalArgs(args []Node, env *Env) []Value {
	out := make([]Value, 0, len(args))
	for _, a := range args {
		if sp, ok := a.(*SpreadElement); ok {
			v := r.eval(sp.Arg, env)
			out = append(out, r.iterToSlice(v)...)
			continue
		}
		out = append(out, r.eval(a, env))
	}
	return out
}

func (r *Realm) memberKey(m *MemberExpr, env *Env) PropKey {
	if m.Computed {
		return r.toPropertyKey(r.eval(m.Prop, env))
	}
	return strKey(m.Prop.(*Identifier).Name)
}

// evalChain evaluates an optional chain; returns (value, shortCircuited).
func (r *Realm) evalChain(n Node, env *Env) (Value, bool) {
	switch e := n.(type) {
	case *MemberExpr:
		return r.evalMember(e, env, true)
	case *CallExpr:
		return r.evalCall(e, env, true)
	}
	return r.eval(n, env), false
}

func (r *Realm) evalMember(e *MemberExpr, env *Env, chain bool) (Value, bool) {
	if _, ok := e.Object.(*SuperExpr); ok {
		te := env.thisEnv()
		home := r.findHome(env)
		if home == nil {
			r.syntaxError("'super' keyword unexpected here")
		}
		key := r.memberKey(e, env)
		var this Value = undefined
		if te != nil && te.this != nil {
			this = te.this
		}
		if home.Proto == nil {
			return undefined, false
		}
		return r.getProp(home.Proto, key, this), false
	}
	var obj Value
	var short bool
	if chain {
		obj, short = r.evalChain(e.Object, env)
		if short {
			return undefined, true
		}
	} else {
		obj = r.eval(e.Object, env)
	}
	if e.Optional && isNullish(obj) {
		return undefined, true
	}
	if id, ok := e.Prop.(*Identifier); ok && !e.Computed && strings.HasPrefix(id.Name, "#") {
		return r.getPrivate(obj, id.Name), false
	}
	key := r.memberKey(e, env)
	if isNullish(obj) {
		name := key.S
		if key.IsSymbol() {
			name = key.Sym.String()
		}
		r.typeError("Cannot read property '" + name + "' of undefined")
	}
	return r.getProp(obj, key, obj), false
}

func (r *Realm) getPrivate(obj Value, name string) Value {
	o, ok := obj.(*Object)
	if !ok {
		r.typeError("Cannot read private member " + name + " from a non-object")
	}
	for p := o; p != nil; p = p.Proto {
		if p.private != nil {
			if v, ok := p.private[name]; ok {
				return v
			}
		}
	}
	r.typeError("Cannot read private member " + name + " from an object whose class did not declare it")
	return undefined
}

func (r *Realm) setPrivate(obj Value, name string, v Value) {
	o, ok := obj.(*Object)
	if !ok {
		r.typeError("Cannot write private member " + name + " to a non-object")
	}
	for p := o; p != nil; p = p.Proto {
		if p.private != nil {
			if _, ok := p.private[name]; ok {
				p.private[name] = v
				return
			}
		}
	}
	if o.private == nil {
		o.private = map[string]Value{}
	}
	o.private[name] = v
}

func (r *Realm) findHome(env *Env) *Object {
	for e := env; e != nil; e = e.parent {
		if e.home != nil {
			return e.home
		}
	}
	return nil
}

func (r *Realm) evalCall(e *CallExpr, env *Env, chain bool) (Value, bool) {
	// super(...)
	if _, ok := e.Callee.(*SuperExpr); ok {
		return r.evalSuperCall(e, env), false
	}
	var fn Value
	var this Value = undefined
	switch c := e.Callee.(type) {
	case *MemberExpr:
		var obj Value
		if _, isSuper := c.Object.(*SuperExpr); isSuper {
			v, _ := r.evalMember(c, env, false)
			fn = v
			te := env.thisEnv()
			if te != nil && te.this != nil {
				this = te.this
			}
			break
		}
		var short bool
		if chain {
			obj, short = r.evalChain(c.Object, env)
			if short {
				return undefined, true
			}
		} else {
			obj = r.eval(c.Object, env)
		}
		if c.Optional && isNullish(obj) {
			return undefined, true
		}
		if id, ok := c.Prop.(*Identifier); ok && !c.Computed && strings.HasPrefix(id.Name, "#") {
			fn = r.getPrivate(obj, id.Name)
			this = obj
			break
		}
		key := r.memberKey(c, env)
		if isNullish(obj) {
			name := key.S
			if key.IsSymbol() {
				name = key.Sym.String()
			}
			r.typeError("Cannot read property '" + name + "' of undefined")
		}
		fn = r.getProp(obj, key, obj)
		this = obj
		if fo, ok := fn.(*Object); !ok || fo.Fn == nil {
			if e.Optional && isNullish(fn) {
				return undefined, true
			}
			if _, isObj := obj.(*Object); isObj {
				if isUndefined(fn) {
					name := key.S
					if key.IsSymbol() {
						name = key.Sym.String()
					}
					r.typeError("Object has no member '" + name + "'")
				}
				r.typeError("Not a function: " + toStringNoThrow(fn))
			}
			if isUndefined(fn) {
				if _, isStr := obj.(string); isStr {
					r.typeError("Object has no member '" + key.S + "'")
				}
				r.typeError("Value is not an object: " + toStringNoThrow(obj))
			}
			r.typeError("Value is not an object: " + toStringNoThrow(obj))
		}
	case *Identifier:
		fn = r.eval(c, env)
		if c.Name == "eval" {
			if fo, ok := fn.(*Object); ok && fo == r.evalFn {
				args := r.evalArgs(e.Args, env)
				return r.directEval(args, env), false
			}
		}
	default:
		if chain {
			var short bool
			fn, short = r.evalChain(e.Callee, env)
			if short {
				return undefined, true
			}
		} else {
			fn = r.eval(e.Callee, env)
		}
	}
	if e.Optional && isNullish(fn) {
		return undefined, true
	}
	args := r.evalArgs(e.Args, env)
	fo, ok := fn.(*Object)
	if !ok || fo.Fn == nil {
		if ok {
			r.typeError("Not a function: " + toStringNoThrow(fn))
		}
		r.typeError("Value is not an object: " + toStringNoThrow(fn))
	}
	return r.callFunction(fo, this, args, nil), false
}

func (r *Realm) evalSuperCall(e *CallExpr, env *Env) Value {
	te := env.thisEnv()
	if te == nil || te.fnObj == nil || te.fnObj.Fn == nil || te.fnObj.Fn.Parent == nil {
		// look up the function env
		fe := env
		for fe != nil && (fe.fnObj == nil || fe.fnObj.Fn.Parent == nil) {
			fe = fe.parent
		}
		if fe == nil {
			r.syntaxError("'super' keyword unexpected here")
		}
		te = fe
	}
	if te.this != nil {
		r.referenceError("Super constructor may only be called once")
	}
	parent := te.fnObj.Fn.Parent
	args := r.evalArgs(e.Args, env)
	nt, _ := te.newTarget.(*Object)
	if nt == nil {
		nt = te.fnObj
	}
	res := r.construct(parent, args, nt)
	ro, ok := res.(*Object)
	if !ok {
		r.typeError("Super constructor did not return an object")
	}
	te.this = ro
	r.initFields(te.fnObj, ro)
	return undefined
}

func (r *Realm) directEval(args []Value, env *Env) Value {
	if len(args) == 0 {
		return undefined
	}
	src, ok := args[0].(string)
	if !ok {
		return args[0]
	}
	prog, perr := Parse(src, env.strict)
	if perr != nil {
		r.syntaxError(perr.Message)
	}
	eenv := newEnv(env)
	r.hoist(prog.Body, eenv, env.funcScope(), false)
	var last Value = undefined
	for _, st := range prog.Body {
		c := r.exec(st, eenv)
		if c.kind != ctrlNone {
			break
		}
		if _, ok := st.(*ExprStmt); ok {
			last = c.value
		}
	}
	return last
}

func (r *Realm) evalUnary(e *UnaryExpr, env *Env) Value {
	switch e.Op {
	case "typeof":
		if id, ok := e.Arg.(*Identifier); ok {
			if b, _ := env.lookup(id.Name); b == nil && !r.Global.hasOwn(strKey(id.Name)) {
				return "undefined"
			}
		}
		return typeOf(r.eval(e.Arg, env))
	case "delete":
		switch t := e.Arg.(type) {
		case *MemberExpr:
			obj := r.eval(t.Object, env)
			key := r.memberKey(t, env)
			return r.deleteProp(obj, key)
		case *OptionalChain:
			if m, ok := t.Expr.(*MemberExpr); ok {
				obj, short := r.evalChain(m.Object, env)
				if short || (m.Optional && isNullish(obj)) {
					return true
				}
				return r.deleteProp(obj, r.memberKey(m, env))
			}
			r.eval(e.Arg, env)
			return true
		case *Identifier:
			r.syntaxError("Delete of an unqualified identifier in strict mode")
		}
		r.eval(e.Arg, env)
		return true
	case "void":
		r.eval(e.Arg, env)
		return undefined
	case "!":
		return !toBoolean(r.eval(e.Arg, env))
	case "-":
		v := r.toNumeric(r.eval(e.Arg, env))
		if b, ok := v.(*big.Int); ok {
			return new(big.Int).Neg(b)
		}
		return -v.(float64)
	case "+":
		return r.toNumber(r.eval(e.Arg, env))
	case "~":
		v := r.toNumeric(r.eval(e.Arg, env))
		if b, ok := v.(*big.Int); ok {
			return new(big.Int).Not(b)
		}
		return float64(^toInt32(v.(float64)))
	}
	r.syntaxError("Unknown unary operator " + e.Op)
	return undefined
}

func (r *Realm) evalUpdate(e *UpdateExpr, env *Env) Value {
	old := r.toNumeric(r.eval(e.Arg, env))
	var nv Value
	if b, ok := old.(*big.Int); ok {
		if e.Op == "++" {
			nv = new(big.Int).Add(b, big.NewInt(1))
		} else {
			nv = new(big.Int).Sub(b, big.NewInt(1))
		}
	} else {
		f := old.(float64)
		if e.Op == "++" {
			nv = f + 1
		} else {
			nv = f - 1
		}
	}
	r.assignTo(e.Arg, nv, env)
	if e.Prefix {
		return nv
	}
	return old
}

func (r *Realm) assignTo(target Node, v Value, env *Env) {
	switch t := target.(type) {
	case *Identifier:
		r.assignIdent(t.Name, v, env)
	case *MemberExpr:
		if _, ok := t.Object.(*SuperExpr); ok {
			te := env.thisEnv()
			key := r.memberKey(t, env)
			r.setProp(te.this, key, v, te.this)
			return
		}
		obj := r.eval(t.Object, env)
		if id, ok := t.Prop.(*Identifier); ok && !t.Computed && strings.HasPrefix(id.Name, "#") {
			r.setPrivate(obj, id.Name, v)
			return
		}
		key := r.memberKey(t, env)
		if isNullish(obj) {
			r.typeError("Cannot convert undefined or null to object")
		}
		r.setProp(obj, key, v, obj)
	default:
		r.bindPattern(target, v, env, "assign")
	}
}

func (r *Realm) evalAssign(e *AssignExpr, env *Env) Value {
	if e.Op == "=" {
		var v Value
		if id, ok := e.Target.(*Identifier); ok {
			v = r.evalNamed(e.Value, env, id.Name)
		} else {
			v = r.eval(e.Value, env)
		}
		// evaluate member target object before value per spec order? keep simple
		r.assignTo(e.Target, v, env)
		return v
	}
	// compound
	var cur Value
	var setter func(Value)
	switch t := e.Target.(type) {
	case *Identifier:
		cur = r.eval(t, env)
		setter = func(v Value) { r.assignIdent(t.Name, v, env) }
	case *MemberExpr:
		obj := r.eval(t.Object, env)
		if id, ok := t.Prop.(*Identifier); ok && !t.Computed && strings.HasPrefix(id.Name, "#") {
			cur = r.getPrivate(obj, id.Name)
			setter = func(v Value) { r.setPrivate(obj, id.Name, v) }
			break
		}
		key := r.memberKey(t, env)
		if isNullish(obj) {
			r.typeError("Cannot read property '" + key.S + "' of undefined")
		}
		cur = r.getProp(obj, key, obj)
		setter = func(v Value) { r.setProp(obj, key, v, obj) }
	default:
		r.syntaxError("Invalid left-hand side in assignment")
	}
	switch e.Op {
	case "&&=":
		if !toBoolean(cur) {
			return cur
		}
		v := r.eval(e.Value, env)
		setter(v)
		return v
	case "||=":
		if toBoolean(cur) {
			return cur
		}
		v := r.eval(e.Value, env)
		setter(v)
		return v
	case "??=":
		if !isNullish(cur) {
			return cur
		}
		v := r.eval(e.Value, env)
		setter(v)
		return v
	}
	rv := r.eval(e.Value, env)
	op := strings.TrimSuffix(e.Op, "=")
	res := r.binaryOp(op, cur, rv)
	setter(res)
	return res
}

// binaryOp evaluates arithmetic/comparison operators.
func (r *Realm) binaryOp(op string, l, rv Value) Value {
	switch op {
	case "+":
		lp := r.toPrimitive(l, "")
		rp := r.toPrimitive(rv, "")
		_, ls := lp.(string)
		_, rs := rp.(string)
		if ls || rs {
			return r.toString(lp) + r.toString(rp)
		}
		ln := r.toNumeric(lp)
		rn := r.toNumeric(rp)
		return r.arith("+", ln, rn)
	case "-", "*", "/", "%", "**", "<<", ">>", ">>>", "&", "|", "^":
		ln := r.toNumeric(l)
		rn := r.toNumeric(rv)
		return r.arith(op, ln, rn)
	case "==":
		return r.looseEquals(l, rv)
	case "!=":
		return !r.looseEquals(l, rv)
	case "===":
		return strictEquals(l, rv)
	case "!==":
		return !strictEquals(l, rv)
	case "<":
		res := r.lessThan(l, rv, true)
		return res == 1
	case ">":
		res := r.lessThan(rv, l, false)
		return res == 1
	case "<=":
		res := r.lessThan(rv, l, false)
		return res == 0
	case ">=":
		res := r.lessThan(l, rv, true)
		return res == 0
	case "instanceof":
		return r.instanceOf(l, rv)
	case "in":
		ro, ok := rv.(*Object)
		if !ok {
			r.typeError("Value is not an object: " + toStringNoThrow(rv))
		}
		return r.hasProperty(ro, r.toPropertyKey(l))
	}
	r.syntaxError("Unknown operator " + op)
	return undefined
}

// lessThan returns 1 if l < r, 0 if not, -1 if undefined (NaN).
func (r *Realm) lessThan(l, rv Value, leftFirst bool) int {
	var lp, rp Value
	if leftFirst {
		lp = r.toPrimitive(l, "number")
		rp = r.toPrimitive(rv, "number")
	} else {
		rp = r.toPrimitive(rv, "number")
		lp = r.toPrimitive(l, "number")
	}
	ls, lok := lp.(string)
	rs, rok := rp.(string)
	if lok && rok {
		lu := utf16Units(ls)
		ru := utf16Units(rs)
		for i := 0; i < len(lu) && i < len(ru); i++ {
			if lu[i] != ru[i] {
				if lu[i] < ru[i] {
					return 1
				}
				return 0
			}
		}
		if len(lu) < len(ru) {
			return 1
		}
		return 0
	}
	lb, lbig := lp.(*big.Int)
	rb, rbig := rp.(*big.Int)
	if lbig && rok {
		rbi, ok := stringToBigInt(rs)
		if !ok {
			return -1
		}
		if lb.Cmp(rbi) < 0 {
			return 1
		}
		return 0
	}
	if lok && rbig {
		lbi, ok := stringToBigInt(ls)
		if !ok {
			return -1
		}
		if lbi.Cmp(rb) < 0 {
			return 1
		}
		return 0
	}
	ln := r.toNumeric(lp)
	rn := r.toNumeric(rp)
	lb, lbig = ln.(*big.Int)
	rb, rbig = rn.(*big.Int)
	if lbig && rbig {
		if lb.Cmp(rb) < 0 {
			return 1
		}
		return 0
	}
	if lbig || rbig {
		var lf, rf *big.Float
		if lbig {
			lf = new(big.Float).SetInt(lb)
			f := rn.(float64)
			if math.IsNaN(f) {
				return -1
			}
			if math.IsInf(f, 1) {
				return 1
			}
			if math.IsInf(f, -1) {
				return 0
			}
			rf = big.NewFloat(f)
		} else {
			f := ln.(float64)
			if math.IsNaN(f) {
				return -1
			}
			if math.IsInf(f, -1) {
				return 1
			}
			if math.IsInf(f, 1) {
				return 0
			}
			lf = big.NewFloat(f)
			rf = new(big.Float).SetInt(rb)
		}
		if lf.Cmp(rf) < 0 {
			return 1
		}
		return 0
	}
	lf := ln.(float64)
	rf := rn.(float64)
	if math.IsNaN(lf) || math.IsNaN(rf) {
		return -1
	}
	if lf < rf {
		return 1
	}
	return 0
}

func (r *Realm) arith(op string, ln, rn Value) Value {
	lb, lbig := ln.(*big.Int)
	rb, rbig := rn.(*big.Int)
	if lbig != rbig {
		r.typeError("Cannot mix BigInt and other types, use explicit conversions")
	}
	if lbig {
		switch op {
		case "+":
			return new(big.Int).Add(lb, rb)
		case "-":
			return new(big.Int).Sub(lb, rb)
		case "*":
			return new(big.Int).Mul(lb, rb)
		case "/":
			if rb.Sign() == 0 {
				r.rangeError("Division by zero")
			}
			return new(big.Int).Quo(lb, rb)
		case "%":
			if rb.Sign() == 0 {
				r.rangeError("Division by zero")
			}
			return new(big.Int).Rem(lb, rb)
		case "**":
			if rb.Sign() < 0 {
				r.rangeError("Exponent must be non-negative")
			}
			return new(big.Int).Exp(lb, rb, nil)
		case "<<":
			return new(big.Int).Lsh(lb, uint(rb.Int64()))
		case ">>":
			return new(big.Int).Rsh(lb, uint(rb.Int64()))
		case ">>>":
			r.typeError("BigInts have no unsigned right shift, use >> instead")
		case "&":
			return new(big.Int).And(lb, rb)
		case "|":
			return new(big.Int).Or(lb, rb)
		case "^":
			return new(big.Int).Xor(lb, rb)
		}
	}
	a := ln.(float64)
	b := rn.(float64)
	switch op {
	case "+":
		return a + b
	case "-":
		return a - b
	case "*":
		return a * b
	case "/":
		return a / b
	case "%":
		if math.IsInf(b, 0) && !math.IsInf(a, 0) && !math.IsNaN(a) {
			return a
		}
		return math.Mod(a, b)
	case "**":
		return jsPow(a, b)
	case "<<":
		return float64(toInt32(a) << (toUint32(b) & 31))
	case ">>":
		return float64(toInt32(a) >> (toUint32(b) & 31))
	case ">>>":
		return float64(toUint32(a) >> (toUint32(b) & 31))
	case "&":
		return float64(toInt32(a) & toInt32(b))
	case "|":
		return float64(toInt32(a) | toInt32(b))
	case "^":
		return float64(toInt32(a) ^ toInt32(b))
	}
	return math.NaN()
}

func jsPow(a, b float64) float64 {
	if math.IsNaN(b) {
		return math.NaN()
	}
	if b == 0 {
		return 1
	}
	if (a == 1 || a == -1) && math.IsInf(b, 0) {
		return math.NaN()
	}
	return math.Pow(a, b)
}

func (r *Realm) instanceOf(l, rv Value) bool {
	ro, ok := rv.(*Object)
	if !ok {
		r.typeError("Value is not an object: " + toStringNoThrow(rv))
	}
	if h := r.getV(ro, r.SymHasInstance); !isNullish(h) && h != r.funcHasInstance {
		return toBoolean(r.call(h, ro, []Value{l}))
	}
	if ro.Fn == nil {
		r.typeError("Right-hand side of 'instanceof' is not callable")
	}
	if ro.Fn.Bound != nil {
		return r.instanceOf(l, ro.Fn.Bound.Target)
	}
	lo, ok := l.(*Object)
	if !ok {
		return false
	}
	protoV := r.getV(ro, "prototype")
	proto, ok := protoV.(*Object)
	if !ok {
		r.typeError("Function has non-object prototype in instanceof check")
	}
	for p := lo.Proto; p != nil; p = p.Proto {
		if p == proto {
			return true
		}
	}
	return false
}
