// materializeArray moves array elements into props so flags can be set (used by freeze).
func (r *Realm) materializeArray(o *Object) {
	// arrays keep dense storage; freezing is approximated by marking non-extensible
}

func (r *Realm) objectToString(this Value) string {
	switch t := this.(type) {
	case Undefined:
		return "[object Undefined]"
	case Null:
		return "[object Null]"
	case *Object:
		tag := "Object"
		switch t.Class {
		case "Array":
			tag = "Array"
		case "Function":
			tag = "Function"
		case "Error":
			tag = "Error"
		case "Boolean":
			tag = "Boolean"
		case "Number":
			tag = "Number"
		case "String":
			tag = "String"
		case "Date":
			tag = "Date"
		case "RegExp":
			tag = "RegExp"
		case "Arguments":
			tag = "Arguments"
		}
		if t.Fn != nil {
			tag = "Function"
		}
		if st := r.getV(t, r.SymToStringTag); !isUndefined(st) {
			if s, ok := st.(string); ok {
				tag = s
			}
		}
		return "[object " + tag + "]"
	}
	o := r.toObject(this)
	return r.objectToString(o)
}

func (r *Realm) defineProperties(o *Object, props *Object) {
	for _, k := range props.ownKeys(true) {
		p := props.getOwn(k)
		if p == nil || !p.Enumerable {
			continue
		}
		desc, ok := r.getProp(props, k, props).(*Object)
		if !ok {
			r.typeError("Property description must be an object")
		}
		r.defineFromDescriptor(o, k, desc)
	}
}

func (r *Realm) defineFromDescriptor(o *Object, key PropKey, desc *Object) {
	existing := o.getOwn(key)
	p := &Prop{}
	if existing != nil {
		cp := *existing
		p = &cp
		if !existing.Configurable {
			// allow only writable->false or same value changes; keep simple
		}
	}
	has := func(name string) bool { return r.hasProperty(desc, strKey(name)) }
	if has("get") || has("set") {
		p.Accessor = true
		p.Value = nil
		if has("get") {
			gv := r.getV(desc, "get")
			if g, ok := gv.(*Object); ok && g.Fn != nil {
				p.Getter = g
			} else if !isUndefined(gv) {
				r.typeError("Getter must be a function: " + toStringNoThrow(gv))
			}
		}
		if has("set") {
			sv := r.getV(desc, "set")
			if s, ok := sv.(*Object); ok && s.Fn != nil {
				p.Setter = s
			} else if !isUndefined(sv) {
				r.typeError("Setter must be a function: " + toStringNoThrow(sv))
			}
		}
	} else {
		if has("value") {
			p.Value = r.getV(desc, "value")
		} else if p.Value == nil && !p.Accessor {
			p.Value = undefined
		}
		if has("writable") {
			p.Writable = toBoolean(r.getV(desc, "writable"))
		}
	}
	if has("enumerable") {
		p.Enumerable = toBoolean(r.getV(desc, "enumerable"))
	}
	if has("configurable") {
		p.Configurable = toBoolean(r.getV(desc, "configurable"))
	}
	if o.Class == "Array" && !key.IsSymbol() {
		if idx, ok := arrayIndex(key.S); ok && !p.Accessor {
			for len(o.Array) <= idx {
				o.Array = append(o.Array, nil)
			}
			o.Array[idx] = p.Value
			return
		}
		if key.S == "length" && !p.Accessor {
			o.setLength(int(toNumber(p.Value)))
			return
		}
	}
	o.defineOwn(key, p)
}

func (r *Realm) fromDescriptor(p *Prop) Value {
	d := r.newPlainObject()
	if p.Accessor {
		if p.Getter != nil {
			d.setOwn(strKey("get"), p.Getter)
		} else {
			d.setOwn(strKey("get"), undefined)
		}
		if p.Setter != nil {
			d.setOwn(strKey("set"), p.Setter)
		} else {
			d.setOwn(strKey("set"), undefined)
		}
	} else {
		d.setOwn(strKey("value"), p.Value)
		d.setOwn(strKey("writable"), p.Writable)
	}
	d.setOwn(strKey("enumerable"), p.Enumerable)
	d.setOwn(strKey("configurable"), p.Configurable)
	return d
}

// ---------- Function ----------

func (r *Realm) setupFunction(g *Object) {
	fp := r.FunctionProto
	fp.defineOwn(strKey("length"), &Prop{Value: float64(0), Configurable: true})
	fp.defineOwn(strKey("name"), &Prop{Value: "", Configurable: true})
	fnCtor := r.newCtor("Function", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		var params []string
		body := ""
		if len(args) > 0 {
			for _, a := range args[:len(args)-1] {
				params = append(params, r.toString(a))
			}
			body = r.toString(args[len(args)-1])
		}
		src := "(function anonymous(" + strings.Join(params, ",") + "\n) {\n" + body + "\n})"
		prog, perr := Parse(src, false)
		if perr != nil {
			r.syntaxError(perr.Message)
		}
		v := r.eval(prog.Body[0].(*ExprStmt).Expr, r.GlobalEnv)
		return v
	}, fp)
	g.defineOwn(strKey("Function"), &Prop{Value: fnCtor, Writable: true, Configurable: true})
	r.setMethod(fp, "call", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		if !isCallable(this) {
			r.typeError("Function.prototype.call called on non-function")
		}
		var rest []Value
		if len(args) > 1 {
			rest = args[1:]
		}
		return r.call(this, arg(args, 0), rest)
	})
	r.setMethod(fp, "apply", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		if !isCallable(this) {
			r.typeError("Function.prototype.apply called on non-function")
		}
		var list []Value
		if a := arg(args, 1); !isNullish(a) {
			list = r.arrayLikeToSlice(a)
		}
		return r.call(this, arg(args, 0), list)
	})
	r.setMethod(fp, "bind", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		target, ok := this.(*Object)
		if !ok || target.Fn == nil {
			r.typeError("Bind must be called on a function")
		}
		var bargs []Value
		if len(args) > 1 {
			bargs = append(bargs, args[1:]...)
		}
		b := newObject(r.FunctionProto)
		b.Class = "Function"
		b.Fn = &Function{Name: "bound " + target.Fn.Name, Bound: &BoundData{Target: target, This: arg(args, 0), Args: bargs}, IsCtor: target.Fn.IsCtor, Realm: r}
		l := target.Fn.Length - len(bargs)
		if l < 0 {
			l = 0
		}
		b.defineOwn(strKey("length"), &Prop{Value: float64(l), Configurable: true})
		b.defineOwn(strKey("name"), &Prop{Value: "bound " + target.Fn.Name, Configurable: true})
		return b
	})
	r.setMethod(fp, "toString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		o, ok := this.(*Object)
		if !ok || o.Fn == nil {
			r.typeError("Function.prototype.toString requires that 'this' be a Function")
		}
		return r.functionSource(o)
	})
	r.funcHasInstance = r.setSymMethod(fp, r.SymHasInstance, "[Symbol.hasInstance]", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.instanceOf(arg(args, 0), this)
	})
}

func (r *Realm) functionSource(o *Object) string {
	fn := o.Fn
	if fn.Bound != nil {
		return "function () { [native code] }"
	}
	if fn.Native != nil {
		return "function " + fn.Name + "() { [native code] }"
	}
	if fn.Source != "" {
		return fn.Source
	}
	if fn.IsClass {
		return "class " + fn.Name + " { }"
	}
	return "function " + fn.Name + "() { [native code] }"
}

func (r *Realm) arrayLikeToSlice(v Value) []Value {
	o, ok := v.(*Object)
	if !ok {
		r.typeError("CreateListFromArrayLike called on non-object")
	}
	if o.Class == "Array" {
		out := make([]Value, len(o.Array))
		for i, x := range o.Array {
			if x == nil {
				x = undefined
			}
			out[i] = x
		}
		return out
	}
	n := r.toLength(r.getV(o, "length"))
	out := make([]Value, n)
	for i := 0; i < n; i++ {
		out[i] = r.getV(o, itoa(i))
	}
	return out
}

// ---------- Boolean ----------

func (r *Realm) setupBoolean(g *Object) {
	bp := r.BooleanProto
	ctor := r.newCtor("Boolean", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		b := toBoolean(arg(args, 0))
		if nt != nil {
			o := r.createFromCtor(nt, r.BooleanProto)
			o.Class = "Boolean"
			o.Prim = b
			return o
		}
		return b
	}, bp)
	g.defineOwn(strKey("Boolean"), &Prop{Value: ctor, Writable: true, Configurable: true})
	thisBool := func(r *Realm, this Value) bool {
		switch t := this.(type) {
		case bool:
			return t
		case *Object:
			if b, ok := t.Prim.(bool); ok && t.Class == "Boolean" {
				return b
			}
		}
		r.typeError("Boolean.prototype.valueOf requires that 'this' be a Boolean")
		return false
	}
	r.setMethod(bp, "toString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		if thisBool(r, this) {
			return "true"
		}
		return "false"
	})
	r.setMethod(bp, "valueOf", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return thisBool(r, this)
	})
}

// ---------- Symbol ----------

func (r *Realm) setupSymbol(g *Object) {
	sp := r.SymbolProto
	registry := map[string]*Symbol{}
	ctor := r.newCtor("Symbol", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		if nt != nil {
			r.typeError("Symbol is not a constructor")
		}
		d := arg(args, 0)
		if isUndefined(d) {
			return &Symbol{}
		}
		return &Symbol{Description: r.toString(d), HasDesc: true}
	}, sp)
	ctor.Fn.IsCtor = false
	g.defineOwn(strKey("Symbol"), &Prop{Value: ctor, Writable: true, Configurable: true})
	r.setConst(ctor, "iterator", r.SymIterator)
	r.setConst(ctor, "hasInstance", r.SymHasInstance)
	r.setConst(ctor, "toPrimitive", r.SymToPrimitive)
	r.setConst(ctor, "toStringTag", r.SymToStringTag)
	r.setConst(ctor, "asyncIterator", r.SymAsyncIterator)
	for _, n := range []string{"species", "isConcatSpreadable", "match", "matchAll", "replace", "search", "split", "unscopables"} {
		r.setConst(ctor, n, &Symbol{Description: "Symbol." + n, HasDesc: true})
	}
	r.setMethod(ctor, "for", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		k := r.toString(arg(args, 0))
		if s, ok := registry[k]; ok {
			return s
		}
		s := &Symbol{Description: k, HasDesc: true}
		registry[k] = s
		return s
	})
	r.setMethod(ctor, "keyFor", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		s, ok := arg(args, 0).(*Symbol)
		if !ok {
			r.typeError("not a symbol")
		}
		for k, v := range registry {
			if v == s {
				return k
			}
		}
		return undefined
	})
	thisSym := func(r *Realm, this Value) *Symbol {
		switch t := this.(type) {
		case *Symbol:
			return t
		case *Object:
			if s, ok := t.Prim.(*Symbol); ok {
				return s
			}
		}
		r.typeError("Symbol.prototype.valueOf requires that 'this' be a Symbol")
		return nil
	}
	r.setMethod(sp, "toString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return thisSym(r, this).String()
	})
	r.setMethod(sp, "valueOf", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return thisSym(r, this)
	})
	r.setGetter(sp, "description", func(r *Realm, this Value) Value {
		s := thisSym(r, this)
		if !s.HasDesc {
			return undefined
		}
		return s.Description
	})
	sp.defineOwn(symKey(r.SymToStringTag), &Prop{Value: "Symbol", Configurable: true})
	r.setSymMethod(sp, r.SymToPrimitive, "[Symbol.toPrimitive]", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return thisSym(r, this)
	})
}

// ---------- Errors ----------

func (r *Realm) setupErrors(g *Object) {
	ep := r.ErrorProto
	mkCtor := func(name string, proto *Object, parent *Object) *Object {
		ctor := r.newCtor(name, 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
			var e *Object
			if nt != nil {
				e = r.createFromCtor(nt, proto)
			} else {
				e = newObject(proto)
			}
			e.Class = "Error"
			e.IsError = true
			msg := arg(args, 0)
			if !isUndefined(msg) {
				e.defineOwn(strKey("message"), &Prop{Value: r.toString(msg), Writable: true, Configurable: true})
			}
			if opts, ok := arg(args, 1).(*Object); ok && r.hasProperty(opts, strKey("cause")) {
				e.defineOwn(strKey("cause"), &Prop{Value: r.getV(opts, "cause"), Writable: true, Configurable: true})
			}
			stack := name
			if !isUndefined(msg) {
				stack += ": " + r.toString(msg)
			}
			e.defineOwn(strKey("stack"), &Prop{Value: stack + "\n\tat <anonymous>", Writable: true, Configurable: true})
			return e
		}, proto)
		if parent != nil {
			ctor.Proto = parent
		}
		proto.defineOwn(strKey("name"), &Prop{Value: name, Writable: true, Configurable: true})
		proto.defineOwn(strKey("message"), &Prop{Value: "", Writable: true, Configurable: true})
		g.defineOwn(strKey(name), &Prop{Value: ctor, Writable: true, Configurable: true})
		r.ErrorCtors[name] = ctor
		return ctor
	}
	errCtor := mkCtor("Error", ep, nil)
	r.setMethod(ep, "toString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		o, ok := this.(*Object)
		if !ok {
			r.typeError("Error.prototype.toString called on non-object")
		}
		name := "Error"
		if n := r.getV(o, "name"); !isUndefined(n) {
			name = r.toString(n)
		}
		msg := ""
		if m := r.getV(o, "message"); !isUndefined(m) {
			msg = r.toString(m)
		}
		if name == "" {
			return msg
		}
		if msg == "" {
			return name
		}
		return name + ": " + msg
	})
	r.setMethod(errCtor, "captureStackTrace", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return undefined
	})
	for _, name := range []string{"TypeError", "ReferenceError", "SyntaxError", "RangeError", "EvalError", "URIError"} {
		proto := newObject(ep)
		mkCtor(name, proto, errCtor)
	}
	// AggregateError
	aproto := newObject(ep)
	actor := r.newCtor("AggregateError", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		e := r.createFromCtor(nt, aproto)
		e.Class = "Error"
		e.IsError = true
		if msg := arg(args, 1); !isUndefined(msg) {
			e.defineOwn(strKey("message"), &Prop{Value: r.toString(msg), Writable: true, Configurable: true})
		}
		e.defineOwn(strKey("errors"), &Prop{Value: r.newArray(r.iterToSlice(arg(args, 0))), Writable: true, Configurable: true})
		return e
	}, aproto)
	actor.Proto = errCtor
	aproto.defineOwn(strKey("name"), &Prop{Value: "AggregateError", Writable: true, Configurable: true})
	aproto.defineOwn(strKey("message"), &Prop{Value: "", Writable: true, Configurable: true})
	g.defineOwn(strKey("AggregateError"), &Prop{Value: actor, Writable: true, Configurable: true})
	r.ErrorCtors["AggregateError"] = actor
	// GoError
	gproto := newObject(ep)
	gctor := r.newCtor("GoError", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		e := r.createFromCtor(nt, gproto)
		e.Class = "Error"
		e.IsError = true
		if msg := arg(args, 0); !isUndefined(msg) {
			e.defineOwn(strKey("message"), &Prop{Value: r.toString(msg), Writable: true, Configurable: true})
		}
		return e
	}, gproto)
	gctor.Proto = errCtor
	gproto.defineOwn(strKey("name"), &Prop{Value: "GoError", Writable: true, Configurable: true})
	gproto.defineOwn(strKey("message"), &Prop{Value: "", Writable: true, Configurable: true})
	g.defineOwn(strKey("GoError"), &Prop{Value: gctor, Writable: true, Configurable: true})
	r.ErrorCtors["GoError"] = gctor
}

// ---------- globals ----------

func (r *Realm) setupGlobals(g *Object) {
	r.evalFn = r.setMethod(g, "eval", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		// indirect eval: global scope
		src, ok := arg(args, 0).(string)
		if !ok {
			return arg(args, 0)
		}
		prog, perr := Parse(src, false)
		if perr != nil {
			r.syntaxError(perr.Message)
		}
		env := newEnv(r.GlobalEnv)
		r.hoist(prog.Body, env, r.GlobalEnv, false)
		var last Value = undefined
		for _, st := range prog.Body {
			c := r.exec(st, env)
			if c.kind != ctrlNone {
				break
			}
			if _, ok := st.(*ExprStmt); ok {
				last = c.value
			}
		}
		return last
	})
	r.setMethod(g, "isNaN", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return math.IsNaN(r.toNumber(arg(args, 0)))
	})
	r.setMethod(g, "isFinite", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		f := r.toNumber(arg(args, 0))
		return !math.IsNaN(f) && !math.IsInf(f, 0)
	})
	parseIntFn := r.setMethod(g, "parseInt", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		s := trimStartJS(r.toString(arg(args, 0)))
		radix := int(toInt32(r.toNumber(arg(args, 1))))
		sign := 1.0
		if strings.HasPrefix(s, "-") {
			sign = -1
			s = s[1:]
		} else if strings.HasPrefix(s, "+") {
			s = s[1:]
		}
		stripPrefix := true
		if radix != 0 {
			if radix < 2 || radix > 36 {
				return math.NaN()
			}
			if radix != 16 {
				stripPrefix = false
			}
		} else {
			radix = 10
		}
		if stripPrefix && len(s) >= 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X') {
			s = s[2:]
			radix = 16
		}
		end := 0
		for end < len(s) {
			d, ok := hexVal(rune(s[end]))
			if s[end] >= 'g' && s[end] <= 'z' {
				d, ok = int(s[end]-'a')+10, true
			} else if s[end] >= 'G' && s[end] <= 'Z' {
				d, ok = int(s[end]-'A')+10, true
			}
			if !ok || d >= radix {
				break
			}
			end++
		}
		if end == 0 {
			return math.NaN()
		}
		digits := s[:end]
		if radix == 10 {
			f, _ := strconv.ParseFloat(digits, 64)
			return sign * f
		}
		b := new(big.Int)
		b.SetString(digits, radix)
		f, _ := new(big.Float).SetInt(b).Float64()
		return sign * f
	})
	parseFloatFn := r.setMethod(g, "parseFloat", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		s := trimStartJS(r.toString(arg(args, 0)))
		return parseFloatPrefix(s)
	})
	r.parseIntFn = parseIntFn
	r.parseFloatFn = parseFloatFn
	uriErr := func() { r.throwError("URIError", "Malformed URI") }
	encode := func(s string, unescaped string) string {
		var b strings.Builder
		cps := decodeWTF8(s)
		for i := 0; i < len(cps); i++ {
			c := cps[i]
			if c < 0x80 && (isURIAlnum(byte(c)) || strings.ContainsRune(unescaped, c)) {
				b.WriteByte(byte(c))
				continue
			}
			if c >= 0xD800 && c <= 0xDFFF {
				uriErr()
			}
			buf := []byte(string(c))
			for _, x := range buf {
				b.WriteString("%" + strings.ToUpper(strconv.FormatInt(int64(x), 16)))
				if x < 16 {
					// ensure two digits
					s := b.String()
					b.Reset()
					b.WriteString(s[:len(s)-1] + "0" + s[len(s)-1:])
				}
			}
		}
		return b.String()
	}
	decode := func(s string, reserved string) string {
		var out []byte
		for i := 0; i < len(s); i++ {
			if s[i] != '%' {
				out = append(out, s[i])
				continue
			}
			if i+2 >= len(s) {
				uriErr()
			}
			v, err := strconv.ParseUint(s[i+1:i+3], 16, 8)
			if err != nil {
				uriErr()
			}
			if v < 0x80 {
				if strings.IndexByte(reserved, byte(v)) >= 0 {
					out = append(out, s[i:i+3]...)
				} else {
					out = append(out, byte(v))
				}
				i += 2
				continue
			}
			// multi-byte sequence
			n := 0
			switch {
			case v&0xE0 == 0xC0:
				n = 2
			case v&0xF0 == 0xE0:
				n = 3
			case v&0xF8 == 0xF0:
				n = 4
			default:
				uriErr()
			}
			seq := []byte{byte(v)}
			j := i + 3
			for k := 1; k < n; k++ {
				if j+2 >= len(s)+0 && j+2 > len(s)-1+1 {
					uriErr()
				}
				if j >= len(s) || s[j] != '%' || j+2 >= len(s)+1 {
					uriErr()
				}
				if j+3 > len(s) {
					uriErr()
				}
				b2, err := strconv.ParseUint(s[j+1:j+3], 16, 8)
				if err != nil || b2&0xC0 != 0x80 {
					uriErr()
				}
				seq = append(seq, byte(b2))
				j += 3
			}
			if !isValidUTF8(seq) {
				uriErr()
			}
			out = append(out, seq...)
			i = j - 1
		}
		return string(out)
	}
	r.setMethod(g, "decodeURI", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return decode(r.toString(arg(args, 0)), ";/?:@&=+$,#")
	})
	r.setMethod(g, "decodeURIComponent", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return decode(r.toString(arg(args, 0)), "")
	})
	r.setMethod(g, "encodeURI", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return encode(r.toString(arg(args, 0)), ";/?:@&=+$,-_.!~*'()#")
	})
	r.setMethod(g, "encodeURIComponent", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return encode(r.toString(arg(args, 0)), "-_.!~*'()")
	})
	r.setMethod(g, "escape", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		s := r.toString(arg(args, 0))
		var b strings.Builder
		for _, u := range utf16Units(s) {
			if u < 256 {
				c := byte(u)
				if isURIAlnum(c) || strings.IndexByte("@*_+-./", c) >= 0 {
					b.WriteByte(c)
				} else {
					b.WriteString("%" + strings.ToUpper(leftPad(strconv.FormatInt(int64(u), 16), 2)))
				}
			} else {
				b.WriteString("%u" + strings.ToUpper(leftPad(strconv.FormatInt(int64(u), 16), 4)))
			}
		}
		return b.String()
	})
	r.setMethod(g, "unescape", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		s := r.toString(arg(args, 0))
		var units []uint16
		u := utf16Units(s)
		for i := 0; i < len(u); i++ {
			if u[i] == '%' {
				if i+5 < len(u) && u[i+1] == 'u' {
					if v, err := strconv.ParseUint(unitsToString(u[i+2:i+6]), 16, 16); err == nil {
						units = append(units, uint16(v))
						i += 5
						continue
					}
				}
				if i+2 < len(u) {
					if v, err := strconv.ParseUint(unitsToString(u[i+1:i+3]), 16, 8); err == nil {
						units = append(units, uint16(v))
						i += 2
						continue
					}
				}
			}
			units = append(units, u[i])
		}
		return unitsToString(units)
	})
	_ = url.QueryEscape
}

func leftPad(s string, n int) string {
	for len(s) < n {
		s = "0" + s
	}
	return s
}

func isURIAlnum(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9'
}

func isValidUTF8(b []byte) bool {
	s := string(b)
	for _, r := range s {
		if r == 0xFFFD {
			return false
