func (r *Realm) setupPromise(g *Object) {
	pp := r.PromiseProto
	ctor := r.newCtor("Promise", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		if nt == nil {
			r.typeError("Promise constructor cannot be invoked without 'new'")
		}
		p := r.createFromCtor(nt, pp)
		p.Class = "Promise"
		exec := arg(args, 0)
		if !isCallable(exec) {
			r.typeError("Promise resolver " + toStringNoThrow(exec) + " is not a function")
		}
		state := r.newPlainObject()
		p.Internal = state
		resolve := r.newNativeFunction("resolve", 1, func(r *Realm, this Value, a []Value, nt *Object) Value {
			state.setOwn(strKey("state"), "fulfilled")
			state.setOwn(strKey("value"), arg(a, 0))
			return undefined
		})
		reject := r.newNativeFunction("reject", 1, func(r *Realm, this Value, a []Value, nt *Object) Value {
			state.setOwn(strKey("state"), "rejected")
			state.setOwn(strKey("value"), arg(a, 0))
			return undefined
		})
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					if th, ok := rec.(*Throw); ok {
						state.setOwn(strKey("state"), "rejected")
						state.setOwn(strKey("value"), th.Value)
						return
					}
					panic(rec)
				}
			}()
			r.call(exec, undefined, []Value{resolve, reject})
		}()
		return p
	}, pp)
	g.defineOwn(strKey("Promise"), &Prop{Value: ctor, Writable: true, Configurable: true})
	r.setMethod(pp, "then", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return this
	})
	r.setMethod(pp, "catch", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return this
	})
	r.setMethod(pp, "finally", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return this
	})
	r.setMethod(ctor, "resolve", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		p := newObject(pp)
		p.Class = "Promise"
		return p
	})
	r.setMethod(ctor, "reject", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		p := newObject(pp)
		p.Class = "Promise"
		return p
	})
