					// backreference: unsupported
					b.WriteRune('\\')
					b.WriteRune(e)
					continue
				}
				if e >= 'a' && e <= 'z' || e >= 'A' && e <= 'Z' || e >= '0' && e <= '9' || e == '_' {
					// identity escape of alphanumerics: literal char
					b.WriteRune(e)
					continue
				}
				if e == '-' && !inClass {
					b.WriteRune('-')
					continue
				}
				if e == '/' {
					b.WriteRune('/')
					continue
				}
				b.WriteRune('\\')
				b.WriteRune(e)
			}
		case c == '[' && !inClass:
			inClass = true
			classStart = b.Len()
			// [^] and []
			if i+1 < len(rs) && rs[i+1] == ']' {
				b.WriteString("[^\\x00-\\x{10FFFF}]")
				i++
				inClass = false
				continue
			}
			if i+2 < len(rs) && rs[i+1] == '^' && rs[i+2] == ']' {
				b.WriteString("[\\x00-\\x{10FFFF}]")
				i += 2
				inClass = false
				continue
			}
			b.WriteRune('[')
		case c == ']' && inClass:
			inClass = false
			b.WriteRune(']')
			_ = classStart
		case c == '(' && !inClass:
			if i+2 < len(rs) && rs[i+1] == '?' && rs[i+2] == '<' && i+3 < len(rs) && rs[i+3] != '=' && rs[i+3] != '!' {
				b.WriteString("(?P<")
				i += 2
				continue
			}
			b.WriteRune('(')
		case c == '.' && !inClass:
			if strings.Contains(flags, "s") {
				b.WriteString("(?s:.)")
			} else {
				b.WriteString("[^\\n\\r\\x{2028}\\x{2029}]")
			}
		case c == '$' && !inClass && !strings.Contains(flags, "m"):
			b.WriteString("\\z")
		case inClass && c == '[':
			b.WriteString("\\[")
		default:
			b.WriteRune(c)
		}
	}
	return b.String(), prefix
}

func validateRegexPattern(pattern, flags string) string {
	_, err := compileJSRegex(pattern, flags)
	if err != nil {
		return err.Error()
	}
	return ""
}

type regexCompileError struct{ msg string }

func (e *regexCompileError) Error() string { return e.msg }

func compileJSRegex(pattern, flags string) (*regexpWrapper, error) {
	translated, _ := translateRegex(pattern, flags)
	re, err := regexp.Compile(translated)
	if err != nil {
		msg := err.Error()
		switch {
		case strings.Contains(msg, "missing closing )"):
			return nil, &regexCompileError{"Unterminated group"}
		case strings.Contains(msg, "missing closing ]"):
			return nil, &regexCompileError{"Unterminated character class"}
		case strings.Contains(msg, "unexpected )"):
			return nil, &regexCompileError{"Unmatched ')'"}
		case strings.Contains(msg, "missing argument to repetition operator"):
			return nil, &regexCompileError{"Nothing to repeat"}
		case strings.Contains(msg, "invalid nested repetition operator"):
			return nil, &regexCompileError{"Nothing to repeat"}
		case strings.Contains(msg, "invalid escape sequence"):
			return nil, &regexCompileError{"Invalid escape"}
		case strings.Contains(msg, "invalid character class range"):
			return nil, &regexCompileError{"Range out of order in character class"}
		case strings.Contains(msg, "invalid or unsupported Perl syntax"):
			return nil, &regexCompileError{"Invalid regular expression: " + pattern}
		}
		return nil, &regexCompileError{"Invalid regular expression: " + pattern}
	}
	w := &regexpWrapper{re: re, names: re.SubexpNames(), numGroups: re.NumSubexp()}
	return w, nil
}

func (r *Realm) newRegExp(pattern, flags string) *Object {
	if msg := validateRegexFlags(flags); msg != "" {
		r.syntaxError(msg)
	}
	w, err := compileJSRegex(pattern, flags)
	if err != nil {
		r.syntaxError(err.Error())
	}
	o := newObject(r.RegExpProto)
	o.Class = "RegExp"
	o.Regex = &RegExpData{
		Source: pattern, Flags: flags,
		Global: strings.Contains(flags, "g"), IgnoreCase: strings.Contains(flags, "i"),
		Multiline: strings.Contains(flags, "m"), DotAll: strings.Contains(flags, "s"),
		Unicode: strings.Contains(flags, "u"), Sticky: strings.Contains(flags, "y"),
		re: w,
	}
	o.defineOwn(strKey("lastIndex"), &Prop{Value: float64(0), Writable: true})
	return o
}

// matchResult holds a single match with UTF-16 indices.
type matchResult struct {
	start, end int      // utf16 indices
	groups     []string // group 0..n ("" for unmatched)
	matched    []bool
	names      []string
}

// execAt runs the regex on s starting at utf16 index from. Sticky anchors the match at from.
func (w *regexpWrapper) execAt(s string, from int, sticky bool) *matchResult {
	if from < 0 || from > strLen(s) {
		return nil
	}
	off := unitIndexToByteOffset(s, from)
	loc := w.re.FindStringSubmatchIndex(s[off:])
	if loc == nil {
		return nil
	}
	if sticky && loc[0] != 0 {
		return nil
	}
	m := &matchResult{names: w.names}
	m.start = from + byteOffsetToUnitIndex(s[off:], loc[0])
	m.end = from + byteOffsetToUnitIndex(s[off:], loc[1])
	n := len(loc) / 2
	m.groups = make([]string, n)
	m.matched = make([]bool, n)
	for i := 0; i < n; i++ {
		if loc[2*i] >= 0 {
			m.groups[i] = s[off+loc[2*i] : off+loc[2*i+1]]
			m.matched[i] = true
		}
	}
	return m
}

// execAtWithBoundary handles lookahead-free matching; also used by replace.
func (r *Realm) regexExec(rx *Object, s string) Value {
	rd := rx.Regex
	lastIndex := 0
	if rd.Global || rd.Sticky {
		lastIndex = int(r.toInteger(r.getV(rx, "lastIndex")))
		if lastIndex > strLen(s) {
			r.setProp(rx, strKey("lastIndex"), float64(0), rx)
			return null
		}
	}
	m := rd.re.execAt(s, lastIndex, rd.Sticky)
	if m == nil {
		if rd.Global || rd.Sticky {
			r.setProp(rx, strKey("lastIndex"), float64(0), rx)
		}
		return null
	}
	if rd.Global || rd.Sticky {
		end := m.end
		if end == m.start && end == lastIndex {
			// avoid infinite loops handled by callers; spec sets lastIndex = end
		}
		r.setProp(rx, strKey("lastIndex"), float64(end), rx)
	}
	return r.matchToArray(m, s)
}

func (r *Realm) matchToArray(m *matchResult, s string) *Object {
	vals := make([]Value, len(m.groups))
	for i := range m.groups {
		if m.matched[i] {
			vals[i] = m.groups[i]
		} else {
			vals[i] = undefined
		}
	}
	arr := r.newArray(vals)
	arr.setOwn(strKey("index"), float64(m.start))
	arr.setOwn(strKey("input"), s)
	hasNames := false
	for _, n := range m.names {
		if n != "" {
			hasNames = true
		}
	}
	if hasNames {
		groups := newObject(nil)
		for i, n := range m.names {
			if n != "" {
				if m.matched[i] {
					groups.setOwn(strKey(n), m.groups[i])
				} else {
					groups.setOwn(strKey(n), undefined)
				}
			}
		}
		arr.setOwn(strKey("groups"), groups)
	} else {
		arr.setOwn(strKey("groups"), undefined)
	}
	return arr
}

// allMatches returns all matches for a global regex.
func (w *regexpWrapper) allMatches(s string) []*matchResult {
	var out []*matchResult
	pos := 0
	n := strLen(s)
	for pos <= n {
		m := w.execAt(s, pos, false)
		if m == nil {
			break
		}
		out = append(out, m)
		if m.end == m.start {
			pos = m.end + 1
		} else {
			pos = m.end
		}
	}
	return out
}

// expandReplacement expands $-patterns in a replacement string.
func expandReplacement(repl string, m *matchResult, s string) string {
	var b strings.Builder
	rs := []rune(repl)
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		if c != '$' || i+1 >= len(rs) {
			b.WriteRune(c)
			continue
		}
		n := rs[i+1]
		switch {
		case n == '$':
			b.WriteRune('$')
			i++
		case n == '&':
			b.WriteString(m.groups[0])
			i++
		case n == '`':
			b.WriteString(strSlice(s, 0, m.start))
			i++
		case n == '\'':
			b.WriteString(strSlice(s, m.end, strLen(s)))
			i++
		case n >= '0' && n <= '9':
			// one or two digits
			d1 := int(n - '0')
			if i+2 < len(rs) && rs[i+2] >= '0' && rs[i+2] <= '9' {
				d2 := d1*10 + int(rs[i+2]-'0')
				if d2 >= 1 && d2 < len(m.groups) {
					b.WriteString(m.groups[d2])
					i += 2
					continue
				}
			}
			if d1 >= 1 && d1 < len(m.groups) {
				b.WriteString(m.groups[d1])
				i++
				continue
			}
			b.WriteRune('$')
		case n == '<':
			j := i + 2
			for j < len(rs) && rs[j] != '>' {
				j++
			}
			if j < len(rs) && len(m.names) > 0 {
				name := string(rs[i+2 : j])
				for gi, gn := range m.names {
					if gn == name {
						b.WriteString(m.groups[gi])
						break
					}
				}
				i = j
				continue
			}
			b.WriteRune('$')
		default:
			b.WriteRune('$')
		}
	}
	return b.String()
}

func (r *Realm) setupRegExp(g *Object) {
	rp := r.RegExpProto
	ctor := r.newCtor("RegExp", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		pat := arg(args, 0)
		fl := arg(args, 1)
		pattern := ""
		flags := ""
		if po, ok := pat.(*Object); ok && po.Class == "RegExp" {
			pattern = po.Regex.Source
			if isUndefined(fl) {
				flags = po.Regex.Flags
			} else {
				flags = r.toString(fl)
			}
			if nt == nil && isUndefined(fl) {
				return po
			}
		} else {
			if !isUndefined(pat) {
				pattern = r.toString(pat)
			}
			if !isUndefined(fl) {
				flags = r.toString(fl)
			}
		}
		if pattern == "" {
			pattern = "(?:)"
		}
		return r.newRegExp(pattern, flags)
	}, rp)
	g.defineOwn(strKey("RegExp"), &Prop{Value: ctor, Writable: true, Configurable: true})
	thisRx := func(r *Realm, this Value) *Object {
		o, ok := this.(*Object)
		if !ok || o.Regex == nil {
			r.typeError("Method RegExp.prototype called on incompatible receiver " + toStringNoThrow(this))
		}
		return o
	}
	r.setMethod(rp, "exec", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		rx := thisRx(r, this)
		return r.regexExec(rx, r.toString(arg(args, 0)))
	})
	r.setMethod(rp, "test", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		rx := thisRx(r, this)
		return !isNull(r.regexExec(rx, r.toString(arg(args, 0))))
	})
	r.setMethod(rp, "toString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		rx := thisRx(r, this)
		return "/" + rx.Regex.Source + "/" + rx.Regex.Flags
	})
	r.setMethod(rp, "compile", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return this
	})
	r.setGetter(rp, "source", func(r *Realm, this Value) Value {
		if this == rp {
			return "(?:)"
		}
		return thisRx(r, this).Regex.Source
	})
	r.setGetter(rp, "flags", func(r *Realm, this Value) Value {
		if this == rp {
			return ""
		}
		rd := thisRx(r, this).Regex
		var b strings.Builder
		for _, f := range "dgimsuy" {
			if strings.ContainsRune(rd.Flags, f) {
				b.WriteRune(f)
			}
		}
		return b.String()
	})
	flagGetter := func(name string, get func(rd *RegExpData) bool) {
		r.setGetter(rp, name, func(r *Realm, this Value) Value {
			if this == rp {
				return undefined
			}
			return get(thisRx(r, this).Regex)
		})
	}
	flagGetter("global", func(rd *RegExpData) bool { return rd.Global })
	flagGetter("ignoreCase", func(rd *RegExpData) bool { return rd.IgnoreCase })
	flagGetter("multiline", func(rd *RegExpData) bool { return rd.Multiline })
	flagGetter("dotAll", func(rd *RegExpData) bool { return rd.DotAll })
	flagGetter("unicode", func(rd *RegExpData) bool { return rd.Unicode })
	flagGetter("sticky", func(rd *RegExpData) bool { return rd.Sticky })
	flagGetter("hasIndices", func(rd *RegExpData) bool { return strings.Contains(rd.Flags, "d") })
	r.setSymMethod(rp, r.symFor("Symbol.match"), "[Symbol.match]", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.stringMatch(r.toString(arg(args, 0)), this)
	})
	r.setSymMethod(rp, r.symFor("Symbol.replace"), "[Symbol.replace]", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.stringReplace(r.toString(arg(args, 0)), this, arg(args, 1), false)
	})
	r.setSymMethod(rp, r.symFor("Symbol.search"), "[Symbol.search]", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.stringSearch(r.toString(arg(args, 0)), this)
	})
	r.setSymMethod(rp, r.symFor("Symbol.split"), "[Symbol.split]", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.stringSplit(r.toString(arg(args, 0)), this, arg(args, 1))
	})
	r.setSymMethod(rp, r.symFor("Symbol.matchAll"), "[Symbol.matchAll]", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.stringMatchAll(r.toString(arg(args, 0)), this)
	})
}

// symFor finds a well-known symbol on the Symbol constructor by description.
func (r *Realm) symFor(desc string) *Symbol {
	sc := r.getV(r.Global, "Symbol").(*Object)
	name := strings.TrimPrefix(desc, "Symbol.")
	if s, ok := r.getV(sc, name).(*Symbol); ok {
		return s
	}
	return &Symbol{Description: desc, HasDesc: true}
}

func (r *Realm) stringMatch(s string, rxv Value) Value {
	rx, ok := rxv.(*Object)
	if !ok || rx.Regex == nil {
		rx = r.newRegExp(regexpQuoteJS(r.toString(rxv)), "")
	}
	if !rx.Regex.Global {
		return r.regexExec(rx, s)
	}
	ms := rx.Regex.re.allMatches(s)
	r.setProp(rx, strKey("lastIndex"), float64(0), rx)
	if len(ms) == 0 {
		return null
	}
	vals := make([]Value, len(ms))
	for i, m := range ms {
		vals[i] = m.groups[0]
	}
	return r.newArray(vals)
}

func (r *Realm) stringMatchAll(s string, rxv Value) Value {
	rx, ok := rxv.(*Object)
	if !ok || rx.Regex == nil {
		rx = r.newRegExp(regexpQuoteJS(r.toString(rxv)), "g")
	}
	if !rx.Regex.Global {
		r.typeError("String.prototype.matchAll called with a non-global RegExp argument")
	}
	ms := rx.Regex.re.allMatches(s)
	i := 0
	return r.makeIterator(r.ArrayIteratorProto, func() (Value, bool) {
		if i >= len(ms) {
			return undefined, true
		}
		m := ms[i]
		i++
		return r.matchToArray(m, s), false
	})
}

func (r *Realm) stringSearch(s string, rxv Value) Value {
	rx, ok := rxv.(*Object)
	if !ok || rx.Regex == nil {
		rx = r.newRegExp(r.toString(rxv), "")
	}
	m := rx.Regex.re.execAt(s, 0, false)
	if m == nil {
		return float64(-1)
	}
	return float64(m.start)
}

func (r *Realm) stringReplace(s string, pattern Value, replacement Value, all bool) Value {
	var matches []*matchResult
	if rx, ok := pattern.(*Object); ok && rx.Regex != nil {
		if all && !rx.Regex.Global {
			r.typeError("replaceAll must be called with a global RegExp")
		}
		if rx.Regex.Global {
			matches = rx.Regex.re.allMatches(s)
			r.setProp(rx, strKey("lastIndex"), float64(0), rx)
		} else {
			lastIndex := 0
			if rx.Regex.Sticky {
				lastIndex = int(r.toInteger(r.getV(rx, "lastIndex")))
			}
			m := rx.Regex.re.execAt(s, lastIndex, rx.Regex.Sticky)
			if m != nil {
				matches = []*matchResult{m}
				if rx.Regex.Sticky {
					r.setProp(rx, strKey("lastIndex"), float64(m.end), rx)
				}
			} else if rx.Regex.Sticky {
				r.setProp(rx, strKey("lastIndex"), float64(0), rx)
			}
		}
	} else {
		sub := r.toString(pattern)
		pos := 0
		for {
			idx := strIndexOf(s, sub, pos)
			if idx < 0 {
				break
			}
			matches = append(matches, &matchResult{start: idx, end: idx + strLen(sub), groups: []string{sub}, matched: []bool{true}})
			if !all {
				break
			}
			if strLen(sub) == 0 {
				pos = idx + 1
				if pos > strLen(s) {
					break
				}
			} else {
				pos = idx + strLen(sub)
			}
		}
	}
	if len(matches) == 0 {
		return s
	}
	var b strings.Builder
	last := 0
	fn, isFn := replacement.(*Object)
	if isFn && fn.Fn == nil {
		isFn = false
	}
	replStr := ""
	if !isFn {
		replStr = r.toString(replacement)
	}
	for _, m := range matches {
		b.WriteString(strSlice(s, last, m.start))
		if isFn {
			args := []Value{}
			for i, g := range m.groups {
				if m.matched[i] {
					args = append(args, g)
				} else {
					args = append(args, undefined)
				}
			}
			args = append(args, float64(m.start), s)
			hasNames := false
			for _, n := range m.names {
				if n != "" {
					hasNames = true
				}
			}
			if hasNames {
				groups := newObject(nil)
				for i, n := range m.names {
					if n != "" {
						if m.matched[i] {
							groups.setOwn(strKey(n), m.groups[i])
						} else {
							groups.setOwn(strKey(n), undefined)
						}
					}
				}
				args = append(args, groups)
			}
			b.WriteString(r.toString(r.call(fn, undefined, args)))
		} else {
			b.WriteString(expandReplacement(replStr, m, s))
		}
		last = m.end
	}
	b.WriteString(strSlice(s, last, strLen(s)))
	return b.String()
}

func (r *Realm) stringSplit(s string, sepv Value, limitv Value) Value {
	limit := -1
	if !isUndefined(limitv) {
		limit = int(toUint32(r.toNumber(limitv)))
	}
	if limit == 0 {
		return r.newArray(nil)
	}
	var out []Value
	push := func(v Value) bool {
		if limit >= 0 && len(out) >= limit {
			return false
		}
		out = append(out, v)
		return true
	}
	if isUndefined(sepv) {
		push(s)
		return r.newArray(out)
	}
	if rx, ok := sepv.(*Object); ok && rx.Regex != nil {
		n := strLen(s)
		if n == 0 {
			if rx.Regex.re.execAt(s, 0, true) != nil {
				return r.newArray(nil)
			}
			return r.newArray([]Value{s})
		}
		p := 0
		q := 0
		for q < n {
			m := rx.Regex.re.execAt(s, q, true)
			if m == nil || m.end == p && m.end == m.start {
				q++
				continue
			}
			if m.end > n {
				break
			}
			e := m.end
			if e == p {
				q++
				continue
			}
			if !push(strSlice(s, p, m.start)) {
				return r.newArray(out)
			}
			for i := 1; i < len(m.groups); i++ {
				var gv Value = undefined
				if m.matched[i] {
					gv = m.groups[i]
				}
				if !push(gv) {
					return r.newArray(out)
				}
			}
			p = e
			q = p
			if m.end == m.start {
				q++
			}
		}
		push(strSlice(s, p, n))
		return r.newArray(out)
	}
	sep := r.toString(sepv)
	if sep == "" {
		for _, u := range utf16Units(s) {
			if !push(unitsToString([]uint16{u})) {
				break
			}
		}
		return r.newArray(out)
	}
	pos := 0
	for {
		idx := strIndexOf(s, sep, pos)
		if idx < 0 {
			push(strSlice(s, pos, strLen(s)))
			break
		}
		if !push(strSlice(s, pos, idx)) {
			break
		}
		pos = idx + strLen(sep)
	}
	return r.newArray(out)
}

func regexpQuoteJS(s string) string {
	var b strings.Builder
	for _, c := range s {
		if strings.ContainsRune(`\^$.|?*+()[]{}/`, c) {
			b.WriteRune('\\')
		}
		b.WriteRune(c)
	}
	return b.String()
}

