// translateRegex converts a JS regular expression into Go RE2 syntax.
func translateRegex(pattern, flags string) (string, string) {
	var b strings.Builder
	prefix := ""
	if strings.Contains(flags, "i") {
		prefix += "i"
	}
	if strings.Contains(flags, "m") {
		prefix += "m"
	}
	if strings.Contains(flags, "s") {
		prefix += "s"
	}
