func jsToUpper(s string) string {
	// handle special cases like ß -> SS
	var b strings.Builder
	for _, c := range s {
		switch c {
		case 'ß':
			b.WriteString("SS")
		case 'ŉ':
			b.WriteString("ʼN")
		default:
			b.WriteString(strings.ToUpper(string(c)))
		}
	}
	return b.String()
}

func jsToLower(s string) string {
	var b strings.Builder
	rs := []rune(s)
	for i, c := range rs {
		if c == 'Σ' {
			// final sigma
			if i > 0 && unicode.IsLetter(rs[i-1]) && (i+1 >= len(rs) || !unicode.IsLetter(rs[i+1])) {
				b.WriteRune('ς')
				continue
			}
		}
		if c == 'İ' {
			b.WriteString("i̇")
			continue
		}
		b.WriteRune(unicode.ToLower(c))
	}
	return b.String()
}

