package js

import (
	"math"
	"math/big"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ---------- JSON.parse ----------

type jsonParser struct {
	r   *Realm
	s   string
	pos int
}

func (p *jsonParser) fail(msg string) {
	p.r.syntaxError(msg)
}

func (p *jsonParser) skipWS() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		break
	}
}

func (p *jsonParser) parseValue(context string) Value {
	p.skipWS()
	if p.pos >= len(p.s) {
		p.fail("unexpected EOF")
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		p.pos++
		obj := p.r.newPlainObject()
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == '}' {
			p.pos++
			return obj
		}
		for {
			p.skipWS()
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
			if p.s[p.pos] != '"' {
				p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " looking for beginning of object key string")
			}
			key := p.parseString()
			p.skipWS()
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
			if p.s[p.pos] != ':' {
				p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " after object key")
			}
			p.pos++
			v := p.parseValue("value")
			obj.defineOwn(strKey(key), &Prop{Value: v, Enumerable: true, Writable: true, Configurable: true})
			p.skipWS()
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
			if p.s[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.s[p.pos] == '}' {
				p.pos++
				return obj
			}
			p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " after object key:value pair")
		}
	case c == '[':
		p.pos++
		var vals []Value
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == ']' {
			p.pos++
			return p.r.newArray(vals)
		}
		for {
			vals = append(vals, p.parseValue("value"))
			p.skipWS()
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
			if p.s[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.s[p.pos] == ']' {
				p.pos++
				return p.r.newArray(vals)
			}
			p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " after array element")
		}
	case c == '"':
		return p.parseString()
	case c == 't':
		return p.parseLiteral("true", true)
	case c == 'f':
		return p.parseLiteral("false", false)
	case c == 'n':
		return p.parseLiteral("null", null)
	case c == '-' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	}
	p.fail("invalid character " + quoteJSONChar(c) + " looking for beginning of value")
	return nil
}

func quoteJSONChar(c byte) string {
	return strconv.QuoteRune(rune(c))
}

func (p *jsonParser) parseLiteral(lit string, v Value) Value {
	for i := 0; i < len(lit); i++ {
		if p.pos >= len(p.s) {
			p.fail("unexpected EOF")
		}
		if p.s[p.pos] != lit[i] {
			p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " in literal " + lit + " (expecting " + strconv.QuoteRune(rune(lit[i])) + ")")
		}
		p.pos++
	}
	return v
}

func (p *jsonParser) parseNumber() Value {
	start := p.pos
	if p.s[p.pos] == '-' {
		p.pos++
	}
	if p.pos >= len(p.s) {
		p.fail("unexpected EOF")
	}
	if p.s[p.pos] == '0' {
		p.pos++
	} else if p.s[p.pos] >= '1' && p.s[p.pos] <= '9' {
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
	} else {
		p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " in numeric literal")
	}
	if p.pos < len(p.s) && p.s[p.pos] == '.' {
		p.pos++
		if p.pos >= len(p.s) {
			p.fail("unexpected EOF")
		}
