			p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " after decimal point in numeric literal")
		}
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
	}
	if p.pos < len(p.s) && (p.s[p.pos] == 'e' || p.s[p.pos] == 'E') {
		p.pos++
		if p.pos < len(p.s) && (p.s[p.pos] == '+' || p.s[p.pos] == '-') {
			p.pos++
		}
		if p.pos >= len(p.s) {
			p.fail("unexpected EOF")
		}
		if !(p.s[p.pos] >= '0' && p.s[p.pos] <= '9') {
			p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " in exponent of numeric literal")
		}
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
	}
	f, _ := strconv.ParseFloat(p.s[start:p.pos], 64)
	return f
}

func (p *jsonParser) parseString() string {
	p.pos++ // "
	var b strings.Builder
	for {
		if p.pos >= len(p.s) {
			p.fail("unexpected EOF")
		}
		c := p.s[p.pos]
		switch {
		case c == '"':
			p.pos++
			return b.String()
		case c == '\\':
			p.pos++
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
			e := p.s[p.pos]
			p.pos++
			switch e {
			case '"', '\\', '/':
				b.WriteByte(e)
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case 'u':
				if p.pos+4 > len(p.s) {
					p.fail("unexpected EOF")
				}
				v, err := strconv.ParseUint(p.s[p.pos:p.pos+4], 16, 32)
				if err != nil {
					p.fail("invalid character " + quoteJSONChar(p.s[p.pos]) + " in \\u hexadecimal character escape")
				}
				p.pos += 4
				cp := rune(v)
				if cp >= 0xD800 && cp <= 0xDBFF && p.pos+6 <= len(p.s) && p.s[p.pos] == '\\' && p.s[p.pos+1] == 'u' {
					if lo, err := strconv.ParseUint(p.s[p.pos+2:p.pos+6], 16, 32); err == nil && lo >= 0xDC00 && lo <= 0xDFFF {
						cp = (cp-0xD800)<<10 + (rune(lo) - 0xDC00) + 0x10000
						p.pos += 6
					}
				}
