			r, size := utf8.DecodeRuneInString(p.s[p.pos:])
			b.WriteRune(r)
			p.pos += size
		}
	}
}

func (r *Realm) jsonParse(s string, reviver Value) Value {
	p := &jsonParser{r: r, s: s}
	p.skipWS()
	if p.pos >= len(s) {
		r.syntaxError("Unexpected end of JSON input (EOF)")
	}
