		holder := r.newPlainObject()
		holder.setOwn(strKey(""), v)
		return r.internalize(holder, strKey(""), reviver)
	}
	return v
}

func (r *Realm) internalize(holder *Object, key PropKey, reviver Value) Value {
	val := r.getProp(holder, key, holder)
	if o, ok := val.(*Object); ok {
		if o.Class == "Array" {
			for i := 0; i < len(o.Array); i++ {
				nv := r.internalize(o, strKey(itoa(i)), reviver)
				if isUndefined(nv) {
					o.Array[i] = nil
				} else {
					o.Array[i] = nv
				}
			}
		} else {
			for _, k := range o.ownKeys(false) {
				p := o.getOwn(k)
				if p == nil || !p.Enumerable {
					continue
				}
				nv := r.internalize(o, k, reviver)
