// ---------- JSON.stringify ----------

type jsonStringifier struct {
	r            *Realm
	replacerFn   Value
	propertyList []string
	gap          string
	indent       string
	stack        []*Object
}

func (r *Realm) jsonStringify(v Value, replacer Value, space Value) Value {
	js := &jsonStringifier{r: r}
	if ro, ok := replacer.(*Object); ok {
		if ro.Fn != nil {
			js.replacerFn = ro
		} else if ro.Class == "Array" {
			seen := map[string]bool{}
			js.propertyList = []string{}
			for _, item := range ro.Array {
				var s string
				switch t := item.(type) {
				case string:
					s = t
				case float64:
					s = numberToString(t)
				case *Object:
					if t.Class == "String" || t.Class == "Number" {
						s = r.toString(t)
					} else {
						continue
					}
				default:
					continue
				}
				if !seen[s] {
					seen[s] = true
					js.propertyList = append(js.propertyList, s)
				}
			}
		}
	}
	if so, ok := space.(*Object); ok {
		if so.Class == "Number" {
