func (js *jsonStringifier) serializeProperty(key PropKey, holder *Object) (string, bool) {
	r := js.r
	value := r.getProp(holder, key, holder)
	if o, ok := value.(*Object); ok {
		toJSON := r.getV(o, "toJSON")
		if isCallable(toJSON) {
			value = r.call(toJSON, value, []Value{key.S})
		}
	} else if b, ok := value.(*big.Int); ok {
		toJSON := r.getV(r.BigIntProto, "toJSON")
		if isCallable(toJSON) {
			value = r.call(toJSON, b, []Value{key.S})
		}
	}
	if js.replacerFn != nil {
		value = r.call(js.replacerFn, holder, []Value{key.S, value})
	}
	if o, ok := value.(*Object); ok {
		switch o.Class {
		case "Number":
			value = r.toNumber(o)
		case "String":
			value = r.toString(o)
		case "Boolean":
			value = o.Prim
		case "BigInt":
			value = o.Prim
		}
	}
	switch t := value.(type) {
	case Null:
		return "null", true
	case bool:
		if t {
			return "true", true
		}
		return "false", true
	case string:
