func (js *jsonStringifier) checkCycle(o *Object) {
	for _, s := range js.stack {
		if s == o {
			js.r.typeError("Converting circular structure to JSON")
		}
	}
}

func (js *jsonStringifier) serializeObject(o *Object) string {
	js.checkCycle(o)
	js.stack = append(js.stack, o)
	stepback := js.indent
	js.indent += js.gap
	var keys []string
	if js.propertyList != nil {
		keys = js.propertyList
	} else {
		for _, k := range o.ownKeys(false) {
			if p := o.getOwn(k); p != nil && p.Enumerable {
				keys = append(keys, k.S)
			}
		}
	}
	var parts []string
	for _, k := range keys {
		s, ok := js.serializeProperty(strKey(k), o)
		if !ok {
			continue
		}
		member := jsonQuote(k) + ":"
		if js.gap != "" {
			member += " "
		}
		parts = append(parts, member+s)
	}
	var res string
	if len(parts) == 0 {
		res = "{}"
	} else if js.gap == "" {
		res = "{" + strings.Join(parts, ",") + "}"
	} else {
		sep := ",\n" + js.indent
		res = "{\n" + js.indent + strings.Join(parts, sep) + "\n" + stepback + "}"
	}
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
	return res
}

func (js *jsonStringifier) serializeArray(o *Object) string {
	js.checkCycle(o)
	js.stack = append(js.stack, o)
	stepback := js.indent
	js.indent += js.gap
	var parts []string
	n := len(o.Array)
	for i := 0; i < n; i++ {
		s, ok := js.serializeProperty(strKey(itoa(i)), o)
		if !ok {
			s = "null"
		}
		parts = append(parts, s)
	}
	var res string
	if len(parts) == 0 {
		res = "[]"
	} else if js.gap == "" {
		res = "[" + strings.Join(parts, ",") + "]"
	} else {
		sep := ",\n" + js.indent
		res = "[\n" + js.indent + strings.Join(parts, sep) + "\n" + stepback + "]"
	}
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
	return res
}

// jsonQuote quotes a string per JSON.stringify (QuoteJSONString).
func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, cp := range decodeWTF8(s) {
		switch cp {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if cp < 0x20 || (cp >= 0xD800 && cp <= 0xDFFF) {
				b.WriteString(`\u`)
				b.WriteString(leftPad(strconv.FormatInt(int64(cp), 16), 4))
			} else {
				b.WriteRune(cp)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func (r *Realm) setupJSON(g *Object) {
	j := r.newPlainObject()
	g.defineOwn(strKey("JSON"), &Prop{Value: j, Writable: true, Configurable: true})
	j.defineOwn(symKey(r.SymToStringTag), &Prop{Value: "JSON", Configurable: true})
	r.setMethod(j, "parse", 2, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.jsonParse(r.toString(arg(args, 0)), arg(args, 1))
	})
	r.setMethod(j, "stringify", 3, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.jsonStringify(arg(args, 0), arg(args, 1), arg(args, 2))
	})
}
