	pos int
}

func (p *jsonParser) fail(msg string) {
	p.r.syntaxError(msg)
}

func (p *jsonParser) skipWS() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		break
	}
}

func (p *jsonParser) parseValue(context string) Value {
	p.skipWS()
	if p.pos >= len(p.s) {
		p.fail("unexpected EOF")
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		p.pos++
		obj := p.r.newPlainObject()
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == '}' {
			p.pos++
			return obj
		}
		for {
			p.skipWS()
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
