			p.pos++
			return b.String()
		case c == '\\':
			p.pos++
			if p.pos >= len(p.s) {
				p.fail("unexpected EOF")
			}
			e := p.s[p.pos]
			p.pos++
			switch e {
			case '"', '\\', '/':
				b.WriteByte(e)
			case 'b':
				b.WriteByte('\b')
			case 'f':
