			member += " "
		}
		parts = append(parts, member+s)
	}
	var res string
	if len(parts) == 0 {
		res = "{}"
	} else if js.gap == "" {
		res = "{" + strings.Join(parts, ",") + "}"
	} else {
		sep := ",\n" + js.indent
		res = "{\n" + js.indent + strings.Join(parts, sep) + "\n" + stepback + "}"
	}
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
	return res
}

func (js *jsonStringifier) serializeArray(o *Object) string {
	js.checkCycle(o)
	js.stack = append(js.stack, o)
	stepback := js.indent
	js.indent += js.gap
	var parts []string
	n := len(o.Array)
	for i := 0; i < n; i++ {
		s, ok := js.serializeProperty(strKey(itoa(i)), o)
		if !ok {
			s = "null"
		}
		parts = append(parts, s)
	}
	var res string
	if len(parts) == 0 {
		res = "[]"
	} else if js.gap == "" {
		res = "[" + strings.Join(parts, ",") + "]"
	} else {
		sep := ",\n" + js.indent
		res = "[\n" + js.indent + strings.Join(parts, sep) + "\n" + stepback + "]"
	}
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
	return res
}

// jsonQuote quotes a string per JSON.stringify (QuoteJSONString).
func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, cp := range decodeWTF8(s) {
		switch cp {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if cp < 0x20 || (cp >= 0xD800 && cp <= 0xDFFF) {
				b.WriteString(`\u`)
				b.WriteString(leftPad(strconv.FormatInt(int64(cp), 16), 4))
			} else {
				b.WriteRune(cp)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

