func timeFromMs(ms float64, utc bool) time.Time {
	sec := math.Floor(ms / 1000)
	nsec := (ms - sec*1000) * 1e6
	t := time.Unix(int64(sec), int64(nsec))
	if utc {
		return t.UTC()
	}
	return t.Local()
}

func msFromTime(t time.Time) float64 {
	return float64(t.UnixNano()/1e6) + float64(t.UnixNano()%1e6)/1e6
}

func timeClip(ms float64) float64 {
	if math.IsNaN(ms) || math.IsInf(ms, 0) || math.Abs(ms) > 8.64e15 {
		return math.NaN()
	}
	return math.Trunc(ms) + 0 // +0 converts -0 to 0
}

// makeDate builds ms from components (month 0-based), in local or UTC.
func makeDateMs(year, month, day, h, m, s, ms float64, utc bool) float64 {
	for _, v := range []float64{year, month, day, h, m, s, ms} {
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return math.NaN()
		}
	}
	y := int(year) + int(math.Floor(month/12))
	mo := int(math.Mod(month, 12))
	if mo < 0 {
		mo += 12
	}
	loc := time.Local
	if utc {
		loc = time.UTC
	}
	t := time.Date(y, time.Month(mo+1), 1, 0, 0, 0, 0, loc)
