func timeClip(ms float64) float64 {
	if math.IsNaN(ms) || math.IsInf(ms, 0) || math.Abs(ms) > 8.64e15 {
		return math.NaN()
	}
	return math.Trunc(ms) + 0 // +0 converts -0 to 0
}

// makeDate builds ms from components (month 0-based), in local or UTC.
func makeDateMs(year, month, day, h, m, s, ms float64, utc bool) float64 {
	for _, v := range []float64{year, month, day, h, m, s, ms} {
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return math.NaN()
		}
	}
	y := int(year) + int(math.Floor(month/12))
	mo := int(math.Mod(month, 12))
	if mo < 0 {
		mo += 12
	}
	loc := time.Local
	if utc {
		loc = time.UTC
	}
	t := time.Date(y, time.Month(mo+1), 1, 0, 0, 0, 0, loc)
	total := msFromTime(t) + (day-1)*msPerDay + h*3600000 + m*60000 + s*1000 + ms
	if !utc {
		// adjust for DST differences between base date and target date
		t2 := timeFromMs(total, false)
		_, off1 := t.Zone()
		_, off2 := t2.Zone()
		total -= float64(off2-off1) * 1000
	}
	return total
}

var dateLayouts = []string{
	"2006-01-02T15:04:05.000Z07:00",
	"2006-01-02T15:04:05Z07:00",
	"2006-01-02T15:04Z07:00",
	"2006-01-02T15:04:05.000",
	"2006-01-02T15:04:05",
	"2006-01-02T15:04",
	"2006-01-02",
	"2006-01",
	"2006",
	"Mon, 02 Jan 2006 15:04:05 GMT",
	"Mon, 02 Jan 2006 15:04:05 MST",
	"Mon Jan 02 2006 15:04:05 GMT-0700",
	"Mon Jan 02 2006 15:04:05 GMT-0700 (MST)",
	"Mon Jan 02 2006",
	"Jan 02, 2006",
	"Jan 02, 2006 15:04:05",
	"Jan 2, 2006",
	"January 2, 2006",
	"2 Jan 2006",
	"02 Jan 2006 15:04:05 GMT",
	"2006/01/02",
	"2006/01/02 15:04:05",
	"2006/01/02 15:04",
	"01/02/2006",
	"01/02/2006 15:04:05",
	"2006-01-02 15:04:05",
	"2006-01-02 15:04",
	"2006-01-02 15:04:05Z07:00",
	"2006-01-02T15:04:05.000000Z07:00",
	"2006-01-02T15:04:05.000000000Z07:00",
}

func parseDate(s string) float64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return math.NaN()
	}
	// ISO formats: date-only is UTC, date-time without offset is local
	isoDateOnly := len(s) == 10 || len(s) == 7 || len(s) == 4
	for _, layout := range dateLayouts {
		loc := time.Local
		if isoDateOnly || strings.HasSuffix(layout, "Z07:00") || strings.Contains(layout, "GMT") || strings.Contains(layout, "MST") {
			loc = time.UTC
		}
		t, err := time.ParseInLocation(layout, s, loc)
		if err == nil {
			return msFromTime(t)
		}
	}
	// expanded years etc: fallback
	if strings.HasSuffix(s, "Z") {
		t, err := time.Parse(time.RFC3339Nano, s)
		if err == nil {
			return msFromTime(t)
		}
	}
	return math.NaN()
}

func (r *Realm) newDate(ms float64, nt *Object) *Object {
	o := r.createFromCtor(nt, r.DateProto)
	o.Class = "Date"
	o.Date = timeClip(ms)
	return o
}

var weekdays = []string{"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"}
var months = []string{"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}

func pad2(n int) string {
	if n < 10 && n >= 0 {
		return "0" + strconv.Itoa(n)
	}
	return strconv.Itoa(n)
}

func pad3(n int) string {
	s := strconv.Itoa(n)
	for len(s) < 3 {
		s = "0" + s
	}
	return s
}

func fmtYear(y int) string {
	if y >= 0 && y <= 9999 {
		s := strconv.Itoa(y)
		for len(s) < 4 {
			s = "0" + s
		}
		return s
	}
	if y < 0 {
		s := strconv.Itoa(-y)
		for len(s) < 6 {
			s = "0" + s
		}
		return "-" + s
	}
	s := strconv.Itoa(y)
	for len(s) < 6 {
		s = "0" + s
	}
	return "+" + s
}

func tzString(t time.Time) string {
	name, off := t.Zone()
	sign := "+"
	if off < 0 {
		sign = "-"
		off = -off
	}
	hh := off / 3600
	mm := (off % 3600) / 60
	full := name
	if name == "UTC" {
		full = "Coordinated Universal Time"
	}
	return "GMT" + sign + pad2(hh) + pad2(mm) + " (" + full + ")"
}

func dateToString(ms float64) string {
	if math.IsNaN(ms) {
		return "Invalid Date"
	}
	t := timeFromMs(ms, false)
	return weekdays[t.Weekday()] + " " + months[t.Month()-1] + " " + pad2(t.Day()) + " " + fmtYear(t.Year()) + " " + pad2(t.Hour()) + ":" + pad2(t.Minute()) + ":" + pad2(t.Second()) + " " + tzString(t)
}

func dateToISO(ms float64) string {
	t := timeFromMs(ms, true)
	return fmtYear(t.Year()) + "-" + pad2(int(t.Month())) + "-" + pad2(t.Day()) + "T" + pad2(t.Hour()) + ":" + pad2(t.Minute()) + ":" + pad2(t.Second()) + "." + pad3(t.Nanosecond()/1e6) + "Z"
}

func (r *Realm) setupDate(g *Object) {
	dp := r.DateProto
	ctor := r.newCtor("Date", 7, func(r *Realm, this Value, args []Value, nt *Object) Value {
		if nt == nil {
			return dateToString(float64(time.Now().UnixNano() / 1e6))
		}
		switch len(args) {
		case 0:
			return r.newDate(float64(time.Now().UnixNano()/1e6), nt)
		case 1:
			v := args[0]
			if o, ok := v.(*Object); ok && o.Class == "Date" {
				return r.newDate(o.Date, nt)
			}
			p := r.toPrimitive(v, "")
			if s, ok := p.(string); ok {
				return r.newDate(parseDate(s), nt)
			}
			return r.newDate(r.toNumber(p), nt)
		}
		nums := make([]float64, 7)
		defaults := []float64{0, 0, 1, 0, 0, 0, 0}
		for i := 0; i < 7; i++ {
			if i < len(args) {
				nums[i] = r.toNumber(args[i])
			} else {
				nums[i] = defaults[i]
			}
		}
		y := nums[0]
		if !math.IsNaN(y) {
			yi := math.Trunc(y)
			if yi >= 0 && yi <= 99 {
				y = 1900 + yi
			}
		}
		ms := makeDateMs(y, nums[1], nums[2], nums[3], nums[4], nums[5], nums[6], false)
		return r.newDate(ms, nt)
	}, dp)
	g.defineOwn(strKey("Date"), &Prop{Value: ctor, Writable: true, Configurable: true})
	r.setMethod(ctor, "now", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return float64(time.Now().UnixNano() / 1e6)
	})
	r.setMethod(ctor, "parse", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return parseDate(r.toString(arg(args, 0)))
	})
	r.setMethod(ctor, "UTC", 7, func(r *Realm, this Value, args []Value, nt *Object) Value {
		nums := make([]float64, 7)
		defaults := []float64{math.NaN(), 0, 1, 0, 0, 0, 0}
		for i := 0; i < 7; i++ {
			if i < len(args) {
				nums[i] = r.toNumber(args[i])
			} else {
				nums[i] = defaults[i]
			}
		}
		y := nums[0]
		if !math.IsNaN(y) {
			yi := math.Trunc(y)
			if yi >= 0 && yi <= 99 {
				y = 1900 + yi
			}
		}
		return timeClip(makeDateMs(y, nums[1], nums[2], nums[3], nums[4], nums[5], nums[6], true))
	})

	getter := func(name string, utc bool, f func(t time.Time) float64) {
		r.setMethod(dp, name, 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
			d := r.thisDate(this)
			if math.IsNaN(d.Date) {
				return math.NaN()
			}
			return f(timeFromMs(d.Date, utc))
		})
	}
	for _, utc := range []bool{false, true} {
		pre := "get"
		if utc {
			pre = "getUTC"
		}
		getter(pre+"FullYear", utc, func(t time.Time) float64 { return float64(t.Year()) })
		getter(pre+"Month", utc, func(t time.Time) float64 { return float64(t.Month() - 1) })
		getter(pre+"Date", utc, func(t time.Time) float64 { return float64(t.Day()) })
		getter(pre+"Day", utc, func(t time.Time) float64 { return float64(t.Weekday()) })
		getter(pre+"Hours", utc, func(t time.Time) float64 { return float64(t.Hour()) })
		getter(pre+"Minutes", utc, func(t time.Time) float64 { return float64(t.Minute()) })
		getter(pre+"Seconds", utc, func(t time.Time) float64 { return float64(t.Second()) })
		getter(pre+"Milliseconds", utc, func(t time.Time) float64 { return float64(t.Nanosecond() / 1e6) })
	}
	getter("getYear", false, func(t time.Time) float64 { return float64(t.Year() - 1900) })
	r.setMethod(dp, "getTime", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.thisDate(this).Date
	})
	r.setMethod(dp, "valueOf", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return r.thisDate(this).Date
	})
	r.setMethod(dp, "getTimezoneOffset", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return math.NaN()
		}
		_, off := timeFromMs(d.Date, false).Zone()
		return float64(-off / 60)
	})
	r.setMethod(dp, "setTime", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		d.Date = timeClip(r.toNumber(arg(args, 0)))
		return d.Date
	})
	// setters
	setter := func(name string, utc bool, apply func(c []float64, args []float64)) {
		r.setMethod(dp, name, 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
			d := r.thisDate(this)
			nums := make([]float64, len(args))
			for i, a := range args {
				nums[i] = r.toNumber(a)
			}
			if math.IsNaN(d.Date) {
				if !strings.Contains(name, "FullYear") {
					return math.NaN()
				}
				d.Date = 0
			}
			t := timeFromMs(d.Date, utc)
			c := []float64{float64(t.Year()), float64(t.Month() - 1), float64(t.Day()), float64(t.Hour()), float64(t.Minute()), float64(t.Second()), float64(t.Nanosecond() / 1e6)}
			if len(nums) == 0 {
				d.Date = math.NaN()
				return d.Date
			}
			apply(c, nums)
			d.Date = timeClip(makeDateMs(c[0], c[1], c[2], c[3], c[4], c[5], c[6], utc))
			return d.Date
		})
	}
	for _, utc := range []bool{false, true} {
		pre := "set"
		if utc {
			pre = "setUTC"
		}
		setter(pre+"FullYear", utc, func(c, a []float64) {
			c[0] = a[0]
			if len(a) > 1 {
				c[1] = a[1]
			}
			if len(a) > 2 {
				c[2] = a[2]
			}
		})
		setter(pre+"Month", utc, func(c, a []float64) {
			c[1] = a[0]
			if len(a) > 1 {
				c[2] = a[1]
			}
		})
		setter(pre+"Date", utc, func(c, a []float64) { c[2] = a[0] })
		setter(pre+"Hours", utc, func(c, a []float64) {
			c[3] = a[0]
			if len(a) > 1 {
				c[4] = a[1]
			}
			if len(a) > 2 {
				c[5] = a[2]
			}
			if len(a) > 3 {
				c[6] = a[3]
			}
		})
		setter(pre+"Minutes", utc, func(c, a []float64) {
			c[4] = a[0]
			if len(a) > 1 {
				c[5] = a[1]
			}
			if len(a) > 2 {
				c[6] = a[2]
			}
		})
		setter(pre+"Seconds", utc, func(c, a []float64) {
			c[5] = a[0]
			if len(a) > 1 {
				c[6] = a[1]
			}
		})
		setter(pre+"Milliseconds", utc, func(c, a []float64) { c[6] = a[0] })
	}
	r.setMethod(dp, "toISOString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			r.rangeError("Invalid time value")
		}
		return dateToISO(d.Date)
	})
	r.setMethod(dp, "toJSON", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		o := r.toObject(this)
		tv := r.toPrimitive(o, "number")
		if f, ok := tv.(float64); ok && (math.IsNaN(f) || math.IsInf(f, 0)) {
			return null
		}
		return r.call(r.getV(o, "toISOString"), o, nil)
	})
	r.setMethod(dp, "toString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return dateToString(r.thisDate(this).Date)
	})
	r.setMethod(dp, "toDateString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return "Invalid Date"
		}
		t := timeFromMs(d.Date, false)
		return weekdays[t.Weekday()] + " " + months[t.Month()-1] + " " + pad2(t.Day()) + " " + fmtYear(t.Year())
	})
	r.setMethod(dp, "toTimeString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return "Invalid Date"
		}
		t := timeFromMs(d.Date, false)
		return pad2(t.Hour()) + ":" + pad2(t.Minute()) + ":" + pad2(t.Second()) + " " + tzString(t)
	})
	r.setMethod(dp, "toUTCString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return "Invalid Date"
		}
		t := timeFromMs(d.Date, true)
		return weekdays[t.Weekday()] + ", " + pad2(t.Day()) + " " + months[t.Month()-1] + " " + fmtYear(t.Year()) + " " + pad2(t.Hour()) + ":" + pad2(t.Minute()) + ":" + pad2(t.Second()) + " GMT"
	})
	dp.defineOwn(strKey("toGMTString"), &Prop{Value: r.getV(dp, "toUTCString"), Writable: true, Configurable: true})
	r.setMethod(dp, "toLocaleDateString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return "Invalid Date"
		}
		t := timeFromMs(d.Date, false)
		return strconv.Itoa(int(t.Month())) + "/" + strconv.Itoa(t.Day()) + "/" + strconv.Itoa(t.Year())
	})
	r.setMethod(dp, "toLocaleTimeString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return "Invalid Date"
		}
		t := timeFromMs(d.Date, false)
		h := t.Hour() % 12
		if h == 0 {
			h = 12
		}
		ampm := "AM"
		if t.Hour() >= 12 {
			ampm = "PM"
		}
		return strconv.Itoa(h) + ":" + pad2(t.Minute()) + ":" + pad2(t.Second()) + " " + ampm
	})
	r.setMethod(dp, "toLocaleString", 0, func(r *Realm, this Value, args []Value, nt *Object) Value {
		d := r.thisDate(this)
		if math.IsNaN(d.Date) {
			return "Invalid Date"
		}
		ds := r.call(r.getV(dp, "toLocaleDateString"), this, nil)
		ts := r.call(r.getV(dp, "toLocaleTimeString"), this, nil)
		return r.toString(ds) + ", " + r.toString(ts)
	})
	r.setSymMethod(dp, r.SymToPrimitive, "[Symbol.toPrimitive]", 1, func(r *Realm, this Value, args []Value, nt *Object) Value {
		o, ok := this.(*Object)
		if !ok {
			r.typeError("Date.prototype[Symbol.toPrimitive] called on non-object")
		}
		hint := r.toString(arg(args, 0))
		var order []string
		switch hint {
		case "string", "default":
			order = []string{"toString", "valueOf"}
		case "number":
			order = []string{"valueOf", "toString"}
		default:
			r.typeError("Invalid hint: " + hint)
		}
		for _, name := range order {
			fn := r.getV(o, name)
			if isCallable(fn) {
				res := r.call(fn, o, nil)
				if !isObject(res) {
					return res
				}
			}
		}
		r.typeError("Cannot convert object to primitive value")
		return undefined
	})
}
