// Call calls a function value. Thrown JS errors are returned as *JSError.
func (r *Realm) Call(fn Value, this Value, args []Value) (result Value, err error) {
	defer func() {
		if rec := recover(); rec != nil {
			switch t := rec.(type) {
			case *Throw:
				err = &JSError{Value: t.Value, Realm: r}
			case *ExitError:
				err = t
			default:
				panic(rec)
			}
		}
	}()
