// RunScript parses and executes source code in the global scope.
func (r *Realm) RunScript(src string, strict bool) (Value, error) {
	prog, perr := Parse(src, strict)
	if perr != nil {
		return nil, perr
	}
	return r.RunProgram(prog)
}

// Exported helpers for embedding.

func (r *Realm) NewObject() *Object        { return r.newPlainObject() }
func (r *Realm) NewArray(v []Value) *Object { return r.newArray(v) }
func (r *Realm) Undefined() Value           { return undefined }
func (r *Realm) Null() Value                { return null }
func IsUndefined(v Value) bool              { return isUndefined(v) }
func IsNull(v Value) bool                   { return isNull(v) }
func IsCallable(v Value) bool               { return isCallable(v) }

func (r *Realm) Set(o *Object, key string, v Value) {
	o.defineOwn(strKey(key), &Prop{Value: v, Enumerable: true, Writable: true, Configurable: true})
}

func (r *Realm) Get(v Value, key string) Value { return r.getV(v, key) }

func (r *Realm) SetGlobal(name string, v Value) {
	r.Global.defineOwn(strKey(name), &Prop{Value: v, Writable: true, Configurable: true, Enumerable: true})
}

func (r *Realm) GetGlobal(name string) Value { return r.getV(r.Global, name) }

func (r *Realm) NewNativeFunction(name string, length int, fn func(this Value, args []Value) Value) *Object {
	return r.newNativeFunction(name, length, func(r *Realm, this Value, args []Value, nt *Object) Value {
		return fn(this, args)
	})
}

// Call calls a function value. Thrown JS errors are returned as *JSError.
func (r *Realm) Call(fn Value, this Value, args []Value) (result Value, err error) {
	defer func() {
		if rec := recover(); rec != nil {
			switch t := rec.(type) {
			case *Throw:
				err = &JSError{Value: t.Value, Realm: r}
			case *ExitError:
				err = t
			default:
				panic(rec)
			}
		}
	}()
	return r.call(fn, this, args), nil
}

func (r *Realm) ToString(v Value) string { return r.toString(v) }
func (r *Realm) ToNumber(v Value) float64 { return r.toNumber(v) }

