func (r *Realm) ThrowValue(v Value) { throwValue(v) }

// OwnEnumerableKeys returns enumerable own string keys in spec order.
func (r *Realm) OwnEnumerableKeys(o *Object) []string {
	var out []string
	for _, k := range o.ownKeys(false) {
		if p := o.getOwn(k); p != nil && p.Enumerable {
			out = append(out, k.S)
		}
	}
	return out
