package engine

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// Transform converts fx shorthand syntax into JavaScript.
func Transform(code string) string {
	if strings.HasPrefix(code, "@") {
		return "map((x, i) => apply(" + Transform(code[1:]) + ", x, i))"
	}
	if strings.HasPrefix(code, ".") {
		if strings.Contains(code, "[]") {
			parts := strings.Split(code, "[]")
			ok := true
			for _, p := range parts {
				if !isSimplePath(p) {
					ok = false
					break
				}
			}
			if ok {
				var b strings.Builder
				for i, p := range parts {
					if i == 0 {
						b.WriteString("(x => x" + p)
						continue
					}
					b.WriteString(".flatMap(x => x" + p)
				}
				b.WriteString(strings.Repeat(")", len(parts)-1))
				b.WriteString(")(x)")
				return b.String()
			}
		}
		return "x" + code
	}
	return code
}

func isSimplePath(p string) bool {
	for _, r := range p {
		if r == '.' || r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) {
			continue
		}
		return false
	}
	return true
}

// IsIdentityReducer reports whether the single reducer is a no-op that should
// print the raw input.
func IsIdentityReducer(code string) bool {
	return code == "." || code == "this" || code == "x"
}

// Display builds the two-line error location display for the given argument
// index within the list of reducers.
func Display(args []string, idx int) (string, string) {
	full := strings.Join(args, " ")
	start := 0
	for i := 0; i < idx; i++ {
		start += utf8.RuneCountInString(args[i]) + 1
	}
	length := utf8.RuneCountInString(args[idx])
	end := start + length
	runes := []rune(full)
	total := len(runes)
	const width = 80
	pad := (width - 4 - length) / 2
	if pad < 1 {
		pad = 1
	}
	from := start - pad
	if from < 0 {
		from = 0
	}
	to := end + pad
	if to > total {
		to = total
	}
	var b strings.Builder
	b.WriteString("  ")
	caretPad := 2
	if from > 0 {
		b.WriteString("…")
		caretPad++
	}
	b.WriteString(string(runes[from:to]))
	if to < total {
		b.WriteString("…")
	}
	caretPad += start - from
	return b.String(), strings.Repeat(" ", caretPad) + strings.Repeat("^", length)
}
