	Args     []string
	FileName string
	Printer  jsonx.Printer
	Theme    theme.Theme
	Stdout   func(string)
	Stderr   func(string)
}

// mainLine is the line number of the first reducer's return statement in the
// combined script (matching the reference implementation).
const mainLine = 211

func preludeLines() int { return strings.Count(prelude, "\n") }

// NewVM creates a realm with the fx runtime installed.
func NewVM(opts *Options) (*js.Realm, error) {
	r := js.NewRealm()
	stdout := opts.Stdout
	if stdout == nil {
		stdout = func(s string) { fmt.Fprint(os.Stdout, s) }
	}
	r.SetGlobal("println", r.NewNativeFunction("println", 1, func(this js.Value, args []js.Value) js.Value {
		s := ""
		if len(args) > 0 && !js.IsUndefined(args[0]) {
			s = r.ToString(args[0])
		}
		stdout(js.SanitizeUTF8(s) + "\n")
		return r.Null()
	}))
	r.SetGlobal("__save__", r.NewNativeFunction("__save__", 1, func(this js.Value, args []js.Value) js.Value {
		if opts.FileName == "" {
			r.ThrowGoError("specify a file as the first argument to be able to save: fx file.json ")
		}
		data := ""
		if len(args) > 0 {
			data = r.ToString(args[0])
		}
		if err := os.WriteFile(opts.FileName, []byte(data+"\n"), 0644); err != nil {
			r.ThrowGoError(err.Error())
		}
		return r.Null()
	}))
	r.SetGlobal("__stringify__", r.NewNativeFunction("__stringify__", 1, func(this js.Value, args []js.Value) js.Value {
		var v js.Value = r.Undefined()
		if len(args) > 0 {
			v = args[0]
		}
		return IndentedJSON(r, v) + "\n"
	}))
	r.SetGlobal("__toBase64__", r.NewNativeFunction("__toBase64__", 1, func(this js.Value, args []js.Value) js.Value {
		s := ""
		if len(args) > 0 {
			s = r.ToString(args[0])
		}
		return base64.StdEncoding.EncodeToString([]byte(s))
	}))
	r.SetGlobal("__fromBase64__", r.NewNativeFunction("__fromBase64__", 1, func(this js.Value, args []js.Value) js.Value {
		s := ""
		if len(args) > 0 {
			s = r.ToString(args[0])
		}
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			r.ThrowGoError(err.Error())
		}
		return string(b)
	}))
