// toGoValue converts a JS value into generic Go data for YAML output.
func toGoValue(r *js.Realm, v js.Value) interface{} {
	switch t := v.(type) {
	case js.Undefined, js.Null:
		return nil
	case bool:
		return t
	case float64:
		return t
	case string:
		return t
	case *js.Object:
		if t.IsFunction() {
			return nil
		}
		if t.IsArray() {
			var out []interface{}
			for _, e := range t.ArrayValues() {
				out = append(out, toGoValue(r, e))
			}
			if out == nil {
				out = []interface{}{}
			}
			return out
		}
		m := &input.OrderedMap{Values: map[string]interface{}{}}
		for _, k := range r.OwnEnumerableKeys(t) {
			m.Keys = append(m.Keys, k)
			m.Values[k] = toGoValue(r, r.Get(t, k))
		}
		return m
	}
	return r.ToString(v)
}

// loadRC runs .fxrc.js configuration files.
func loadRC(r *js.Realm, stderr func(string)) bool {
	var paths []string
	home, _ := os.UserHomeDir()
	if home != "" {
		paths = append(paths, filepath.Join(home, ".fxrc.js"))
	}
	xdg := os.Getenv("XDG_CONFIG_HOME")
	if xdg == "" && home != "" {
		xdg = filepath.Join(home, ".config")
	}
	if xdg != "" {
		paths = append(paths, filepath.Join(xdg, "fx", ".fxrc.js"), filepath.Join(xdg, "fx", "fxrc.js"))
	}
	for _, p := range paths {
		data, err := os.ReadFile(p)
		if err != nil {
			continue
		}
		if _, err := r.RunScript(string(data), false); err != nil {
			if se, ok := err.(*js.SyntaxError); ok {
				stderr(se.Message + "\n")
			} else {
				stderr(err.Error() + "\n")
			}
			return false
		}
	}
	return true
}

// buildMain generates the source of the __main__ function.
func buildMain(args []string, codes []string) string {
	var b strings.Builder
	b.WriteString("function __main__(json) {\n")
	for i, code := range codes {
		disp, carets := Display(args, i)
		msg := "\n" + disp + "\n" + carets + "\n\n"
		if code != args[i] {
			msg += code + "\n\n"
		}
		b.WriteString("\n  try {\n    json = apply((function () {\n      const x = this\n      return ")
		b.WriteString(code)
		b.WriteString("\n    }).call(json), json)\n  } catch (e) {\n    throw ")
		b.WriteString(jsStringLiteral(msg))
		b.WriteString(" + e.toString()\n  }\n\n  if (json === skip) return skip\n")
	}
	b.WriteString("\n  return json\n}")
	return b.String()
}

func jsStringLiteral(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if r < 0x20 {
				b.WriteString(fmt.Sprintf(`\u%04x`, r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// standalone wraps a single reducer the way the reference checks syntax.
func standaloneWrapper(code string) string {
	return "function __main__(json) {\n\n  try {\n    json = apply((function () {\n      const x = this\n      return " + code + "\n    }).call(json), json)\n  } catch (e) {\n    throw e\n  }\n  return json\n}"
}

// cleanParserMessage reproduces the quirks of the reference error messages.
func cleanParserMessage(msg string) string {
	switch {
	case strings.HasPrefix(msg, "Unexpected token ..."):
		return msg
	case strings.HasPrefix(msg, "Unexpected token "):
		return msg + " "
	}
	return msg
}

// Run executes reducers against the input and returns the exit code.
func Run(opts Options) int {
	stdout := opts.Stdout
	if stdout == nil {
		stdout = func(s string) { fmt.Fprint(os.Stdout, s) }
	}
	stderr := opts.Stderr
	if stderr == nil {
		stderr = func(s string) { fmt.Fprint(os.Stderr, s) }
	}
	opts.Stdout = stdout
	args := opts.Args

	// Identity shortcut: print raw input.
	if len(args) == 1 && IsIdentityReducer(args[0]) {
		err := opts.Source.Each(func(n *jsonx.Node) error {
			if n.Kind == jsonx.KindString {
				s, err := strconv.Unquote(n.Value)
				if err != nil {
					panic(&Panic{Msg: "invalid syntax"})
				}
				stdout(s + "\n")
				return nil
			}
			stdout(opts.Printer.String(n) + "\n")
			return nil
		})
		if err != nil {
			stderr(err.Error() + "\n")
			return 1
		}
		return 0
	}

	codes := make([]string, len(args))
	for i, a := range args {
		codes[i] = Transform(a)
	}

	// Syntax check each reducer standalone (sloppy mode).
	for i, code := range codes {
		if _, perr := js.Parse(standaloneWrapper(code), false); perr != nil {
			disp, carets := Display(args, i)
			var b strings.Builder
			b.WriteString("\n" + disp + "\n" + carets + "\n\n")
			if code != args[i] {
				b.WriteString(code + "\n\n")
			}
			if perr.Kind == "compiler" {
				b.WriteString(fmt.Sprintf("SyntaxError: SyntaxError: %s at %d:%d\n", perr.Message, perr.Line, perr.Col))
			} else {
				b.WriteString(cleanParserMessage(perr.Message) + "\n")
			}
			stderr(b.String())
			return 1
		}
	}

	r, err := NewVM(&opts)
	if err != nil {
		stderr(err.Error() + "\n")
		return 1
	}
	if !loadRC(r, stderr) {
		return 1
	}

	mainSrc := buildMain(args, codes)
	// Compile the full script in strict mode to catch strict-mode violations.
	pl := preludeLines()
	pad := mainLine - 5 - 1 - pl
	full := prelude + strings.Repeat("\n", max(pad, 0)) + mainSrc
	prog, perr := js.Parse(full, true)
