// Script returns the completion script for a shell.
func Script(shell string) string {
	switch shell {
	case "bash":
		return "complete -o filenames -C fx fx\n"
	case "zsh":
		return zshScript
	case "fish":
		return "complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'\n"
	}
	return "unknown shell type\n"
