		if p, err := strconv.Atoi(os.Getenv("COMP_POINT")); err == nil && p >= 0 && p <= len(line) {
			line = line[:p]
		}
	}
	words := splitWords(line)
	if len(words) == 0 {
		return
	}
	cur := words[len(words)-1]
	if mode == "bash" && len(os.Args) > 2 {
		cur = os.Args[2]
	}
	cands := complete(words[1:], cur)
	var out []string
	for _, c := range cands {
		switch mode {
		case "zsh":
			out = append(out, c.display+"\t"+c.insert+"\t"+c.typ)
		default:
			out = append(out, c.insert)
		}
	}
	fmt.Print(strings.Join(out, "\n"))
}

func complete(args []string, cur string) []candidate {
	var cands []candidate
	if strings.HasPrefix(cur, "-") {
		for _, f := range flags {
			if strings.HasPrefix(f, cur) {
				cands = append(cands, candidate{display: f, insert: f, typ: "flag"})
			}
		}
		return cands
	}
	if len(args) <= 1 {
		return completeFiles(cur)
	}
	fileName := args[0]
	data, err := os.ReadFile(fileName)
	if err != nil {
		return completeFiles(cur)
	}
	nodes, perr := jsonx.ParseAll(data, false)
	if len(nodes) == 0 || (perr != nil && len(nodes) == 0) {
		return nil
	}
	node := nodes[0]
	// apply previous reducers
	for _, prev := range args[1 : len(args)-1] {
		n, ok := evalPath(node, prev)
		if !ok {
			node = nil
			break
		}
		node = n
	}
	if node != nil {
		base, partial := cur, ""
		if i := strings.LastIndex(cur, "."); i >= 0 {
			base, partial = cur[:i+1], cur[i+1:]
		} else if strings.HasPrefix(cur, "[") || strings.HasPrefix(cur, "@[") || strings.HasPrefix(cur, "x[") {
			// bracket completion without dot
			i := strings.Index(cur, "[")
			base, partial = cur[:i], cur[i:]
		}
		pathExpr := strings.TrimSuffix(base, ".")
		target, ok := evalPath(node, pathExpr)
		if ok && target != nil && target.Kind == jsonx.KindObject {
			bracketOnly := false
			if strings.HasPrefix(partial, "[") {
				if partial == "[" || partial == "[\"" || partial == "['" {
					bracketOnly = true
				} else {
					ok = false
				}
			}
			if ok {
				prefix := strings.TrimSuffix(base, ".")
				for _, child := range orderedChildren(target) {
					key := engine.Unquote(child.Key)
					var seg string
					if isIdentifier(key) {
						if bracketOnly {
							continue
						}
						if !strings.HasPrefix(key, partial) {
							continue
						}
						seg = "." + key
					} else {
						if !bracketOnly && partial != "" {
							continue
						}
						seg = "[" + strconv.Quote(key) + "]"
					}
					cands = append(cands, candidate{display: seg, insert: prefix + seg, typ: "key"})
				}
			}
		}
	}
	for _, g := range engine.PreludeGlobals {
		if strings.HasPrefix(g, cur) {
			cands = append(cands, candidate{display: g, insert: g, typ: "global"})
		}
	}
	return cands
}

// orderedChildren returns object members in JS property order.
func orderedChildren(n *jsonx.Node) []*jsonx.Node {
	var ints []*jsonx.Node
	var rest []*jsonx.Node
	for _, c := range n.Children {
		key := engine.Unquote(c.Key)
		if isArrayIndex(key) {
			ints = append(ints, c)
		} else {
			rest = append(rest, c)
		}
	}
	sort.SliceStable(ints, func(i, j int) bool {
		a, _ := strconv.Atoi(engine.Unquote(ints[i].Key))
		b, _ := strconv.Atoi(engine.Unquote(ints[j].Key))
		return a < b
	})
	return append(ints, rest...)
}

func isArrayIndex(s string) bool {
	if s == "" || len(s) > 10 {
		return false
	}
	if s == "0" {
		return true
	}
	if s[0] < '1' || s[0] > '9' {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func isIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if r == '$' || r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') {
			continue
		}
		if i > 0 && r >= '0' && r <= '9' {
			continue
		}
		return false
	}
	return true
}

// evalPath evaluates a simple path expression against a node.
func evalPath(n *jsonx.Node, expr string) (*jsonx.Node, bool) {
	s := expr
	if strings.HasPrefix(s, "x") {
		s = s[1:]
	} else if strings.HasPrefix(s, "@") {
		s = s[1:]
	} else if strings.HasPrefix(s, "this") {
		s = s[4:]
	}
	cur := n
	for len(s) > 0 {
		switch {
		case s[0] == '.':
			s = s[1:]
			j := 0
			for j < len(s) && s[j] != '.' && s[j] != '[' {
				j++
			}
			name := s[:j]
			s = s[j:]
			if name == "" {
				if len(s) == 0 {
					return cur, true
				}
				if s[0] == '[' {
					continue
				}
				return nil, false
			}
			if cur == nil || cur.Kind != jsonx.KindObject {
				return nil, false
			}
			found := false
			for _, c := range cur.Children {
				if engine.Unquote(c.Key) == name {
					cur = c
					found = true
					break
				}
			}
			if !found {
				return nil, false
			}
		case s[0] == '[':
			end := strings.Index(s, "]")
			if end < 0 {
				return nil, false
			}
			inner := s[1:end]
			s = s[end+1:]
			if strings.HasPrefix(inner, "\"") || strings.HasPrefix(inner, "'") {
				key, err := strconv.Unquote(strings.ReplaceAll(inner, "'", "\""))
				if err != nil {
					return nil, false
				}
				if cur == nil || cur.Kind != jsonx.KindObject {
					return nil, false
				}
				found := false
				for _, c := range cur.Children {
					if engine.Unquote(c.Key) == key {
						cur = c
						found = true
						break
					}
				}
				if !found {
					return nil, false
				}
			} else {
				idx, err := strconv.Atoi(inner)
				if err != nil || cur == nil || cur.Kind != jsonx.KindArray || idx < 0 || idx >= len(cur.Children) {
					return nil, false
				}
				cur = cur.Children[idx]
			}
		default:
			return nil, false
		}
	}
	return cur, true
}

func completeFiles(cur string) []candidate {
	var cands []candidate
	dir := cur
	prefix := ""
	if cur == "" {
		dir = "."
	} else if st, err := os.Stat(cur); err == nil {
		if !st.IsDir() {
			return nil
		}
	} else {
		dir = filepath.Dir(cur)
		prefix = filepath.Base(cur)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	for _, e := range entries {
		name := e.Name()
		if prefix != "" && !strings.HasPrefix(name, prefix) {
			continue
		}
		var full string
		if cur == "" {
			full = name
		} else if dir == cur {
			full = filepath.Join(cur, name)
			if strings.HasSuffix(cur, "/") && !strings.HasPrefix(full, cur) {
				full = cur + name
			}
		} else {
			full = filepath.Join(dir, name)
		}
		cands = append(cands, candidate{display: name, insert: full, typ: "file"})
	}
	return cands
}
