// Key represents a decoded key press.
type Key struct {
	Name string // e.g. "a", "enter", "up", "ctrl+c", "shift+up", "pgup"
	Rune rune
	// mouse wheel
	Wheel int // -1 up, 1 down
}

type keyReader struct {
	f   *os.File
	buf []byte
	ch  chan []byte
}

func newKeyReader(f *os.File) *keyReader {
	kr := &keyReader{f: f, ch: make(chan []byte, 16)}
	go func() {
		for {
			b := make([]byte, 256)
			n, err := f.Read(b)
			if err != nil {
				close(kr.ch)
				return
			}
			if n > 0 {
				kr.ch <- b[:n]
			}
		}
	}()
	return kr
}

