		if len(kr.buf) > 0 {
			k, n := decodeKey(kr.buf)
			if n == 0 {
				// incomplete escape sequence: wait briefly for more
				select {
				case b, ok := <-kr.ch:
					if !ok {
						k, n = decodeKeyFinal(kr.buf)
						kr.buf = kr.buf[n:]
						return k, true, false
					}
					kr.buf = append(kr.buf, b...)
					continue
				case <-time.After(50 * time.Millisecond):
					k, n = decodeKeyFinal(kr.buf)
					kr.buf = kr.buf[n:]
					return k, true, false
				}
			}
			kr.buf = kr.buf[n:]
			return k, true, false
		}
		select {
		case b, ok := <-kr.ch:
			if !ok {
				return Key{}, false, false
			}
			kr.buf = append(kr.buf, b...)
		case <-resize:
			return Key{}, true, true
		}
	}
