// decodeKey decodes one key from buf. Returns n=0 if more bytes are needed.
func decodeKey(buf []byte) (Key, int) {
	b := buf[0]
	if b == 0x1b {
		if len(buf) == 1 {
			return Key{}, 0
		}
		switch buf[1] {
		case '[':
			if len(buf) == 2 {
				return Key{}, 0
			}
			// mouse SGR: ESC [ < b ; x ; y M/m
			if buf[2] == '<' {
				for i := 3; i < len(buf); i++ {
					if buf[i] == 'M' || buf[i] == 'm' {
						params := string(buf[3:i])
						var bcode, x, y int
						parts := splitParams(params)
						if len(parts) >= 3 {
							bcode, x, y = parts[0], parts[1], parts[2]
						}
						_ = x
						_ = y
						k := Key{Name: "mouse"}
						if buf[i] == 'M' {
							switch bcode {
							case 64:
								k.Wheel = -1
							case 65:
								k.Wheel = 1
							}
						}
						return k, i + 1
					}
				}
				return Key{}, 0
			}
			// CSI sequence: params then final byte 0x40-0x7e
			for i := 2; i < len(buf); i++ {
				c := buf[i]
				if c >= 0x40 && c <= 0x7e {
					params := splitParams(string(buf[2:i]))
					mod := 1
					if len(params) >= 2 {
						mod = params[1]
					}
					name := ""
					switch c {
					case 'A':
						name = "up"
					case 'B':
						name = "down"
					case 'C':
						name = "right"
					case 'D':
						name = "left"
					case 'H':
						name = "home"
					case 'F':
						name = "end"
					case 'Z':
						name = "shift+tab"
					case '~':
						if len(params) >= 1 {
							switch params[0] {
							case 1, 7:
								name = "home"
							case 4, 8:
								name = "end"
							case 5:
								name = "pgup"
							case 6:
								name = "pgdown"
							case 3:
								name = "delete"
							case 2:
								name = "insert"
							}
						}
					}
					if name == "" {
						return Key{Name: "unknown"}, i + 1
					}
					if mod == 2 || mod == 4 {
						name = "shift+" + name
					} else if mod == 5 {
						name = "ctrl+" + name
					} else if mod == 3 {
						name = "alt+" + name
					}
					return Key{Name: name}, i + 1
				}
			}
			return Key{}, 0
		case 'O':
			if len(buf) == 2 {
				return Key{}, 0
			}
			switch buf[2] {
			case 'A':
				return Key{Name: "up"}, 3
			case 'B':
				return Key{Name: "down"}, 3
			case 'C':
				return Key{Name: "right"}, 3
			case 'D':
				return Key{Name: "left"}, 3
			case 'H':
				return Key{Name: "home"}, 3
			case 'F':
				return Key{Name: "end"}, 3
			}
			return Key{Name: "unknown"}, 3
		default:
			// alt+key
			k, n := decodeKey(buf[1:])
			if n == 0 {
				return Key{}, 0
			}
			k.Name = "alt+" + k.Name
			return k, n + 1
		}
	}
	switch b {
	case '\r', '\n':
		return Key{Name: "enter"}, 1
	case '\t':
		return Key{Name: "tab"}, 1
	case 0x7f, 0x08:
		return Key{Name: "backspace"}, 1
	case ' ':
		return Key{Name: "space", Rune: ' '}, 1
	}
	if b < 0x20 {
		return Key{Name: "ctrl+" + string(rune('a'+b-1))}, 1
	}
	// utf8 rune
	r, size := decodeRune(buf)
	if size == 0 {
		return Key{}, 0
	}
	return Key{Name: string(r), Rune: r}, size
}

func decodeKeyFinal(buf []byte) (Key, int) {
	if buf[0] == 0x1b {
		if len(buf) == 1 {
			return Key{Name: "esc"}, 1
		}
		k, n := decodeKey(buf)
		if n == 0 {
			return Key{Name: "esc"}, 1
		}
		return k, n
	}
	k, n := decodeKey(buf)
	if n == 0 {
		return Key{Name: "unknown"}, len(buf)
	}
	return k, n
}

func decodeRune(buf []byte) (rune, int) {
	b := buf[0]
	var size int
	switch {
	case b < 0x80:
		return rune(b), 1
	case b&0xE0 == 0xC0:
		size = 2
	case b&0xF0 == 0xE0:
		size = 3
	case b&0xF8 == 0xF0:
		size = 4
	default:
		return rune(b), 1
	}
	if len(buf) < size {
		return 0, 0
	}
	r := rune(b & (0xFF >> (size + 1)))
	for i := 1; i < size; i++ {
		r = r<<6 | rune(buf[i]&0x3F)
	}
	return r, size
}

func splitParams(s string) []int {
	var out []int
	cur := 0
	has := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			cur = cur*10 + int(c-'0')
			has = true
		} else if c == ';' {
			out = append(out, cur)
			cur = 0
			has = false
		}
	}
	if has || len(out) > 0 {
		out = append(out, cur)
	}
	return out
}
