					} else if mod == 5 {
						name = "ctrl+" + name
					} else if mod == 3 {
						name = "alt+" + name
					}
					return Key{Name: name}, i + 1
				}
			}
			return Key{}, 0
		case 'O':
			if len(buf) == 2 {
				return Key{}, 0
			}
			switch buf[2] {
			case 'A':
				return Key{Name: "up"}, 3
			case 'B':
				return Key{Name: "down"}, 3
			case 'C':
				return Key{Name: "right"}, 3
			case 'D':
				return Key{Name: "left"}, 3
			case 'H':
				return Key{Name: "home"}, 3
			case 'F':
				return Key{Name: "end"}, 3
			}
			return Key{Name: "unknown"}, 3
		default:
			// alt+key
			k, n := decodeKey(buf[1:])
			if n == 0 {
				return Key{}, 0
			}
			k.Name = "alt+" + k.Name
			return k, n + 1
		}
	}
	switch b {
	case '\r', '\n':
		return Key{Name: "enter"}, 1
	case '\t':
		return Key{Name: "tab"}, 1
	case 0x7f, 0x08:
		return Key{Name: "backspace"}, 1
	case ' ':
		return Key{Name: "space", Rune: ' '}, 1
	}
	if b < 0x20 {
		return Key{Name: "ctrl+" + string(rune('a'+b-1))}, 1
	}
	// utf8 rune
	r, size := decodeRune(buf)
	if size == 0 {
		return Key{}, 0
	}
	return Key{Name: string(r), Rune: r}, size
}

func decodeKeyFinal(buf []byte) (Key, int) {
	if buf[0] == 0x1b {
		if len(buf) == 1 {
			return Key{Name: "esc"}, 1
		}
		k, n := decodeKey(buf)
		if n == 0 {
			return Key{Name: "esc"}, 1
		}
		return k, n
	}
	k, n := decodeKey(buf)
	if n == 0 {
		return Key{Name: "unknown"}, len(buf)
	}
	return k, n
}

func decodeRune(buf []byte) (rune, int) {
	b := buf[0]
	var size int
	switch {
	case b < 0x80:
		return rune(b), 1
	case b&0xE0 == 0xC0:
		size = 2
	case b&0xF0 == 0xE0:
		size = 3
	case b&0xF8 == 0xF0:
		size = 4
	default:
		return rune(b), 1
	}
	if len(buf) < size {
		return 0, 0
	}
	r := rune(b & (0xFF >> (size + 1)))
	for i := 1; i < size; i++ {
		r = r<<6 | rune(buf[i]&0x3F)
	}
	return r, size
}

func splitParams(s string) []int {
	var out []int
	cur := 0
	has := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			cur = cur*10 + int(c-'0')
			has = true
		} else if c == ';' {
			out = append(out, cur)
			cur = 0
			has = false
		}
	}
	if has || len(out) > 0 {
		out = append(out, cur)
	}
	return out
}
