}

// nodeJSON renders an item's value as indented JSON text.
func nodeJSON(it *item, printer jsonx.Printer) string {
	if it.text {
		return it.raw
	}
	n := it.node.Clone()
	n.Key = ""
	n.HasKey = false
	return printer.String(n)
