// Run starts the interactive viewer.
func Run(o Options) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "panic: could not open a new TTY: %v\n\ngoroutine 1 [running]:\nmain.main()\n", err)
		os.Exit(2)
	}
	fi, _ := os.Stdout.Stat()
	if fi == nil || fi.Mode()&os.ModeCharDevice == 0 {
		// Output is not a terminal: nothing to show.
		return
	}
	text := ""
	if o.ParseErr != nil {
		if pe, ok := o.ParseErr.(*jsonx.ParseError); ok {
			text = pe.Snippet
		} else {
			text = o.ParseErr.Error()
		}
	}
	u := &ui{opts: o, th: o.Theme, wrap: true, tty: tty, out: os.Stdout}
	u.doc = buildDoc(o.Nodes, text)
	if os.Getenv("FX_SHOW_SIZE") == "true" {
		u.showSizes = true
	}
	if os.Getenv("FX_LINE_NUMBERS") == "true" {
		u.showLines = true
	}
	if os.Getenv("FX_COLLAPSED") == "true" {
		for _, r := range u.doc.roots {
			setCollapsedRec(r, true)
		}
		u.doc.flatten()
	}
	u.loop()
}

func (u *ui) write(s string) { u.out.WriteString(s) }

func (u *ui) enter() (*termios, error) {
	old, err := makeRaw(u.tty.Fd())
	if err != nil {
		return nil, err
	}
	u.write("\x1b[?1049h\x1b[?25l")
	if os.Getenv("FX_NO_MOUSE") != "true" {
		u.write("\x1b[?1000h\x1b[?1006h")
	}
	return old, nil
}

func (u *ui) leave(old *termios) {
	if os.Getenv("FX_NO_MOUSE") != "true" {
		u.write("\x1b[?1006l\x1b[?1000l")
	}
	u.write("\x1b[?25h\x1b[?1049l")
	if old != nil {
		setTermios(u.tty.Fd(), old)
	}
}

func (u *ui) loop() {
	old, err := u.enter()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer u.leave(old)
	u.width, u.height = termSize(u.tty.Fd())
	resize := make(chan struct{}, 1)
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGWINCH)
	go func() {
		for range sig {
			select {
			case resize <- struct{}{}:
			default:
			}
		}
	}()
	kr := newKeyReader(u.tty)
	u.draw()
	for !u.quit {
		k, ok, resized := kr.read(resize)
		if !ok {
			return
		}
		if resized {
			u.width, u.height = termSize(u.tty.Fd())
			u.draw()
			continue
		}
		u.handleKey(k)
		if u.exitFn != nil {
			u.leave(old)
			u.exitFn()
			return
		}
		if !u.quit {
			u.draw()
		}
	}
}

// contentHeight is the number of rows available for the document.
func (u *ui) contentHeight() int {
	h := u.height - 1
	if u.bottomLine() != "" {
		h--
	}
	if h < 1 {
		h = 1
	}
	return h
}

func (u *ui) bottomLine() string {
	switch u.mode {
	case modeSearch:
		return "/" + u.input + cursorStyle.Render(" ")
	case modeGoto:
		return "@" + u.input + cursorStyle.Render(" ")
	case modeCommand:
		return ":" + u.input + cursorStyle.Render(" ")
	case modeYank:
		return "(y)value  (p)path  (k)key  (b)key+value"
	case modeSizes:
		return "(s)sizes  (l)line numbers"
	}
	if u.showSearch && u.searchRe != nil {
		left := "/" + u.searchStr + "/i"
		right := ""
		if len(u.matches) == 0 {
			right = "not found"
		} else {
			right = fmt.Sprintf("found: [%d/%d]", u.matchIdx+1, len(u.matches))
		}
		pad := u.width - runewidth.StringWidth(left) - runewidth.StringWidth(right)
		if pad < 1 {
			pad = 1
		}
		return left + strings.Repeat(" ", pad) + right
	}
	if u.status != "" {
		return u.status
	}
	return ""
}

func (u *ui) gutterWidth() int {
	if !u.showLines {
		return 0
	}
	return len(strconv.Itoa(u.doc.total)) + 2
}

// renderLine renders one visible line into physical rows.
func (u *ui) renderLine(idx int, l line) []string {
	it := l.it
	sl := &styledLine{}
	gutter := u.gutterWidth()
	if u.showLines {
		num := it.startLine + 1
		if l.end {
			num = it.endLine + 1
		}
		s := strconv.Itoa(num)
		sl.add(strings.Repeat(" ", gutter-2-len(s))+s, lineNumStyle)
		sl.add("  ", noStyle)
	}
	indent := it.depth * 2
	sl.add(strings.Repeat(" ", indent), noStyle)
	isCursor := idx == u.cursor
	if it.text {
		st := noStyle
		if isCursor {
			st = cursorStyle
		}
		sl.add(it.raw, st)
		return sl.render(u.width, false, 0)
	}
	n := it.node
	if l.end {
		br := "}"
		if n.Kind == jsonx.KindArray {
			br = "]"
		}
		if isCursor {
			sl.add(br, cursorStyle)
		} else {
			sl.add(br, u.th.Syntax)
		}
		if it.comma {
			sl.add(",", u.th.Syntax)
		}
		return sl.render(u.width, false, 0)
	}
	// key
	hasKey := n.HasKey
	if hasKey {
		u.addMatched(sl, n.Key, it, true, isCursor, u.th.Key)
		sl.add(": ", u.th.Syntax)
	}
	valueStyle := func(st theme.Style) theme.Style {
		if isCursor && !hasKey {
			return cursorStyle
		}
		return st
	}
	switch n.Kind {
	case jsonx.KindObject, jsonx.KindArray:
		open, close := "{", "}"
		if n.Kind == jsonx.KindArray {
			open, close = "[", "]"
		}
		if len(n.Children) == 0 {
			sl.add(open+close, valueStyle(u.th.Syntax))
		} else if it.collapsed {
			sl.add(open, valueStyle(u.th.Syntax))
			sl.add(preview(it), u.th.Preview)
			sl.add(close, u.th.Syntax)
		} else {
			sl.add(open, valueStyle(u.th.Syntax))
			if u.showSizes {
				cnt := len(n.Children)
				unit := "keys"
				if n.Kind == jsonx.KindArray {
					unit = "items"
					if cnt == 1 {
						unit = "item"
					}
				} else if cnt == 1 {
					unit = "key"
				}
				sl.add(fmt.Sprintf(" (%d %s)", cnt, unit), sizeStyle)
			}
			if it.comma {
				sl.add(",", u.th.Syntax)
			}
			return sl.render(u.width, false, 0)
		}
		if it.comma {
			sl.add(",", u.th.Syntax)
		}
		return sl.render(u.width, false, 0)
	}
	// primitive
	var st theme.Style
	switch n.Kind {
	case jsonx.KindString:
		st = u.th.String
	case jsonx.KindNumber:
		st = u.th.Number
	case jsonx.KindBool:
		st = u.th.Boolean
	case jsonx.KindNull:
		st = u.th.Null
	default:
		st = theme.Style{Codes: "38;5;255;48;5;196"}
	}
	u.addMatched(sl, n.Value, it, false, isCursor && !hasKey, st)
	if it.comma {
		sl.add(",", u.th.Syntax)
	}
	wrap := u.wrap && n.Kind == jsonx.KindString
	return sl.render(u.width, wrap, gutter+indent)
}

// addMatched adds a token, highlighting search matches.
func (u *ui) addMatched(sl *styledLine, text string, it *item, inKey bool, cursor bool, base theme.Style) {
	if cursor {
		base = cursorStyle
	}
	if u.searchRe == nil || len(u.matches) == 0 {
		sl.add(text, base)
		return
	}
	pos := 0
	for i, m := range u.matches {
		if m.it != it || m.inKey != inKey {
			continue
		}
		if m.start < pos {
			continue
		}
		sl.add(text[pos:m.start], base)
		st := matchStyle
		if i == u.matchIdx {
			st = cursorStyle
		}
		sl.add(text[m.start:m.stop], st)
		pos = m.stop
	}
	sl.add(text[pos:], base)
}

func (u *ui) draw() {
	var b strings.Builder
	b.WriteString("\x1b[H")
	rows := u.contentHeight()
	var body []string
	switch u.mode {
	case modeHelp:
		body = u.helpLines()
	case modePreview:
		body = u.previewLines()
	default:
		body = u.docLines(rows)
	}
	for i := 0; i < rows; i++ {
		if i < len(body) {
			b.WriteString(body[i])
		} else if u.mode == modeNormal || u.mode == modeSearch || u.mode == modeGoto || u.mode == modeCommand || u.mode == modeYank || u.mode == modeSizes {
			b.WriteString(tildeStyle.Render("~"))
		}
		b.WriteString("\x1b[K\r\n")
	}
	b.WriteString(u.statusBar())
	b.WriteString("\x1b[K")
	if bl := u.bottomLine(); bl != "" {
		b.WriteString("\r\n")
		b.WriteString(bl)
		b.WriteString("\x1b[K")
	}
	u.write(b.String())
}

// docLines renders the visible document rows, scrolling to keep the cursor visible.
func (u *ui) docLines(rows int) []string {
	lines := u.doc.lines
	if u.cursor >= len(lines) {
		u.cursor = len(lines) - 1
	}
	if u.cursor < 0 {
		u.cursor = 0
	}
	// render lines lazily from offset
	render := func(i int) []string { return u.renderLine(i, lines[i]) }
	if u.offset > u.cursor {
		u.offset = u.cursor
	}
	if u.offset < 0 {
		u.offset = 0
	}
	// ensure cursor line fully visible: compute rows used from offset to cursor
	for {
		used := 0
		for i := u.offset; i <= u.cursor && i < len(lines); i++ {
			used += len(render(i))
		}
		if used <= rows || u.offset >= u.cursor {
			break
		}
		u.offset++
	}
	var out []string
	for i := u.offset; i < len(lines) && len(out) < rows; i++ {
		out = append(out, render(i)...)
	}
	if len(out) > rows {
		out = out[:rows]
	}
	return out
}

func (u *ui) statusBar() string {
	left := ""
	right := ""
	if u.mode == modeHelp {
		return statusStyle.Render(padRight("", u.width))
	}
	if u.mode == modePreview {
		left = pathOf(u.previewIt)
		right = u.opts.FileName
	} else {
		if u.mode == modeGoto && len(u.gotoRes) > 0 {
			res := u.gotoRes[u.gotoIdx]
			var b strings.Builder
			posSet := map[int]bool{}
			for _, p := range res.pos {
				posSet[p] = true
			}
			for i := 0; i < len(res.path); i++ {
				if posSet[i] {
					b.WriteString(matchStyle.Render(res.path[i:i+1]) + "\x1b[" + statusStyle.Codes + "m")
				} else {
					b.WriteByte(res.path[i])
				}
			}
			left = b.String()
			return statusStyle.Render(left + strings.Repeat(" ", max(0, u.width-runewidth.StringWidth(res.path))))
		}
		if len(u.doc.lines) > 0 && u.cursor < len(u.doc.lines) {
			left = pathOf(u.doc.lines[u.cursor].it)
		}
		pct := u.percent()
		right = fmt.Sprintf("%d%%", pct)
		if u.opts.FileName != "" {
			right += " " + u.opts.FileName
		}
	}
	pad := u.width - runewidth.StringWidth(left) - runewidth.StringWidth(right)
	if pad < 1 {
		pad = 1
	}
	s := left + strings.Repeat(" ", pad) + right
	return statusStyle.Render(truncate(s, u.width))
}

func (u *ui) percent() int {
	if len(u.doc.lines) == 0 || u.doc.total == 0 {
		return 0
	}
	l := u.doc.lines[u.cursor]
	idx := l.it.startLine
	if l.end {
		idx = l.it.endLine
	}
	if idx == 0 {
		p := 100 / u.doc.total
		if p > 1 {
			p = 1
		}
		return p
	}
	return (idx + 1) * 100 / u.doc.total
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// ---- actions ----

func (u *ui) current() *item {
	if u.cursor < len(u.doc.lines) {
		return u.doc.lines[u.cursor].it
	}
	return nil
}

func (u *ui) pushHistory() {
	if it := u.current(); it != nil {
		if u.histPos < len(u.history) {
			u.history = u.history[:u.histPos]
		}
		u.history = append(u.history, it)
		u.histPos = len(u.history)
	}
}

func (u *ui) moveTo(it *item, end bool) {
	u.doc.expandTo(it)
	u.doc.flatten()
	idx := u.doc.lineIndex(it, end)
	if idx >= 0 {
		u.cursor = idx
	}
}

func (u *ui) handleKey(k Key) {
	if k.Name == "mouse" {
		if k.Wheel != 0 && (u.mode == modeNormal || u.mode == modeHelp || u.mode == modePreview) {
			u.scroll(k.Wheel * 3)
		}
		return
	}
	switch u.mode {
	case modeSearch, modeGoto, modeCommand:
		u.handleInput(k)
		return
	case modeYank:
		u.mode = modeNormal
		it := u.current()
		if it == nil {
			return
		}
		switch k.Name {
		case "y":
			u.yank(nodeJSON(it, jsonx.Printer{Theme: theme.Themes["0"], Inline: u.opts.Printer.Inline}))
		case "p":
			u.yank(pathOf(it))
		case "k":
			if it.node != nil && it.node.HasKey {
				u.yank(engine.Unquote(it.node.Key))
			}
		case "b":
			if it.node != nil && it.node.HasKey {
				u.yank(it.node.Key + ": " + nodeJSON(it, jsonx.Printer{Theme: theme.Themes["0"], Inline: u.opts.Printer.Inline}))
			} else {
				u.yank(nodeJSON(it, jsonx.Printer{Theme: theme.Themes["0"], Inline: u.opts.Printer.Inline}))
			}
		}
		return
	case modeSizes:
		u.mode = modeNormal
		switch k.Name {
		case "s":
			u.showSizes = !u.showSizes
		case "l":
			u.showLines = !u.showLines
		}
		return
	case modeHelp:
		switch k.Name {
		case "q", "?", "esc", "ctrl+c":
			u.mode = modeNormal
		case "j", "down":
			u.helpOffset++
		case "k", "up":
			if u.helpOffset > 0 {
				u.helpOffset--
			}
		case "pgdown", "space", "f":
			u.helpOffset += u.contentHeight()
		case "pgup", "b":
			u.helpOffset -= u.contentHeight()
			if u.helpOffset < 0 {
				u.helpOffset = 0
			}
		case "g", "home":
			u.helpOffset = 0
		case "G", "end":
			u.helpOffset = max(0, len(strings.Split(helpText, "\n"))-u.contentHeight())
		}
		return
	case modePreview:
		switch k.Name {
		case "q", "esc", "p", "ctrl+c", "enter":
			u.mode = modeNormal
		case "j", "down":
			u.previewOff++
		case "k", "up":
			if u.previewOff > 0 {
				u.previewOff--
			}
		case "pgdown", "space", "f":
			u.previewOff += u.contentHeight()
		case "pgup", "b":
			u.previewOff = max(0, u.previewOff-u.contentHeight())
		case "g", "home":
			u.previewOff = 0
		case "G", "end":
			u.previewOff = max(0, len(u.preview)-u.contentHeight())
		}
		if u.previewOff > max(0, len(u.preview)-1) {
			u.previewOff = max(0, len(u.preview)-1)
		}
		return
	}
	u.status = ""
	switch k.Name {
	case "q", "ctrl+c", "esc":
		if u.showSearch && k.Name == "esc" {
			u.showSearch = false
			return
		}
		u.quit = true
	case "ctrl+z":
		u.suspend()
	case "?":
		u.mode = modeHelp
		u.helpOffset = 0
	case "up", "k":
		u.moveCursor(-1)
	case "down", "j":
		u.moveCursor(1)
	case "pgup", "b":
		u.moveCursor(-u.contentHeight())
	case "pgdown", "space", "f":
		u.moveCursor(u.contentHeight())
	case "ctrl+u":
		u.moveCursor(-u.contentHeight() / 2)
	case "ctrl+d":
		u.moveCursor(u.contentHeight() / 2)
	case "g", "home":
		u.cursor = 0
		u.offset = 0
	case "G", "end":
		u.cursor = len(u.doc.lines) - 1
	case "J", "shift+down":
		u.sibling(1)
	case "K", "shift+up":
		u.sibling(-1)
	case "[":
		if u.histPos > 0 {
			if u.histPos == len(u.history) {
				u.pushHistory()
				u.histPos--
			}
			u.histPos--
			u.moveTo(u.history[u.histPos], false)
		}
	case "]":
		if u.histPos < len(u.history)-1 {
			u.histPos++
			u.moveTo(u.history[u.histPos], false)
		}
	case "right", "l", "enter":
		u.expand()
	case "left", "h", "backspace":
		u.collapse()
	case "L", "shift+right":
		if it := u.current(); it != nil {
			setCollapsedRec(it, false)
			u.doc.flatten()
		}
	case "H", "shift+left":
		if it := u.current(); it != nil {
			setCollapsedRec(it, true)
			u.doc.flatten()
			u.cursor = u.doc.lineIndex(it, false)
		}
	case "e":
		for _, r := range u.doc.roots {
			setCollapsedRec(r, false)
		}
		u.reflatten()
	case "E":
		for _, r := range u.doc.roots {
			setCollapsedRec(r, true)
		}
		u.reflatten()
	case "1", "2", "3", "4", "5", "6", "7", "8", "9":
		level, _ := strconv.Atoi(k.Name)
		for _, r := range u.doc.roots {
			collapseToLevel(r, level)
		}
		u.reflatten()
	case "/":
		u.mode = modeSearch
		u.input = ""
	case "n":
		u.nextMatch(1)
	case "N":
		u.nextMatch(-1)
	case "@":
		u.mode = modeGoto
		u.input = ""
		u.gotoRes = nil
	case "ctrl+g":
		u.gotoRef()
	case ":":
		u.mode = modeCommand
		u.input = ""
	case "y":
		u.mode = modeYank
	case "d":
		u.deleteNode()
	case "p":
		u.openPreview()
	case "P":
		if it := u.current(); it != nil {
			text := nodeJSON(it, jsonx.Printer{Theme: u.th, Inline: u.opts.Printer.Inline})
			u.exitFn = func() {
				fmt.Fprintln(os.Stdout, text)
			}
		}
	case "v":
		u.openEditor()
	case "z":
		u.wrap = !u.wrap
	case "s":
		u.mode = modeSizes
	}
}

// reflatten re-computes lines keeping the cursor on the same item if possible.
func (u *ui) reflatten() {
	cur := u.current()
	u.doc.flatten()
	if cur != nil {
		idx := u.doc.lineIndex(cur, false)
		for idx < 0 && cur.parent != nil {
			cur = cur.parent
			idx = u.doc.lineIndex(cur, false)
		}
		if idx >= 0 {
			u.cursor = idx
		}
	}
	if u.cursor >= len(u.doc.lines) {
		u.cursor = len(u.doc.lines) - 1
	}
}

func (u *ui) moveCursor(d int) {
	u.cursor += d
	if u.cursor < 0 {
		u.cursor = 0
	}
	if u.cursor >= len(u.doc.lines) {
		u.cursor = len(u.doc.lines) - 1
	}
}

func (u *ui) scroll(d int) {
	if u.mode == modeHelp {
		u.helpOffset = max(0, u.helpOffset+d)
		return
	}
	if u.mode == modePreview {
		u.previewOff = max(0, u.previewOff+d)
		return
	}
	u.offset += d
	if u.offset < 0 {
		u.offset = 0
	}
	if u.offset >= len(u.doc.lines) {
		u.offset = len(u.doc.lines) - 1
	}
	if u.cursor < u.offset {
		u.cursor = u.offset
	}
	rows := u.contentHeight()
	if u.cursor >= u.offset+rows {
		u.cursor = u.offset + rows - 1
		if u.cursor >= len(u.doc.lines) {
			u.cursor = len(u.doc.lines) - 1
		}
	}
}

func (u *ui) sibling(d int) {
	it := u.current()
	if it == nil || it.parent == nil {
		// top-level roots
		if it != nil {
			for i, r := range u.doc.roots {
				if r == it {
					j := i + d
					if j >= 0 && j < len(u.doc.roots) {
						u.cursor = u.doc.lineIndex(u.doc.roots[j], false)
					}
					return
				}
			}
		}
		return
	}
	j := it.index + d
	if j >= 0 && j < len(it.parent.children) {
		u.cursor = u.doc.lineIndex(it.parent.children[j], false)
	}
}

func (u *ui) expand() {
	l := u.doc.lines[u.cursor]
	it := l.it
	if l.end {
		return
	}
	if it.hasChildren() && it.collapsed {
		it.collapsed = false
		u.doc.flatten()
	}
}

func (u *ui) collapse() {
	l := u.doc.lines[u.cursor]
	it := l.it
	if l.end {
		it.collapsed = true
		u.doc.flatten()
		u.cursor = u.doc.lineIndex(it, false)
		return
	}
	if it.hasChildren() && !it.collapsed {
		it.collapsed = true
		u.doc.flatten()
		return
	}
	if it.parent != nil {
		p := it.parent
		p.collapsed = true
		u.doc.flatten()
		u.cursor = u.doc.lineIndex(p, false)
	}
}

func (u *ui) handleInput(k Key) {
	switch k.Name {
	case "esc", "ctrl+c":
		u.mode = modeNormal
		u.input = ""
		return
	case "enter":
		input := u.input
		m := u.mode
		u.mode = modeNormal
		switch m {
		case modeSearch:
			u.doSearch(input)
		case modeGoto:
			if len(u.gotoRes) > 0 {
				u.pushHistory()
				u.moveTo(u.gotoRes[u.gotoIdx].it, false)
			}
		case modeCommand:
			u.runCommand(input)
		}
		return
	case "backspace":
		if len(u.input) > 0 {
			rs := []rune(u.input)
			u.input = string(rs[:len(rs)-1])
		}
	case "ctrl+u":
		u.input = ""
	case "ctrl+w":
		s := strings.TrimRight(u.input, " ")
		if i := strings.LastIndex(s, " "); i >= 0 {
			u.input = s[:i+1]
		} else {
			u.input = ""
		}
	case "tab", "down", "ctrl+n":
		if u.mode == modeGoto && len(u.gotoRes) > 0 {
			u.gotoIdx = (u.gotoIdx + 1) % len(u.gotoRes)
			u.moveTo(u.gotoRes[u.gotoIdx].it, false)
		}
		return
	case "shift+tab", "up", "ctrl+p":
		if u.mode == modeGoto && len(u.gotoRes) > 0 {
			u.gotoIdx = (u.gotoIdx - 1 + len(u.gotoRes)) % len(u.gotoRes)
			u.moveTo(u.gotoRes[u.gotoIdx].it, false)
		}
		return
	default:
		if k.Rune != 0 {
			u.input += string(k.Rune)
		} else {
			return
		}
	}
	if u.mode == modeGoto {
		u.gotoRes = u.doc.fuzzyFind(u.input)
		u.gotoIdx = 0
		if len(u.gotoRes) > 0 {
			u.moveTo(u.gotoRes[0].it, false)
		}
	}
}

func (u *ui) doSearch(pattern string) {
	u.searchStr = pattern
	if pattern == "" {
		u.searchRe = nil
		u.matches = nil
		u.showSearch = false
		return
	}
	re, err := regexp.Compile("(?i)" + pattern)
	if err != nil {
		re, err = regexp.Compile("(?i)" + regexp.QuoteMeta(pattern))
		if err != nil {
			return
		}
	}
	u.searchRe = re
	u.matches = u.doc.search(re)
	u.matchIdx = 0
	u.showSearch = true
	if len(u.matches) > 0 {
		u.pushHistory()
		u.jumpToMatch()
	}
}

func (u *ui) nextMatch(d int) {
	if len(u.matches) == 0 {
		return
	}
	u.matchIdx = (u.matchIdx + d + len(u.matches)) % len(u.matches)
	u.showSearch = true
	u.jumpToMatch()
}

func (u *ui) jumpToMatch() {
	m := u.matches[u.matchIdx]
	u.moveTo(m.it, m.end)
}

func (u *ui) gotoRef() {
	it := u.current()
	if it == nil || it.text || it.node.Kind != jsonx.KindString {
		return
	}
	ref := engine.Unquote(it.node.Value)
	target := u.resolveRef(ref)
	if target != nil {
		u.pushHistory()
		u.moveTo(target, false)
	}
}

// resolveRef resolves JSON pointer style ("#/a/b") or fx path (".a.b", "a.b") references.
func (u *ui) resolveRef(ref string) *item {
	if len(u.doc.roots) == 0 {
		return nil
	}
	ref = strings.TrimPrefix(ref, "#")
	var segs []string
	if strings.HasPrefix(ref, "/") {
		for _, s := range strings.Split(strings.TrimPrefix(ref, "/"), "/") {
			s = strings.ReplaceAll(strings.ReplaceAll(s, "~1", "/"), "~0", "~")
			segs = append(segs, s)
		}
	} else {
		r := strings.TrimPrefix(ref, ".")
		r = strings.ReplaceAll(r, "[", ".")
		r = strings.ReplaceAll(r, "]", "")
		r = strings.ReplaceAll(r, "\"", "")
		for _, s := range strings.Split(r, ".") {
			if s != "" {
				segs = append(segs, s)
			}
		}
	}
	cur := u.doc.roots[0]
	for _, s := range segs {
		found := false
		for _, c := range cur.children {
			if cur.node.Kind == jsonx.KindArray {
				if strconv.Itoa(c.index) == s {
					cur = c
					found = true
					break
				}
			} else if engine.Unquote(c.node.Key) == s {
				cur = c
				found = true
				break
			}
		}
		if !found {
			return nil
		}
	}
	return cur
}

func (u *ui) deleteNode() {
	it := u.current()
	if it == nil || it.text {
		return
	}
	if it.parent == nil {
		for i, r := range u.doc.roots {
			if r == it {
				u.doc.roots = append(u.doc.roots[:i], u.doc.roots[i+1:]...)
				break
			}
		}
	} else {
		p := it.parent
		p.children = append(p.children[:it.index], p.children[it.index+1:]...)
		p.node.Children = append(p.node.Children[:it.index], p.node.Children[it.index+1:]...)
		p.node.Reindex()
		for i, c := range p.children {
			c.index = i
			c.comma = i < len(p.children)-1
		}
	}
	u.doc.number()
	u.doc.flatten()
	if u.cursor >= len(u.doc.lines) {
		u.cursor = len(u.doc.lines) - 1
	}
	if u.cursor < 0 {
		u.cursor = 0
	}
}

func (u *ui) openPreview() {
	it := u.current()
	if it == nil {
		return
	}
	text := nodeJSON(it, jsonx.Printer{Theme: u.th, Inline: u.opts.Printer.Inline})
	if !it.text && it.node.Kind == jsonx.KindString {
		text = engine.Unquote(it.node.Value)
	}
	u.preview = strings.Split(text, "\n")
	u.previewOff = 0
	u.previewIt = it
	u.mode = modePreview
}

func (u *ui) previewLines() []string {
	var out []string
	rows := u.contentHeight()
	for i := u.previewOff; i < len(u.preview) && len(out) < rows; i++ {
		sl := &styledLine{}
		sl.add(u.preview[i], noStyle)
		out = append(out, sl.renderANSI(u.width, u.wrap)...)
	}
	return out
}

// renderANSI renders a line that may already contain escape codes: wrap by plain width only.
func (sl *styledLine) renderANSI(width int, wrap bool) []string {
	text := sl.spans[0].text
	plain := stripANSI(text)
	if !wrap || runewidth.StringWidth(plain) <= width {
		return []string{text}
	}
	// wrap plain text (loses colors for wrapped long lines)
	var out []string
	var cur strings.Builder
	col := 0
	for _, r := range plain {
		w := runewidth.RuneWidth(r)
		if col+w > width {
			out = append(out, cur.String())
			cur.Reset()
			col = 0
		}
		cur.WriteRune(r)
		col += w
	}
	out = append(out, cur.String())
	return out
}

var ansiRe = regexp.MustCompile("\x1b\\[[0-9;]*m")

func stripANSI(s string) string { return ansiRe.ReplaceAllString(s, "") }

func (u *ui) runCommand(cmd string) {
	cmd = strings.TrimSpace(cmd)
	if cmd == "" {
		return
	}
	if len(u.doc.roots) == 0 || u.doc.roots[0].text {
		return
	}
	data := []byte(jsonx.Compact(u.doc.roots[0].node))
	r, res, ok := engine.Evaluate(data, nil, cmd)
	if !ok {
		u.status = "error"
		return
	}
	var text string
	switch t := res.(type) {
	case string:
		text = t
	default:
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					text = "error"
				}
			}()
			n := engine.Stringify(r, res)
			text = u.opts.Printer.String(n)
		}()
	}
	u.preview = strings.Split(text, "\n")
	u.previewOff = 0
	u.previewIt = u.current()
	u.mode = modePreview
}

func (u *ui) yank(text string) {
	// OSC 52 clipboard
	enc := base64.StdEncoding.EncodeToString([]byte(text))
	u.write("\x1b]52;c;" + enc + "\x07")
	for _, c := range [][]string{{"pbcopy"}, {"xclip", "-selection", "clipboard"}, {"xsel", "--clipboard", "--input"}, {"wl-copy"}} {
		if _, err := exec.LookPath(c[0]); err == nil {
			cmd := exec.Command(c[0], c[1:]...)
			cmd.Stdin = strings.NewReader(text)
			cmd.Run()
			break
		}
	}
}

func (u *ui) openEditor() {
	it := u.current()
	if it == nil {
		return
	}
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = "vi"
	}
	f, err := os.CreateTemp("", "fx-*.json")
	if err != nil {
		return
	}
	f.WriteString(nodeJSON(it, jsonx.Printer{Theme: theme.Themes["0"], Inline: u.opts.Printer.Inline}))
	f.Close()
	old, _ := getTermios(u.tty.Fd())
	u.leave(old)
	cmd := exec.Command("sh", "-c", editor+" "+f.Name())
	cmd.Stdin = u.tty
	cmd.Stdout = u.tty
	cmd.Stderr = u.tty
	cmd.Run()
	os.Remove(f.Name())
	u.enter()
}

func (u *ui) suspend() {
	old, _ := getTermios(u.tty.Fd())
	u.leave(old)
	signal.Reset(syscall.SIGTSTP)
	syscall.Kill(0, syscall.SIGTSTP)
	u.enter()
	u.width, u.height = termSize(u.tty.Fd())
}

const helpText = `
  Key Bindings
  ────────────────────────────────────────

  Navigation
    up, k                 up
    down, j               down
    pgup, b               page up
    pgdown, space, f      page down
    ctrl+u                half page up
    ctrl+d                half page down
    g, home               goto top
    G, end                goto bottom
    J, shift+down         next sibling
    K, shift+up           previous sibling
    [                     go back
    ]                     go forward

  Expand / Collapse
    right, l, enter       expand
    left, h, backspace    collapse
    L, shift+right        expand recursively
    H, shift+left         collapse recursively
    e                     expand all
    E                     collapse all
    1-9                   collapse to nth level

  Search
    /                     search regexp
    n                     next search result
    N                     prev search result
    @                     goto symbol
    ctrl+g                goto ref

  Actions
    y                     yank/copy
    d                     delete node
    p                     preview node
    P                     print to stdout
    v                     open in editor

  View
    z                     toggle strings wrap
    s                     show sizes/line numbers

  Other
    ?                     show help
    :                     open command line
    q, ctrl+c, esc        exit program
    ctrl+z                suspend program

  ────────────────────────────────────────
  Press q or ? to close`

func (u *ui) helpLines() []string {
	lines := strings.Split(helpText, "\n")
	rows := u.contentHeight()
	maxOff := max(0, len(lines)-rows)
	if u.helpOffset > maxOff {
		u.helpOffset = maxOff
	}
	var out []string
	for i := u.helpOffset; i < len(lines) && len(out) < rows; i++ {
		out = append(out, truncate(lines[i], u.width))
	}
	return out
}
