package tui

import (
	"strings"

	"fx/internal/theme"

	"github.com/mattn/go-runewidth"
)

type span struct {
	text  string
	style theme.Style
}

type styledLine struct {
	spans []span
}

func (sl *styledLine) add(text string, st theme.Style) {
	if text == "" {
		return
	}
	sl.spans = append(sl.spans, span{text: text, style: st})
}

func (sl *styledLine) width() int {
	w := 0
	for _, s := range sl.spans {
		w += runewidth.StringWidth(s.text)
	}
	return w
}

// render produces physical lines of at most width columns. When wrap is false
// the line is truncated. Continuation lines are prefixed with contIndent spaces.
func (sl *styledLine) render(width int, wrap bool, contIndent int) []string {
	if width <= 0 {
		width = 1
	}
	var out []string
	var cur strings.Builder
	col := 0
	first := true
	flush := func() {
		out = append(out, cur.String())
		cur.Reset()
		col = 0
	}
	truncated := false
	for _, sp := range sl.spans {
		if truncated {
			break
		}
		var seg strings.Builder
		open := func() {
			if sp.style.Codes != "" && theme.ColorEnabled {
				seg.WriteString("\x1b[" + sp.style.Codes + "m")
			}
		}
		closeSeg := func() {
			if seg.Len() > 0 {
				if sp.style.Codes != "" && theme.ColorEnabled {
					seg.WriteString("\x1b[0m")
				}
				cur.WriteString(seg.String())
				seg.Reset()
			}
		}
		open()
		hasContent := false
		for _, r := range sp.text {
			w := runewidth.RuneWidth(r)
			if w == 0 {
				seg.WriteRune(r)
				continue
			}
			if col+w > width {
				if !wrap {
					truncated = true
					break
				}
				if hasContent {
					closeSeg()
				} else {
					seg.Reset()
				}
				flush()
				first = false
				if contIndent > 0 && contIndent < width {
					cur.WriteString(strings.Repeat(" ", contIndent))
					col = contIndent
				}
				open()
				hasContent = false
			}
			seg.WriteRune(r)
			hasContent = true
			col += w
		}
		if hasContent {
			closeSeg()
		} else {
			seg.Reset()
		}
	}
	_ = first
	flush()
	return out
}

func padRight(s string, width int) string {
	w := runewidth.StringWidth(s)
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func truncate(s string, width int) string {
	if runewidth.StringWidth(s) <= width {
		return s
	}
	return runewidth.Truncate(s, width, "")
}
