package gol

import (
	"math/rand"
	"os"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

func termSize() (int, int) {
	var ws struct{ Row, Col, X, Y uint16 }
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), 0x5413, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 || ws.Col == 0 || ws.Row == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

// Run plays Conway's game of life until a key is pressed.
func Run() {
	cols, rows := termSize()
	w, h := cols, rows*2
	grid := make([][]bool, h)
	for y := range grid {
		grid[y] = make([]bool, w)
	}
	rand.Seed(time.Now().UnixNano())
	glider := [][2]int{{1, 0}, {2, 1}, {0, 2}, {1, 2}, {2, 2}}
	for i := 0; i < (w*h)/400+3; i++ {
		ox, oy := rand.Intn(w), rand.Intn(h)
		for _, p := range glider {
			grid[(oy+p[1])%h][(ox+p[0])%w] = true
		}
	}
	for i := 0; i < (w*h)/40; i++ {
		grid[rand.Intn(h)][rand.Intn(w)] = true
	}

	// raw mode for key detection
	var old syscall.Termios
	rawOK := false
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err == nil {
		if _, _, e := syscall.Syscall(syscall.SYS_IOCTL, tty.Fd(), 0x5401, uintptr(unsafe.Pointer(&old))); e == 0 {
			raw := old
			raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.ISIG
			raw.Cc[syscall.VMIN] = 1
			raw.Cc[syscall.VTIME] = 0
			syscall.Syscall(syscall.SYS_IOCTL, tty.Fd(), 0x5402, uintptr(unsafe.Pointer(&raw)))
			rawOK = true
		}
	}
	keys := make(chan struct{}, 1)
	if tty != nil {
		go func() {
			b := make([]byte, 16)
			for {
				n, err := tty.Read(b)
				if err != nil {
					return
				}
				if n > 0 {
					keys <- struct{}{}
					return
				}
			}
		}()
	}
	out := os.Stdout
	out.WriteString("\x1b[2J\x1b[?25l\x1b[H")
	defer func() {
		out.WriteString("\x1b[?25h\x1b[2J\x1b[H")
		if rawOK {
			syscall.Syscall(syscall.SYS_IOCTL, tty.Fd(), 0x5402, uintptr(unsafe.Pointer(&old)))
		}
	}()
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	for {
		var b strings.Builder
		b.WriteString("\x1b[H")
		for r := 0; r < rows; r++ {
			for x := 0; x < w; x++ {
				top := grid[2*r][x]
				bot := 2*r+1 < h && grid[2*r+1][x]
				switch {
				case top && bot:
					b.WriteString("█")
				case top:
					b.WriteString("▀")
				case bot:
					b.WriteString("▄")
				default:
					b.WriteByte(' ')
				}
			}
			if r < rows-1 {
				b.WriteString("\r\n")
			}
		}
		out.WriteString(b.String())
		grid = step(grid, w, h)
		select {
		case <-keys:
			return
		case <-ticker.C:
		}
	}
}

func step(g [][]bool, w, h int) [][]bool {
	ng := make([][]bool, h)
	for y := 0; y < h; y++ {
		ng[y] = make([]bool, w)
		for x := 0; x < w; x++ {
			n := 0
			for dy := -1; dy <= 1; dy++ {
				for dx := -1; dx <= 1; dx++ {
					if dx == 0 && dy == 0 {
						continue
					}
					yy := (y + dy + h) % h
					xx := (x + dx + w) % w
					if g[yy][xx] {
						n++
					}
				}
			}
			ng[y][x] = n == 3 || (n == 2 && g[y][x])
		}
	}
	return ng
}
